def _task1_affinity_offset_slices(shape: tuple[int, int, int],
                                  offset_zyx: tuple[int, int, int]) -> tuple[tuple[slice, ...], tuple[slice, ...]]:
    """Return source/destination slices for one directed 3D affinity offset."""
    src: list[slice] = []
    dst: list[slice] = []
    for dim, delta in zip(shape, offset_zyx):
        if abs(int(delta)) >= int(dim):
            raise ValueError(f"affinity offset {offset_zyx} is invalid for shape {shape}")
        if int(delta) > 0:
            src.append(slice(0, -int(delta)))
            dst.append(slice(int(delta), None))
        elif int(delta) < 0:
            src.append(slice(-int(delta), None))
            dst.append(slice(0, int(delta)))
        else:
            src.append(slice(None))
            dst.append(slice(None))
    return tuple(src), tuple(dst)


def _task1_v253_affinity13_edge_counts(probs: np.ndarray,
                                        *,
                                        support_threshold: float,
                                        affinity_threshold: float) -> dict[str, Any]:
    """Count valid and joined V253 affinity13 graph edges before graph decode.

    Raises:
        ValueError: `probs`가 V253 18채널 확률 텐서가 아니거나 NaN/Inf를 포함할 때.
    """
    arr = np.asarray(probs, dtype=np.float32)
    expected_channels = 5 + len(TASK1_V252_AFFINITY13_OFFSETS)
    # [QC][Invariant:channel_order]
    # V253 decoder는 [support, exterior, CFS, seed_center, seed_body, 13 affinity] 순서를 전제로 한다.
    # 이 순서가 깨지면 edge cap이 실제 decoder graph와 다른 대상을 세어 hang/metric 오판을 만들 수 있다.
    if arr.ndim != 4 or int(arr.shape[0]) != int(expected_channels):
        raise ValueError(f"V253 edge count expects [{expected_channels},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V253 edge count received NaN/Inf probabilities")
    support = arr[TASK1_V252_BASE_CHANNELS["support"]] >= float(support_threshold)
    affinity = np.clip(arr[5:], 0.0, 1.0)
    shape = tuple(int(v) for v in support.shape)
    valid_edges = 0
    joined_edges = 0
    per_offset: list[dict[str, Any]] = []
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(shape, offset)
        edge_valid = support[src_sl] & support[dst_sl]
        edge_join = edge_valid & (affinity[i][src_sl] >= float(affinity_threshold))
        valid_count = int(edge_valid.sum())
        joined_count = int(edge_join.sum())
        valid_edges += valid_count
        joined_edges += joined_count
        per_offset.append({
            "offset_zyx": [int(v) for v in offset],
            "valid_edges": int(valid_count),
            "joined_edges": int(joined_count),
        })
    return {
        "support_voxels": int(support.sum()),
        "valid_affinity_edges": int(valid_edges),
        "joined_affinity_edges": int(joined_edges),
        "affinity_threshold": float(affinity_threshold),
        "per_offset": per_offset,
    }


def _probability_threshold_to_logit(threshold: float, *, name: str) -> float:
    """Convert a Bernoulli probability threshold to the equivalent logit threshold."""
    value = float(threshold)
    if not 0.0 < value < 1.0:
        raise ValueError(f"{name} must be in (0, 1), got {threshold}")
    return float(np.log(value / (1.0 - value)))


def _task1_v253_affinity13_edge_counts_from_logits(logits: np.ndarray,
                                                   *,
                                                   support_threshold: float,
                                                   affinity_threshold: float) -> dict[str, Any]:
    """Count V253 affinity13 graph edges directly from logits.

    Raises:
        ValueError: `logits`가 V253 18채널 logit 텐서가 아니거나 NaN/Inf를 포함할 때.
    """
    arr = np.asarray(logits)
    expected_channels = 5 + len(TASK1_V252_AFFINITY13_OFFSETS)
    # [QC][Invariant:threshold_equivalence]
    # sigmoid(logit) >= p 는 logit >= log(p/(1-p))와 동치다. learned eval에서는
    # cap 초과 ROI를 확률 텐서/graph로 확장하기 전에 raw logit에서 걸러야 CPU/RAM 병목을 막을 수 있다.
    if arr.ndim != 4 or int(arr.shape[0]) != int(expected_channels):
        raise ValueError(f"V253 raw edge count expects [{expected_channels},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V253 raw edge count received NaN/Inf logits")
    support_logit_threshold = _probability_threshold_to_logit(support_threshold, name="support_threshold")
    affinity_logit_threshold = _probability_threshold_to_logit(affinity_threshold, name="affinity_threshold")
    support = arr[TASK1_V252_BASE_CHANNELS["support"]] >= support_logit_threshold
    shape = tuple(int(v) for v in support.shape)
    valid_edges = 0
    joined_edges = 0
    per_offset: list[dict[str, Any]] = []
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(shape, offset)
        edge_valid = support[src_sl] & support[dst_sl]
        edge_join = edge_valid & (arr[5 + i][src_sl] >= affinity_logit_threshold)
        valid_count = int(edge_valid.sum())
        joined_count = int(edge_join.sum())
        valid_edges += valid_count
        joined_edges += joined_count
        per_offset.append({
            "offset_zyx": [int(v) for v in offset],
            "valid_edges": int(valid_count),
            "joined_edges": int(joined_count),
        })
    return {
        "support_voxels": int(support.sum()),
        "valid_affinity_edges": int(valid_edges),
        "joined_affinity_edges": int(joined_edges),
        "affinity_threshold": float(affinity_threshold),
        "per_offset": per_offset,
    }


def _task1_v255_mutex13_edge_counts(probs: np.ndarray,
                                    *,
                                    support_threshold: float,
                                    affinity_threshold: float,
                                    mutex_threshold: float = 0.5) -> dict[str, Any]:
    """Count V255 graph edges using attractive + repulsive mutex probabilities."""
    arr = np.asarray(probs, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V255 edge count expects [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V255 edge count received NaN/Inf probabilities")
    support = arr[TASK1_V252_BASE_CHANNELS["support"]] >= float(support_threshold)
    attractive = np.clip(arr[TASK1_V255_ATTRACTIVE_START:TASK1_V255_REPULSIVE_START], 0.0, 1.0)
    repulsive = np.clip(arr[TASK1_V255_REPULSIVE_START:], 0.0, 1.0)
    shape = tuple(int(v) for v in support.shape)
    valid_edges = 0
    joined_edges = 0
    veto_edges = 0
    per_offset: list[dict[str, Any]] = []
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(shape, offset)
        edge_valid = support[src_sl] & support[dst_sl]
        edge_veto = edge_valid & (repulsive[i][src_sl] >= float(mutex_threshold))
        edge_join = edge_valid & (attractive[i][src_sl] >= float(affinity_threshold)) & ~edge_veto
        valid_count = int(edge_valid.sum())
        joined_count = int(edge_join.sum())
        veto_count = int(edge_veto.sum())
        valid_edges += valid_count
        joined_edges += joined_count
        veto_edges += veto_count
        per_offset.append({
            "offset_zyx": [int(v) for v in offset],
            "valid_edges": valid_count,
            "joined_edges": joined_count,
            "mutex_veto_edges": veto_count,
        })
    return {
        "support_voxels": int(support.sum()),
        "valid_affinity_edges": int(valid_edges),
        "joined_affinity_edges": int(joined_edges),
        "mutex_veto_edges": int(veto_edges),
        "affinity_threshold": float(affinity_threshold),
        "mutex_threshold": float(mutex_threshold),
        "per_offset": per_offset,
    }


def _task1_v255_mutex13_edge_counts_from_logits(logits: np.ndarray,
                                                *,
                                                support_threshold: float,
                                                affinity_threshold: float,
                                                mutex_threshold: float = 0.5) -> dict[str, Any]:
    """Count V255 graph edges directly from logits before probability expansion."""
    arr = np.asarray(logits)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V255 raw edge count expects [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V255 raw edge count received NaN/Inf logits")
    support_logit_threshold = _probability_threshold_to_logit(support_threshold, name="support_threshold")
    affinity_logit_threshold = _probability_threshold_to_logit(affinity_threshold, name="affinity_threshold")
    mutex_logit_threshold = _probability_threshold_to_logit(mutex_threshold, name="mutex_threshold")
    support = arr[TASK1_V252_BASE_CHANNELS["support"]] >= support_logit_threshold
    shape = tuple(int(v) for v in support.shape)
    valid_edges = 0
    joined_edges = 0
    veto_edges = 0
    per_offset: list[dict[str, Any]] = []
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(shape, offset)
        edge_valid = support[src_sl] & support[dst_sl]
        edge_veto = edge_valid & (arr[TASK1_V255_REPULSIVE_START + i][src_sl] >= mutex_logit_threshold)
        edge_join = edge_valid & (arr[TASK1_V255_ATTRACTIVE_START + i][src_sl] >= affinity_logit_threshold) & ~edge_veto
        valid_count = int(edge_valid.sum())
        joined_count = int(edge_join.sum())
        veto_count = int(edge_veto.sum())
        valid_edges += valid_count
        joined_edges += joined_count
        veto_edges += veto_count
        per_offset.append({
            "offset_zyx": [int(v) for v in offset],
            "valid_edges": valid_count,
            "joined_edges": joined_count,
            "mutex_veto_edges": veto_count,
        })
    return {
        "support_voxels": int(support.sum()),
        "valid_affinity_edges": int(valid_edges),
        "joined_affinity_edges": int(joined_edges),
        "mutex_veto_edges": int(veto_edges),
        "affinity_threshold": float(affinity_threshold),
        "mutex_threshold": float(mutex_threshold),
        "per_offset": per_offset,
    }


def compute_task1_v252_oracle_target(inst_roi: np.ndarray,
                                     spacing_zyx: tuple[float, float, float],
                                     *,
                                     exterior_mm: float = 3.0,
                                     seed_radius_mm: float = 2.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Build a V252 18-channel oracle target with 26-neighborhood affinity.

    [AUDIT][Risk:High][Scope:v252_oracle_contract]
    V251 short x/y/z affinity failed on case003 because valid GT fragments can
    be one 26-connected object but two 6-connected objects. V252 therefore uses
    13 directed offsets, the undirected half of the 26-neighborhood, so the
    decoder can reproduce the annotation topology before any learned training.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V252 target: {spacing_zyx}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = inst > 0
    target = np.zeros((5 + len(TASK1_V252_AFFINITY13_OFFSETS), *inst.shape), dtype=np.float32)
    target[TASK1_V252_BASE_CHANNELS["support"]] = support.astype(np.float32)
    if support.any():
        exterior = ndi.distance_transform_edt(~support, sampling=spacing_zyx) <= float(exterior_mm)
        target[TASK1_V252_BASE_CHANNELS["exterior_context"]] = (exterior & ~support).astype(np.float32)
        ids = [int(v) for v in np.unique(inst) if int(v) > 0]
        target[TASK1_V252_BASE_CHANNELS["fracture_surface"]] = get_contact_surface_regions(
            inst,
            contact_radius=1,
            surface_erosion_radius=1,
            groups={1: ids},
        ).astype(np.float32)
        for fragment_id in ids:
            center, body = _task1_v251_fragment_seed_body(
                inst == int(fragment_id),
                spacing_zyx,
                radius_mm=seed_radius_mm,
            )
            target[TASK1_V252_BASE_CHANNELS["seed_center"]] = np.maximum(
                target[TASK1_V252_BASE_CHANNELS["seed_center"]],
                center,
            )
            target[TASK1_V252_BASE_CHANNELS["seed_body"]] = np.maximum(
                target[TASK1_V252_BASE_CHANNELS["seed_body"]],
                body,
            )
        for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
            src_sl, dst_sl = _task1_affinity_offset_slices(inst.shape, offset)
            a = inst[src_sl]
            b = inst[dst_sl]
            same_fragment = (a > 0) & (b > 0) & (a == b)
            target[5 + i][src_sl] = same_fragment.astype(np.float32)

    seed_cc, seed_n = ndi.label(target[TASK1_V252_BASE_CHANNELS["seed_body"]] >= 0.5)
    fragment_count = int(len([v for v in np.unique(inst) if int(v) > 0]))
    audit = {
        "contract": "task1_v252_oracle_target_affinity13_v1",
        "channels": dict(TASK1_V252_CHANNELS),
        "affinity_offsets_zyx": [list(v) for v in TASK1_V252_AFFINITY13_OFFSETS],
        "shape": [int(v) for v in inst.shape],
        "fragment_count": fragment_count,
        "support_voxels": int(support.sum()),
        "fracture_surface_voxels": int(target[TASK1_V252_BASE_CHANNELS["fracture_surface"]].sum()),
        "seed_body_voxels": int(target[TASK1_V252_BASE_CHANNELS["seed_body"]].sum()),
        "seed_components": int(seed_n),
        "one_seed_component_per_fragment": bool(int(seed_n) == int(fragment_count)),
        "affinity_same_edge_voxels": int(target[5:].sum()),
    }
    if support.any() and not audit["one_seed_component_per_fragment"]:
        # [QC][FailFast:v252_seed_topology]
        # 13방향 affinity는 support 연결을 해결하지만 seed component 수가 GT
        # fragment 수와 다르면 decoder/training contract가 여전히 불완전하다.
        raise ValueError(
            "V252 oracle target seed topology failed: "
            f"seed_components={seed_n}, fragment_count={fragment_count}"
        )
    return target, audit


def compute_task1_v255_oracle_target(inst_roi: np.ndarray,
                                     spacing_zyx: tuple[float, float, float],
                                     *,
                                     exterior_mm: float = 3.0,
                                     seed_radius_mm: float = 2.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V255 oracle target with attractive affinity and repulsive mutex heads.

    [AUDIT][Risk:High][Scope:v255_oracle_contract]
    V254 failed because different-fragment/contact edges still scored as joined
    at the fixed 0.50 affinity threshold. V255 adds a decoder-facing mutex head:
    an edge joins only when same-fragment attraction is high and contact
    repulsion is low.
    """
    base_target, base_audit = compute_task1_v252_oracle_target(
        inst_roi,
        spacing_zyx,
        exterior_mm=exterior_mm,
        seed_radius_mm=seed_radius_mm,
    )
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    target = np.zeros((TASK1_V255_OUTPUT_CHANNELS, *inst.shape), dtype=np.float32)
    target[: base_target.shape[0]] = base_target
    mutex_edges = 0
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(inst.shape, offset)
        a = inst[src_sl]
        b = inst[dst_sl]
        a_fg = (a > 0) & (a <= 150)
        b_fg = (b > 0) & (b <= 150)
        same_anatomy = a_fg & b_fg & (((a - 1) // 50) == ((b - 1) // 50))
        different_fragment = same_anatomy & (a != b)
        target[TASK1_V255_REPULSIVE_START + i][src_sl] = different_fragment.astype(np.float32)
        mutex_edges += int(different_fragment.sum())
    audit = dict(base_audit)
    audit.update({
        "contract": "task1_v255_oracle_target_mutex13_seed_healed_v1",
        "channels": dict(TASK1_V255_CHANNELS),
        "mutex_contact_edge_voxels": int(mutex_edges),
        "output_channels": int(TASK1_V255_OUTPUT_CHANNELS),
    })
    return target, audit


def compute_task1_v273_no_contact_pairwise_oracle_target(
    inst_roi: np.ndarray,
    spacing_zyx: tuple[float, float, float],
    *,
    seed_radius_mm: float = 2.5,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V273 no-contact pairwise join/cut oracle target.

    [AUDIT][Risk:Blocker][Scope:v273_contact_removed_boundary_exact]
    Contact scalar supervision is removed from the active path. V272 showed that
    marker watershed can recover fragment count but still fail fracture-boundary
    topology. V273 therefore makes the decoder-facing target the boundary itself:
    each local edge is join if both voxels are the same GT fragment, cut if both
    are foreground but different fragments. No contact/fracture probability is
    produced or consumed.

    [QC][Invariant:channel_order]
    Output is `[28,Z,Y,X]`: support, seed_body, 13 join logits/probabilities, 13
    cut logits/probabilities. Offsets reuse the V252 13 directed half-neighborhood.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V273 target: {spacing_zyx}")
    if float(seed_radius_mm) <= 0.0:
        raise ValueError(f"seed_radius_mm must be > 0, got {seed_radius_mm}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = (inst > 0) & (inst <= 150)
    target = np.zeros((TASK1_V273_OUTPUT_CHANNELS, *inst.shape), dtype=np.float32)
    target[TASK1_V273_BASE_CHANNELS["support"]] = support.astype(np.float32)
    ids = [int(v) for v in np.unique(inst) if int(v) > 0]
    for fragment_id in ids:
        _center, body = _task1_v251_fragment_seed_body(
            inst == int(fragment_id),
            spacing_zyx,
            radius_mm=seed_radius_mm,
        )
        target[TASK1_V273_BASE_CHANNELS["seed_body"]] = np.maximum(
            target[TASK1_V273_BASE_CHANNELS["seed_body"]],
            body.astype(np.float32, copy=False),
        )
    join_edges = 0
    cut_edges = 0
    valid_edges = 0
    per_offset: list[dict[str, Any]] = []
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(inst.shape, offset)
        a = inst[src_sl]
        b = inst[dst_sl]
        edge_valid = (a > 0) & (b > 0)
        edge_join = edge_valid & (a == b)
        edge_cut = edge_valid & (a != b)
        target[TASK1_V273_JOIN_START + i][src_sl] = edge_join.astype(np.float32)
        target[TASK1_V273_CUT_START + i][src_sl] = edge_cut.astype(np.float32)
        valid_count = int(edge_valid.sum())
        join_count = int(edge_join.sum())
        cut_count = int(edge_cut.sum())
        valid_edges += valid_count
        join_edges += join_count
        cut_edges += cut_count
        per_offset.append({
            "offset_zyx": [int(v) for v in offset],
            "valid_edges": int(valid_count),
            "join_edges": int(join_count),
            "cut_edges": int(cut_count),
        })
    seed_cc, seed_n = ndi.label(target[TASK1_V273_BASE_CHANNELS["seed_body"]] >= 0.5)
    fragment_count = int(len(ids))
    audit = {
        "contract": "task1_v273_no_contact_pairwise_join_cut_oracle_target_v1",
        "channels": dict(TASK1_V273_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "fragment_count": int(fragment_count),
        "support_voxels": int(support.sum()),
        "seed_body_voxels": int(target[TASK1_V273_BASE_CHANNELS["seed_body"]].sum()),
        "seed_components": int(seed_n),
        "one_seed_component_per_fragment": bool(int(seed_n) == int(fragment_count)),
        "valid_pairwise_edges": int(valid_edges),
        "join_edges": int(join_edges),
        "cut_edges": int(cut_edges),
        "affinity_offsets_zyx": [list(v) for v in TASK1_V252_AFFINITY13_OFFSETS],
        "per_offset": per_offset,
    }
    if support.any() and not audit["one_seed_component_per_fragment"]:
        raise ValueError(
            "V273 oracle target seed topology failed: "
            f"seed_components={seed_n}, fragment_count={fragment_count}"
        )
    return target, audit


def task1_v275_local_fragment_position_target(inst_roi: np.ndarray) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V275 local fragment-position class target.

    [DATA][Risk:High][Scope:v275_fragment_position_target]
    Output은 `[Z,Y,X]` uint8 label map이다. 0은 background, 1..50은 공식 anatomy
    ID range 안의 local fragment position이다. contact/seed/pairwise field는 생성하지 않는다.
    """
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    target = np.zeros(inst.shape, dtype=np.uint8)
    foreground = (inst > 0) & (inst <= 200)
    target[foreground] = (((inst[foreground].astype(np.int32) - 1) % 50) + 1).astype(np.uint8)
    classes, counts = np.unique(target, return_counts=True)
    audit = {
        "contract": "task1_v275_local_fragment_position_target_v1",
        "channels": dict(TASK1_V275_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "output_channels": int(TASK1_V275_OUTPUT_CHANNELS),
        "fragment_position_classes_present": [int(v) for v in classes if int(v) > 0],
        "class_voxels": {str(int(c)): int(n) for c, n in zip(classes, counts)},
        "support_voxels": int(foreground.sum()),
        "contract_has_contact_channel": False,
        "contract_has_seed_channel": False,
        "contract_has_pairwise_graph": False,
    }
    return target, audit


def decode_task1_v275_fragment_position(target_or_probs: np.ndarray) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V275 probabilities/logits/labels by direct local-class argmax.

    [METRIC][Scope:task1_primary_gate]
    V275의 decoder는 threshold가 없다. channel argmax 또는 `[Z,Y,X]` local class를
    그대로 instance label로 사용하므로 promotion 판단은 Task1 official-aligned proxy
    지표와 visual audit에만 묶인다.
    """
    arr = np.asarray(target_or_probs)
    if arr.ndim == 3:
        decoded = arr.astype(np.uint16, copy=False)
    elif arr.ndim == 4 and int(arr.shape[0]) == int(TASK1_V275_OUTPUT_CHANNELS):
        if not np.isfinite(arr).all():
            raise ValueError("V275 decoder received NaN/Inf probabilities/logits")
        decoded = np.argmax(arr, axis=0).astype(np.uint16, copy=False)
    else:
        raise ValueError(f"V275 decoder expects [51,Z,Y,X] or [Z,Y,X], got {arr.shape}")
    decoded = np.where((decoded >= 1) & (decoded <= 50), decoded, 0).astype(np.uint16, copy=False)
    trace = {
        "decoder": "task1_v275_fragment_position_argmax",
        "pred_fragment_count": int(len([v for v in np.unique(decoded) if int(v) > 0])),
        "pred_classes": [int(v) for v in np.unique(decoded) if int(v) > 0],
        "contract_has_contact_channel": False,
        "contract_has_seed_channel": False,
        "contract_has_pairwise_graph": False,
    }
    return decoded, trace


def _task1_v277_separator_gap_from_instances(inst_roi: np.ndarray) -> np.ndarray:
    """Build a 13-neighbor separator-gap mask from same-anatomy instance IDs.

    [DATA][Risk:High][Scope:v277_separator_target]
    이 함수는 old contact head target을 재사용하지 않는다. 같은 anatomy range 안에서
    인접 voxel의 instance ID가 달라지는 지점만 separator로 표시해 connected component
    decoder의 절단면을 만든다.
    """
    inst = np.asarray(inst_roi).astype(np.int32, copy=False)
    separator = np.zeros(inst.shape, dtype=bool)
    for offset in TASK1_V252_AFFINITY13_OFFSETS:
        src_sl, dst_sl = _task1_affinity_offset_slices(inst.shape, offset)
        a = inst[src_sl]
        b = inst[dst_sl]
        a_fg = (a > 0) & (a <= 150)
        b_fg = (b > 0) & (b <= 150)
        same_anatomy = a_fg & b_fg & (((a - 1) // 50) == ((b - 1) // 50))
        different_fragment = same_anatomy & (a != b)
        if different_fragment.any():
            src_view = separator[src_sl]
            dst_view = separator[dst_sl]
            src_view[different_fragment] = True
            dst_view[different_fragment] = True
            separator[src_sl] = src_view
            separator[dst_sl] = dst_view
    return separator


def task1_v277_separator_gap_target(inst_roi: np.ndarray) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V277 support + separator-gap oracle fields.

    [QC][Invariant:channel_order]
    Output은 `[2,Z,Y,X]` float32이다. channel 0은 support, channel 1은 separator gap이다.
    channel 수가 2를 벗어나면 learned prediction exporter/evaluator가 같은 contract를
    읽지 못한다.
    """
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = (inst > 0) & (inst <= 150)
    separator = _task1_v277_separator_gap_from_instances(inst) & support
    target = np.stack([support, separator], axis=0).astype(np.float32, copy=False)
    audit = {
        "contract": "task1_v277_no_contact_separator_gap_target_v1",
        "channels": dict(TASK1_V277_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "output_channels": int(TASK1_V277_OUTPUT_CHANNELS),
        "support_voxels": int(support.sum()),
        "separator_gap_voxels": int(separator.sum()),
        "separator_fraction_of_support": float(separator.sum() / max(int(support.sum()), 1)),
        "contract_has_contact_probability": False,
        "contract_has_seed_channel": False,
        "contract_has_pairwise_graph": False,
    }
    return target, audit


def task1_v278_separator_energy_target(inst_roi: np.ndarray,
                                       *,
                                       separator_energy_decay: float = 0.45,
                                       separator_energy_steps: int = 12) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V278 support + dense separator-energy oracle fields.

    [DATA][Risk:High][Scope:v278_separator_energy]
    exact separator는 1.0이고 주변 support는 `decay ** step`으로 낮아진다.
    decay는 0.5보다 작아야 decoder threshold 0.50이 V277 oracle 절단면을 유지한다.
    """
    if not 0.0 < float(separator_energy_decay) < 0.5:
        raise ValueError(f"separator_energy_decay must be in (0, 0.5), got {separator_energy_decay}")
    if int(separator_energy_steps) < 1:
        raise ValueError(f"separator_energy_steps must be >= 1, got {separator_energy_steps}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = (inst > 0) & (inst <= 150)
    separator = _task1_v277_separator_gap_from_instances(inst) & support
    energy = separator.astype(np.float32, copy=False)
    current = separator.copy()
    visited = separator.copy()
    structure = np.ones((3, 3, 3), dtype=bool)
    for step in range(1, int(separator_energy_steps) + 1):
        current = ndi.binary_dilation(current, structure=structure) & support
        shell = current & ~visited
        if shell.any():
            energy[shell] = float(separator_energy_decay) ** int(step)
        visited |= current
    target = np.stack([support.astype(np.float32), energy.astype(np.float32)], axis=0)
    audit = {
        "contract": "task1_v278_no_contact_separator_energy_target_v1",
        "channels": dict(TASK1_V278_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "output_channels": int(TASK1_V278_OUTPUT_CHANNELS),
        "support_voxels": int(support.sum()),
        "exact_separator_voxels": int(separator.sum()),
        "energy_positive_voxels": int((energy > 0.0).sum()),
        "energy_ge_0_50_voxels": int((energy >= 0.5).sum()),
        "separator_energy_decay": float(separator_energy_decay),
        "separator_energy_steps": int(separator_energy_steps),
        "contract_has_contact_probability": False,
        "contract_has_seed_channel": False,
        "contract_has_pairwise_graph": False,
    }
    return target, audit


def _task1_v277_merge_small_components(labels: np.ndarray,
                                       *,
                                       min_component_voxels: int) -> np.ndarray:
    """Merge tiny separator-induced fragments into nearest large component."""
    out = np.asarray(labels).astype(np.int32, copy=True)
    if int(min_component_voxels) <= 0:
        return out.astype(np.uint16, copy=False)
    ids = [int(v) for v in np.unique(out) if int(v) > 0]
    if not ids:
        return out.astype(np.uint16, copy=False)
    sizes = {component_id: int((out == component_id).sum()) for component_id in ids}
    small_ids = [component_id for component_id in ids if int(sizes[component_id]) < int(min_component_voxels)]
    large_ids = [component_id for component_id in ids if int(sizes[component_id]) >= int(min_component_voxels)]
    if not small_ids or not large_ids:
        return out.astype(np.uint16, copy=False)
    large_mask = np.isin(out, np.asarray(large_ids, dtype=np.int32))
    nearest_indices = ndi.distance_transform_edt(~large_mask, return_indices=True)[1]
    for component_id in small_ids:
        mask = out == int(component_id)
        if not mask.any():
            continue
        nearest_ids = out[tuple(axis_indices[mask] for axis_indices in nearest_indices)]
        nearest_ids = nearest_ids[nearest_ids > 0]
        if nearest_ids.size <= 0:
            continue
        values, counts = np.unique(nearest_ids, return_counts=True)
        out[mask] = int(values[int(np.argmax(counts))])
    compact = np.zeros_like(out, dtype=np.uint16)
    for new_id, old_id in enumerate([int(v) for v in np.unique(out) if int(v) > 0], start=1):
        compact[out == int(old_id)] = np.uint16(new_id)
    return compact


def decode_task1_v277_separator_gap(fields: np.ndarray,
                                    *,
                                    support_threshold: float = 0.50,
                                    separator_threshold: float = 0.50,
                                    min_component_voxels: int = 100) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V277 support/separator fields by CC + nearest separator assignment.

    [METRIC][Scope:task1_primary_gate]
    support와 separator 모두 fixed 0.50 threshold를 사용한다. promotion 판단은
    Task1 proxy metric이며, old contact precision/recall/ratio는 이 decoder의 metric이 아니다.
    """
    arr = np.asarray(fields)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V277_OUTPUT_CHANNELS):
        raise ValueError(f"V277 decoder expects [2,Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V277 decoder received NaN/Inf fields")
    support = arr[0] >= float(support_threshold)
    separator = (arr[1] >= float(separator_threshold)) & support
    core = support & ~separator
    labels, num_components = ndi.label(core, structure=np.ones((3, 3, 3), dtype=bool))
    labels = labels.astype(np.int32, copy=False)
    if support.any():
        if int(num_components) <= 0:
            labels[support] = 1
        else:
            fill_mask = support & (labels == 0)
            if fill_mask.any():
                nearest_indices = ndi.distance_transform_edt(labels == 0, return_indices=True)[1]
                labels[fill_mask] = labels[tuple(axis_indices[fill_mask] for axis_indices in nearest_indices)]
    before_merge_count = int(len([v for v in np.unique(labels) if int(v) > 0]))
    decoded = _task1_v277_merge_small_components(labels, min_component_voxels=int(min_component_voxels))
    trace = {
        "decoder": "task1_v277_no_contact_separator_gap_cc",
        "support_threshold": float(support_threshold),
        "separator_threshold": float(separator_threshold),
        "min_component_voxels": int(min_component_voxels),
        "support_voxels": int(support.sum()),
        "separator_gap_voxels": int(separator.sum()),
        "core_voxels": int(core.sum()),
        "components_before_small_merge": int(before_merge_count),
        "pred_fragment_count": int(len([v for v in np.unique(decoded) if int(v) > 0])),
        "contract_has_contact_probability": False,
        "contract_has_seed_channel": False,
        "contract_has_pairwise_graph": False,
    }
    return decoded.astype(np.uint16, copy=False), trace


def task1_v288_abbc_target(inst_roi: np.ndarray,
                           *,
                           core_radius_vox: float = 2.0,
                           boundary_dilate_vox: int = 2) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V288 ABBC oracle fields: [background, border, boundary, core].

    [QC][Invariant:channel_order]
    Output은 `[4,Z,Y,X]` float32 one-hot이다. channel 0 background, 1 border,
    2 boundary, 3 core. core는 decoder seed class이고, boundary는 fragment-pair 사이
    medial-axis-adaptive 두께의 cut surface다.

    [DATA][Risk:High][Scope:v288_abbc_target]
    PENGWIN 2024 1st (MIC-DKFZ) ABBC representation을 oracle 단계에서 재현한다.
    boundary 두께는 raw 13-neighbor between-fragment band를 `boundary_dilate_vox`
    iteration binary_dilation으로 확장한 뒤 support와 교차해 정의한다. core는 support
    안에서 boundary로부터 `core_radius_vox` 이상 떨어진 voxel이고, 각 fragment에서
    core가 비면 fragment EDT argmax 1 voxel을 강제 seed로 추가해 thin fragment도
    seed를 갖도록 보장한다.
    """
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    if inst.ndim != 3:
        raise ValueError(f"V288 ABBC target requires [Z,Y,X], got {inst.shape}")
    if float(core_radius_vox) < 0.0:
        raise ValueError(f"core_radius_vox must be >= 0, got {core_radius_vox}")
    if int(boundary_dilate_vox) < 0:
        raise ValueError(f"boundary_dilate_vox must be >= 0, got {boundary_dilate_vox}")
    support = (inst > 0) & (inst <= 150)
    raw_between = _task1_v277_separator_gap_from_instances(inst) & support
    structure = np.ones((3, 3, 3), dtype=bool)
    if int(boundary_dilate_vox) > 0 and raw_between.any():
        boundary = ndi.binary_dilation(
            raw_between,
            structure=structure,
            iterations=int(boundary_dilate_vox),
        ) & support
    else:
        boundary = raw_between & support
    blocker = (~support) | boundary
    if (~blocker).any():
        edt_to_blocker = ndi.distance_transform_edt(~blocker)
    else:
        edt_to_blocker = np.zeros(inst.shape, dtype=np.float32)
    core = support & (~boundary) & (edt_to_blocker >= float(core_radius_vox))
    fragments_without_core = 0
    fragments_forced_seed = 0
    for frag_id in [int(v) for v in np.unique(inst) if 1 <= int(v) <= 150]:
        frag_mask = (inst == frag_id)
        if not frag_mask.any():
            continue
        if core[frag_mask].any():
            continue
        fragments_without_core += 1
        frag_inner = frag_mask & (~boundary)
        if not frag_inner.any():
            continue
        frag_edt = ndi.distance_transform_edt(frag_inner)
        flat_idx = int(np.argmax(frag_edt))
        seed_zyx = np.unravel_index(flat_idx, frag_edt.shape)
        if float(frag_edt[seed_zyx]) > 0.0:
            core[seed_zyx] = True
            fragments_forced_seed += 1
    border = support & (~boundary) & (~core)
    background = ~support
    target = np.stack([background, border, boundary, core], axis=0).astype(np.float32, copy=False)
    audit = {
        "contract": "task1_v288_abbc_target_v1",
        "channels": dict(TASK1_V288_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "output_channels": int(TASK1_V288_OUTPUT_CHANNELS),
        "core_radius_vox": float(core_radius_vox),
        "boundary_dilate_vox": int(boundary_dilate_vox),
        "support_voxels": int(support.sum()),
        "raw_between_voxels": int(raw_between.sum()),
        "boundary_voxels": int(boundary.sum()),
        "core_voxels": int(core.sum()),
        "border_voxels": int(border.sum()),
        "background_voxels": int(background.sum()),
        "fragments_without_core_before_force": int(fragments_without_core),
        "fragments_forced_seed": int(fragments_forced_seed),
        "fragment_count": int(len([v for v in np.unique(inst) if 1 <= int(v) <= 150])),
    }
    return target, audit


def _task1_v288_anatomy_size_ratio_merge(labels: np.ndarray,
                                         *,
                                         size_ratio_keep: float) -> np.ndarray:
    """Merge components smaller than `size_ratio_keep * largest` into nearest larger.

    [DATA][Risk:High][Scope:v288_anatomical_refinement]
    PENGWIN 1st (MIC-DKFZ) "merging smaller fragments with closest anatomically
    correct instance" 후처리. anatomy ROI 안에서 가장 큰 component 대비 비율이
    `size_ratio_keep` 미만인 component를 nearest larger component로 흡수한다.
    multi-component-per-fragment GT label 아티팩트(예: 003 Sacrum이 GT 1인데
    multi-CC로 저장됨)를 inference 단계에서도 동일 anatomy 안에서 자동 통합한다.
    """
    if float(size_ratio_keep) <= 0.0:
        return np.asarray(labels).astype(np.uint16, copy=False)
    out = np.asarray(labels).astype(np.int32, copy=True)
    sizes = {int(c): int((out == c).sum()) for c in np.unique(out) if int(c) > 0}
    if len(sizes) <= 1:
        return out.astype(np.uint16, copy=False)
    largest_size = max(sizes.values())
    threshold = max(1, int(float(size_ratio_keep) * float(largest_size)))
    small_ids = [c for c, sz in sizes.items() if sz < threshold]
    large_ids = [c for c, sz in sizes.items() if sz >= threshold]
    if not small_ids or not large_ids:
        return out.astype(np.uint16, copy=False)
    large_mask = np.isin(out, np.asarray(large_ids, dtype=np.int32))
    nearest_indices = ndi.distance_transform_edt(~large_mask, return_indices=True)[1]
    for c in small_ids:
        mask = out == int(c)
        if not mask.any():
            continue
        nearest_ids = out[tuple(axis_indices[mask] for axis_indices in nearest_indices)]
        nearest_ids = nearest_ids[nearest_ids > 0]
        if nearest_ids.size <= 0:
            continue
        vals, counts = np.unique(nearest_ids, return_counts=True)
        out[mask] = int(vals[int(np.argmax(counts))])
    compact = np.zeros_like(out, dtype=np.uint16)
    for new_id, old_id in enumerate([int(c) for c in np.unique(out) if int(c) > 0], start=1):
        compact[out == int(old_id)] = np.uint16(new_id)
    return compact


def decode_task1_v288_abbc(fields: np.ndarray,
                           *,
                           background_threshold: float = 0.50,
                           core_threshold: float = 0.50,
                           min_component_voxels: int = 100,
                           anatomy_size_ratio_keep: float = 0.0) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V288 ABBC fields: core CC -> seeds, boundary watershed-merge to nearest seed.

    [METRIC][Scope:task1_primary_gate]
    background/core 모두 fixed 0.50 threshold를 사용한다. core CC를 watershed seed로 쓰고,
    boundary/border voxel은 가장 가까운 seed로 흡수된다. 작은 component는 V277 helper로
    merge한다.
    """
    arr = np.asarray(fields)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V288_OUTPUT_CHANNELS):
        raise ValueError(f"V288 decoder expects [4,Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V288 decoder received NaN/Inf fields")
    background = arr[0] >= float(background_threshold)
    support = ~background
    core = (arr[3] >= float(core_threshold)) & support
    core_labels, n_core = ndi.label(core, structure=np.ones((3, 3, 3), dtype=bool))
    core_labels = core_labels.astype(np.int32, copy=False)
    if not support.any():
        decoded = np.zeros(arr.shape[1:], dtype=np.uint16)
        trace = {
            "decoder": "task1_v288_abbc_core_seed_watershed",
            "background_threshold": float(background_threshold),
            "core_threshold": float(core_threshold),
            "min_component_voxels": int(min_component_voxels),
            "support_voxels": 0,
            "core_voxels": 0,
            "core_seed_components_before_merge": 0,
            "components_before_small_merge": 0,
            "pred_fragment_count": 0,
            "contract_has_contact_probability": False,
            "contract_has_seed_channel": True,
            "contract_has_pairwise_graph": False,
        }
        return decoded, trace
    if int(n_core) <= 0:
        labels = np.where(support, 1, 0).astype(np.int32, copy=False)
    else:
        from skimage.segmentation import watershed as _ski_watershed
        priority = ndi.distance_transform_edt(core_labels == 0)
        labels = _ski_watershed(
            priority,
            markers=core_labels,
            mask=support,
        ).astype(np.int32, copy=False)
        fill_mask = support & (labels == 0)
        if fill_mask.any():
            nearest_indices = ndi.distance_transform_edt(labels == 0, return_indices=True)[1]
            labels[fill_mask] = labels[tuple(axis_indices[fill_mask] for axis_indices in nearest_indices)]
    before_merge_count = int(len([v for v in np.unique(labels) if int(v) > 0]))
    decoded = _task1_v277_merge_small_components(labels, min_component_voxels=int(min_component_voxels))
    components_after_size_merge = int(len([v for v in np.unique(decoded) if int(v) > 0]))
    if float(anatomy_size_ratio_keep) > 0.0:
        decoded = _task1_v288_anatomy_size_ratio_merge(
            decoded, size_ratio_keep=float(anatomy_size_ratio_keep),
        )
    trace = {
        "decoder": "task1_v288_abbc_core_seed_watershed",
        "background_threshold": float(background_threshold),
        "core_threshold": float(core_threshold),
        "min_component_voxels": int(min_component_voxels),
        "anatomy_size_ratio_keep": float(anatomy_size_ratio_keep),
        "support_voxels": int(support.sum()),
        "core_voxels": int(core.sum()),
        "core_seed_components_before_merge": int(n_core),
        "components_before_small_merge": int(before_merge_count),
        "components_after_small_merge": int(components_after_size_merge),
        "pred_fragment_count": int(len([v for v in np.unique(decoded) if int(v) > 0])),
        "contract_has_contact_probability": False,
        "contract_has_seed_channel": True,
        "contract_has_pairwise_graph": False,
    }
    return decoded.astype(np.uint16, copy=False), trace


def task1_v289_abbc_sdf_target(inst_roi: np.ndarray,
                               *,
                               core_radius_vox: float = 2.0,
                               boundary_dilate_vox: int = 2,
                               sdf_max_distance_vox: float = 10.0) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V289 ABBC+SDF oracle fields: [background, border, boundary_sdf, core].

    [QC][Invariant:channel_order]
    Output은 `[4,Z,Y,X]` float32이다. channel 0/1/3은 V288 ABBC one-hot이지만
    boundary class voxel은 border channel(1)에 합쳐진다. channel 2는 same-anatomy
    fragment-pair surface까지의 distance (0 ~ sdf_max_distance_vox).
    """
    if float(core_radius_vox) < 0.0 or int(boundary_dilate_vox) < 0:
        raise ValueError("core_radius_vox and boundary_dilate_vox must be >= 0")
    if float(sdf_max_distance_vox) <= 0.0:
        raise ValueError("sdf_max_distance_vox must be > 0")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    if inst.ndim != 3:
        raise ValueError(f"V289 ABBC+SDF target requires [Z,Y,X], got {inst.shape}")
    # ABBC 4-class via V288 helper.
    abbc_target, abbc_audit = task1_v288_abbc_target(
        inst,
        core_radius_vox=core_radius_vox,
        boundary_dilate_vox=boundary_dilate_vox,
    )
    # ABBC -> 3-class softmax target (bg, border, core); boundary voxels fold into border.
    bg = abbc_target[0] > 0.5
    border = abbc_target[1] > 0.5
    boundary_class = abbc_target[2] > 0.5
    core = abbc_target[3] > 0.5
    border_with_boundary = border | boundary_class
    # SDF channel: per voxel distance to nearest same-anatomy fragment-pair surface.
    max_d = float(sdf_max_distance_vox)
    sdf = np.full(inst.shape, max_d, dtype=np.float32)
    for anatomy_idx in range(3):
        lo = anatomy_idx * 50 + 1
        hi = anatomy_idx * 50 + 50
        anatomy_mask = (inst >= int(lo)) & (inst <= int(hi))
        if not anatomy_mask.any():
            continue
        frag_ids = [int(f) for f in np.unique(inst[anatomy_mask]) if int(f) > 0]
        if len(frag_ids) < 2:
            continue
        for frag_id in frag_ids:
            frag_mask = inst == int(frag_id)
            if not frag_mask.any():
                continue
            other_frag = anatomy_mask & (inst != int(frag_id)) & (inst > 0)
            if not other_frag.any():
                continue
            edt = ndi.distance_transform_edt(~other_frag)
            sdf[frag_mask] = np.minimum(edt[frag_mask].astype(np.float32), max_d)
    # Channel layout: [background, border (+boundary folded in), SDF, core]
    target = np.zeros((4, *inst.shape), dtype=np.float32)
    target[0] = bg.astype(np.float32)
    target[1] = border_with_boundary.astype(np.float32)
    target[2] = sdf
    target[3] = core.astype(np.float32)
    audit = {
        "contract": "task1_v289_abbc_sdf_target_v1",
        "channels": dict(TASK1_V289_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "output_channels": int(TASK1_V289_OUTPUT_CHANNELS),
        "core_radius_vox": float(core_radius_vox),
        "boundary_dilate_vox": int(boundary_dilate_vox),
        "sdf_max_distance_vox": float(sdf_max_distance_vox),
        "support_voxels": int(abbc_audit["support_voxels"]),
        "raw_between_voxels": int(abbc_audit["raw_between_voxels"]),
        "core_voxels": int(abbc_audit["core_voxels"]),
        "border_with_boundary_voxels": int(border_with_boundary.sum()),
        "background_voxels": int(bg.sum()),
        "sdf_voxels_lt_2": int(((sdf < 2.0) & (~bg)).sum()),
        "sdf_voxels_eq_max": int((sdf >= float(sdf_max_distance_vox)).sum()),
        "fragments_without_core_before_force": int(abbc_audit["fragments_without_core_before_force"]),
        "fragments_forced_seed": int(abbc_audit["fragments_forced_seed"]),
        "fragment_count": int(abbc_audit["fragment_count"]),
    }
    return target, audit


def decode_task1_v289_abbc_sdf(fields: np.ndarray,
                               *,
                               background_threshold: float = 0.50,
                               core_threshold: float = 0.50,
                               sdf_threshold: float = 2.0,
                               min_component_voxels: int = 100,
                               anatomy_size_ratio_keep: float = 0.0) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V289 ABBC+SDF fields.

    Softmax is applied over channels {0, 1, 3} (background/border/core); channel 2
    is the SDF regression. background_mask uses softmax-argmax on background channel,
    core_mask uses softmax-argmax on core channel, boundary_mask = (SDF < threshold) within support.
    core CC excludes boundary voxels and produces watershed seeds; remaining support
    voxels (including the boundary and border) are assigned to the nearest seed.
    """
    arr = np.asarray(fields)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V289_OUTPUT_CHANNELS):
        raise ValueError(f"V289 decoder expects [4,Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V289 decoder received NaN/Inf fields")
    # Note: fields can be either raw 4-channel logits/regression or post-softmax
    # probabilities for channels 0/1/3. For oracle one-hot input both work because
    # the softmax + argmax over a one-hot retrieves the same class.
    softmax_input = np.stack([arr[0], arr[1], arr[3]], axis=0)
    sm_shifted = softmax_input - np.max(softmax_input, axis=0, keepdims=True)
    sm_exp = np.exp(sm_shifted).astype(np.float32, copy=False)
    sm_prob = sm_exp / np.maximum(np.sum(sm_exp, axis=0, keepdims=True), np.float32(1e-8))
    background = sm_prob[0] >= float(background_threshold)
    support = ~background
    core = (sm_prob[2] >= float(core_threshold)) & support
    sdf = arr[2]
    boundary_mask = (sdf < float(sdf_threshold)) & support
    core_seeds_mask = core & (~boundary_mask)
    core_labels, n_core = ndi.label(core_seeds_mask, structure=np.ones((3, 3, 3), dtype=bool))
    core_labels = core_labels.astype(np.int32, copy=False)
    if not support.any():
        decoded = np.zeros(arr.shape[1:], dtype=np.uint16)
        trace = {
            "decoder": "task1_v289_abbc_sdf_core_seed_watershed",
            "background_threshold": float(background_threshold),
            "core_threshold": float(core_threshold),
            "sdf_threshold": float(sdf_threshold),
            "min_component_voxels": int(min_component_voxels),
            "anatomy_size_ratio_keep": float(anatomy_size_ratio_keep),
            "support_voxels": 0,
            "core_voxels": 0,
            "boundary_mask_voxels": 0,
            "core_seed_components_before_merge": 0,
            "components_before_small_merge": 0,
            "components_after_small_merge": 0,
            "pred_fragment_count": 0,
            "contract_has_contact_probability": False,
            "contract_has_seed_channel": True,
            "contract_has_pairwise_graph": False,
        }
        return decoded, trace
    if int(n_core) <= 0:
        labels = np.where(support, 1, 0).astype(np.int32, copy=False)
    else:
        from skimage.segmentation import watershed as _ski_watershed
        priority = ndi.distance_transform_edt(core_labels == 0)
        labels = _ski_watershed(
            priority,
            markers=core_labels,
            mask=support,
        ).astype(np.int32, copy=False)
        fill_mask = support & (labels == 0)
        if fill_mask.any():
            nearest_indices = ndi.distance_transform_edt(labels == 0, return_indices=True)[1]
            labels[fill_mask] = labels[tuple(axis_indices[fill_mask] for axis_indices in nearest_indices)]
    before_merge_count = int(len([v for v in np.unique(labels) if int(v) > 0]))
    decoded = _task1_v277_merge_small_components(labels, min_component_voxels=int(min_component_voxels))
    components_after_size_merge = int(len([v for v in np.unique(decoded) if int(v) > 0]))
    if float(anatomy_size_ratio_keep) > 0.0:
        decoded = _task1_v288_anatomy_size_ratio_merge(
            decoded, size_ratio_keep=float(anatomy_size_ratio_keep),
        )
    trace = {
        "decoder": "task1_v289_abbc_sdf_core_seed_watershed",
        "background_threshold": float(background_threshold),
        "core_threshold": float(core_threshold),
        "sdf_threshold": float(sdf_threshold),
        "min_component_voxels": int(min_component_voxels),
        "anatomy_size_ratio_keep": float(anatomy_size_ratio_keep),
        "support_voxels": int(support.sum()),
        "core_voxels": int(core.sum()),
        "boundary_mask_voxels": int(boundary_mask.sum()),
        "core_seed_components_before_merge": int(n_core),
        "components_before_small_merge": int(before_merge_count),
        "components_after_small_merge": int(components_after_size_merge),
        "pred_fragment_count": int(len([v for v in np.unique(decoded) if int(v) > 0])),
        "contract_has_contact_probability": False,
        "contract_has_seed_channel": True,
        "contract_has_pairwise_graph": False,
    }
    return decoded.astype(np.uint16, copy=False), trace


def decode_task1_v252_affinity13(target: np.ndarray,
                                 *,
                                 support_threshold: float = 0.5,
                                 seed_threshold: float = 0.5,
                                 affinity_threshold: float = 0.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V252 13-offset affinities into instance components.

    [METRIC][Scope:task1_topology]
    이 decoder는 GT oracle에서 Instance F1/Precision/Split/Topology가 1.0에
    가까운지 확인하기 위한 gate다. 학습 결과 평가 전에 oracle이 실패하면
    해당 output contract는 Task1 metric을 최적화할 수 없다.
    """
    arr = np.asarray(target, dtype=np.float32)
    expected_channels = 5 + len(TASK1_V252_AFFINITY13_OFFSETS)
    if arr.ndim != 4 or int(arr.shape[0]) != int(expected_channels):
        raise ValueError(f"V252 decoder expects [{expected_channels},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V252 decoder received NaN/Inf target/probabilities")
    support = arr[TASK1_V252_BASE_CHANNELS["support"]] >= float(support_threshold)
    seed_body = arr[TASK1_V252_BASE_CHANNELS["seed_body"]] >= float(seed_threshold)
    affinity = np.clip(arr[5:], 0.0, 1.0)
    shape = tuple(int(v) for v in support.shape)
    size = int(np.prod(shape))
    if not support.any():
        return np.zeros(shape, dtype=np.uint16), {
            "decoder": "task1_v252_affinity13_cc",
            "support_voxels": 0,
            "seed_components": 0,
            "pred_fragment_count": 0,
        }

    support_idx = np.flatnonzero(support.reshape(-1))
    compact_index = np.full(size, -1, dtype=np.int64)
    compact_index[support_idx] = np.arange(int(support_idx.size), dtype=np.int64)
    flat_index = np.arange(size, dtype=np.int64).reshape(shape)
    edge_rows = []
    edge_cols = []
    joined_edges = 0
    valid_edges = 0
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(shape, offset)
        edge_valid = support[src_sl] & support[dst_sl]
        edge_join = edge_valid & (affinity[i][src_sl] >= float(affinity_threshold))
        valid_edges += int(edge_valid.sum())
        joined_edges += int(edge_join.sum())
        if edge_join.any():
            src_idx = compact_index[flat_index[src_sl][edge_join].reshape(-1)]
            dst_idx = compact_index[flat_index[dst_sl][edge_join].reshape(-1)]
            edge_rows.append(src_idx.astype(np.int64, copy=False))
            edge_cols.append(dst_idx.astype(np.int64, copy=False))

    # [QC][Invariant:decoder_runtime]
    # Learned early checkpoints can create millions of affinity edges. Python
    # union-find made evaluation runtime depend on edge count and could hang a
    # smoke gate. Sparse connected-components keeps the exact same graph
    # contract while moving the heavy work into scipy's compiled implementation.
    from scipy import sparse as sp
    from scipy.sparse.csgraph import connected_components

    n_support = int(support_idx.size)
    if edge_rows:
        rows = np.concatenate(edge_rows)
        cols = np.concatenate(edge_cols)
        graph = sp.coo_matrix(
            (
                np.ones(int(rows.size) * 2, dtype=np.bool_),
                (np.concatenate([rows, cols]), np.concatenate([cols, rows])),
            ),
            shape=(n_support, n_support),
        ).tocsr()
        component_count, labels = connected_components(graph, directed=False, return_labels=True)
    else:
        component_count = n_support
        labels = np.arange(n_support, dtype=np.int64)
    if int(component_count) > int(np.iinfo(np.uint16).max):
        raise RuntimeError(
            "V252/V253 decoder produced too many graph components for uint16 output: "
            f"{component_count}"
        )
    decoded_flat = np.zeros(size, dtype=np.uint16)
    decoded_flat[support_idx] = (labels.astype(np.uint32) + 1).astype(np.uint16)
    decoded = decoded_flat.reshape(shape)
    seed_cc, seed_n = ndi.label(seed_body)
    component_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    component_seed_counts = []
    component_seed_count_skipped = False
    # [QC][Invariant:decoder_runtime]
    # Learned failed checkpoints can produce tens of thousands of raw graph components.
    # Scanning the full volume once per component does not change metrics, but it can
    # make the gate appear hung. Keep exact detailed samples for oracle/small graphs
    # and skip only the trace-only component seed sample on large learned failures.
    if len(component_ids) <= 5000:
        for pred_id in component_ids:
            seeds = [int(v) for v in np.unique(seed_cc[decoded == pred_id]) if int(v) > 0]
            component_seed_counts.append({"component": int(pred_id), "seed_components": int(len(seeds))})
    else:
        component_seed_count_skipped = True
    missing_seed_components = [row for row in component_seed_counts if int(row["seed_components"]) == 0]
    multi_seed_components = [row for row in component_seed_counts if int(row["seed_components"]) > 1]
    return decoded.astype(np.uint16, copy=False), {
        "decoder": "task1_v252_affinity13_cc",
        "support_threshold": float(support_threshold),
        "seed_threshold": float(seed_threshold),
        "affinity_threshold": float(affinity_threshold),
        "support_voxels": int(support.sum()),
        "valid_affinity_edges": int(valid_edges),
        "joined_affinity_edges": int(joined_edges),
        "seed_components": int(seed_n),
        "pred_fragment_count": int(len(component_ids)),
        "graph_component_count": int(component_count),
        "missing_seed_component": missing_seed_components[:50],
        "missing_seed_component_count": int(len(missing_seed_components)),
        "multi_seed_component": multi_seed_components[:50],
        "multi_seed_component_count": int(len(multi_seed_components)),
        "component_seed_count_skipped": bool(component_seed_count_skipped),
        "component_seed_count_report_cap": 50,
    }


def decode_task1_v253_affinity13_seed_healed(target: np.ndarray,
                                             spacing_zyx: tuple[float, float, float],
                                             *,
                                             support_threshold: float = 0.5,
                                             seed_threshold: float = 0.5,
                                             affinity_threshold: float = 0.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V252 affinities, then attach seedless CCs to nearest seed.

    [AUDIT][Risk:High][Scope:v253_decoder_contract]
    V252 passes case003/011 but fails case017 because one GT Sacrum instance has
    a small disconnected island even under 26-connectivity. Local affinities
    cannot connect disconnected objects. V253 keeps the same 18-channel target
    but makes the seed channel decoder-facing: each seedless affinity component
    is assigned to the nearest seed marker inside the same anatomy ROI.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V253 decoder: {spacing_zyx}")
    decoded, trace = decode_task1_v252_affinity13(
        target,
        support_threshold=support_threshold,
        seed_threshold=seed_threshold,
        affinity_threshold=affinity_threshold,
    )
    arr = np.asarray(target, dtype=np.float32)
    seed_body = arr[TASK1_V252_BASE_CHANNELS["seed_body"]] >= float(seed_threshold)
    seed_cc, seed_n = ndi.label(seed_body)
    if int(seed_n) <= 0 or not (decoded > 0).any():
        trace.update({
            "decoder": "task1_v253_affinity13_seed_healed",
            "seed_healing_applied": False,
            "seed_healing_reason": "no_seed_or_no_decoded_support",
        })
        return decoded, trace

    healed = np.zeros_like(decoded, dtype=np.uint16)
    raw_component_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    seedless_components = []
    multi_seed_components = []
    if len(raw_component_ids) > 5000:
        # [AUDIT][Risk:High][Scope:learned_decoder_failure_path]
        # V273/V274 learned probes can produce 30k~70k raw components before seed
        # healing. The old exact loop scanned the full volume per component and made
        # failure analysis impractically slow. This vectorized path keeps the same
        # high-level rule for seeded components: a component with an internal seed
        # uses that seed. Seedless components stay separate in this failure path;
        # running a full nearest-seed distance transform on a 50k-component failure
        # only hides the root cause and can stall the gate.
        flat_decoded = decoded.reshape(-1)
        flat_seed = seed_cc.reshape(-1)
        comp_mask = flat_decoded > 0
        max_component = int(max(raw_component_ids))
        assignment = np.arange(max_component + 1, dtype=np.uint16)

        internal_seed_mask = comp_mask & (flat_seed > 0)
        if internal_seed_mask.any():
            comp_seed = flat_decoded[internal_seed_mask].astype(np.int64, copy=False)
            seed_vals = flat_seed[internal_seed_mask].astype(np.uint16, copy=False)
            order = np.argsort(comp_seed, kind="mergesort")
            unique_comp, first_idx = np.unique(comp_seed[order], return_index=True)
            assignment[unique_comp] = seed_vals[order][first_idx]

        assigned_seedless_count = 0
        unassigned_seedless_count = 0
        seeded_components = np.flatnonzero(assignment != np.arange(max_component + 1, dtype=np.uint16))
        unassigned_seedless_count = int(len(raw_component_ids) - int(seeded_components.size))

        healed_flat = np.zeros_like(flat_decoded, dtype=np.uint16)
        healed_flat[comp_mask] = assignment[flat_decoded[comp_mask]]
        healed = healed_flat.reshape(decoded.shape)
        healed_ids = [int(v) for v in np.unique(healed) if int(v) > 0]
        trace.update({
            "decoder": "task1_v253_affinity13_seed_healed",
            "seed_healing_applied": True,
            "seed_assignment_policy": "vectorized_internal_seed_else_keep_seedless_component",
            "raw_pred_fragment_count": int(len(raw_component_ids)),
            "pred_fragment_count": int(len(healed_ids)),
            "healed_pred_fragment_count": int(len(healed_ids)),
            "seedless_component_assigned_count": int(assigned_seedless_count),
            "seedless_component_unassigned_count": int(unassigned_seedless_count),
            "seedless_component_voxels": None,
            "seedless_component_samples": [],
            "multi_seed_component_after_healing_count": None,
            "multi_seed_component_after_healing_samples": [],
            "large_component_fast_path": True,
        })
        return healed.astype(np.uint16, copy=False), trace

    # [METRIC][Scope:task1_split_topology]
    # Instance Precision/Split/Topology는 작은 seedless island도 별도 instance로
    # 세면 실패한다. nearest-seed assignment는 Panoptic/center 기반 decoder와
    # 같은 역할로, support geometry는 유지하면서 instance ID만 복구한다.
    _, nearest_idx = ndi.distance_transform_edt(
        seed_cc == 0,
        sampling=spacing_zyx,
        return_indices=True,
    )
    nearest_seed = seed_cc[tuple(nearest_idx)]

    for comp_id in raw_component_ids:
        comp = decoded == int(comp_id)
        seed_ids = [int(v) for v in np.unique(seed_cc[comp]) if int(v) > 0]
        if len(seed_ids) == 1:
            healed[comp] = np.uint16(seed_ids[0])
        elif len(seed_ids) > 1:
            multi_seed_components.append({
                "component": int(comp_id),
                "seed_components": int(len(seed_ids)),
                "voxels": int(comp.sum()),
            })
            healed[comp] = np.uint16(seed_ids[0])
        else:
            candidate_seed = nearest_seed[comp]
            candidate_seed = candidate_seed[candidate_seed > 0]
            if candidate_seed.size == 0:
                seedless_components.append({
                    "component": int(comp_id),
                    "assigned_seed": None,
                    "voxels": int(comp.sum()),
                })
                healed[comp] = np.uint16(int(seed_n) + int(len(seedless_components)))
                continue
            counts = np.bincount(candidate_seed.astype(np.int64))
            assigned_seed = int(np.argmax(counts))
            healed[comp] = np.uint16(assigned_seed)
            seedless_components.append({
                "component": int(comp_id),
                "assigned_seed": int(assigned_seed),
                "voxels": int(comp.sum()),
            })

    healed_ids = [int(v) for v in np.unique(healed) if int(v) > 0]
    trace.update({
        "decoder": "task1_v253_affinity13_seed_healed",
        "seed_healing_applied": True,
        "seed_assignment_policy": "nearest_seed_component_by_physical_distance",
        "raw_pred_fragment_count": int(len(raw_component_ids)),
        "pred_fragment_count": int(len(healed_ids)),
        "healed_pred_fragment_count": int(len(healed_ids)),
        "seedless_component_assigned_count": int(sum(1 for row in seedless_components if row["assigned_seed"] is not None)),
        "seedless_component_unassigned_count": int(sum(1 for row in seedless_components if row["assigned_seed"] is None)),
        "seedless_component_voxels": int(sum(int(row["voxels"]) for row in seedless_components)),
        "seedless_component_samples": seedless_components[:50],
        "multi_seed_component_after_healing_count": int(len(multi_seed_components)),
        "multi_seed_component_after_healing_samples": multi_seed_components[:50],
    })
    return healed.astype(np.uint16, copy=False), trace


def decode_task1_v255_mutex13_seed_healed(target: np.ndarray,
                                          spacing_zyx: tuple[float, float, float],
                                          *,
                                          support_threshold: float = 0.5,
                                          seed_threshold: float = 0.5,
                                          affinity_threshold: float = 0.5,
                                          mutex_threshold: float = 0.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V255 mutex affinities through the existing seed-healed partitioner.

    [METRIC][Scope:task1_merge_topology]
    Decoder join condition is fixed: attractive affinity >= 0.50 and repulsive
    mutex < 0.50. This makes Merge Errors and Topology Consistency first-class
    decoder constraints instead of post-hoc contact diagnostics.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V255 decoder expects [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V255 decoder received NaN/Inf target/probabilities")
    attractive = np.clip(arr[TASK1_V255_ATTRACTIVE_START:TASK1_V255_REPULSIVE_START], 0.0, 1.0)
    repulsive = np.clip(arr[TASK1_V255_REPULSIVE_START:], 0.0, 1.0)
    gated_affinity = np.where(
        repulsive < float(mutex_threshold),
        attractive,
        0.0,
    ).astype(np.float32, copy=False)
    v253_like = np.zeros((5 + len(TASK1_V252_AFFINITY13_OFFSETS), *arr.shape[1:]), dtype=np.float32)
    v253_like[:5] = arr[:5]
    v253_like[5:] = gated_affinity
    decoded, trace = decode_task1_v253_affinity13_seed_healed(
        v253_like,
        spacing_zyx,
        support_threshold=support_threshold,
        seed_threshold=seed_threshold,
        affinity_threshold=affinity_threshold,
    )
    trace.update({
        "decoder": "task1_v255_mutex13_seed_healed",
        "mutex_threshold": float(mutex_threshold),
        "attractive_threshold": float(affinity_threshold),
        "join_rule": "support && attractive>=threshold && repulsive<mutex_threshold",
        "repulsive_edges_ge_threshold": int((repulsive >= float(mutex_threshold)).sum()),
    })
    return decoded, trace


def task1_v266_pairwise_softmax_fields_from_logits(raw_logits: np.ndarray) -> np.ndarray:
    """Convert V266 raw logits to V255-compatible decoder probabilities.

    [QC][Invariant:channel_activation]
    V266 rows 5..17 and 18..30 are not independent sigmoid probabilities.
    They are join-vs-cut logits for the same edge. The decoder probability is
    sigmoid(join_logit - cut_logit), which is exactly the two-class softmax
    join probability. Applying expit to each row independently would recreate
    the V255/V260 failure mode.
    """
    raw = np.asarray(raw_logits, dtype=np.float32)
    if raw.ndim != 4 or int(raw.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V266 logits expect [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {raw.shape}")
    if not np.isfinite(raw).all():
        raise ValueError("V266 logits contain NaN/Inf")
    fields = np.zeros_like(raw, dtype=np.float32)
    fields[:5] = expit(raw[:5]).astype(np.float32, copy=False)
    diff = raw[TASK1_V255_ATTRACTIVE_START:TASK1_V255_REPULSIVE_START] - raw[TASK1_V255_REPULSIVE_START:]
    fields[TASK1_V255_ATTRACTIVE_START:TASK1_V255_REPULSIVE_START] = expit(diff).astype(np.float32, copy=False)
    fields[TASK1_V255_REPULSIVE_START:] = expit(-diff).astype(np.float32, copy=False)
    return fields


def decode_task1_v266_pairwise_softmax_mutex13_seed_healed(target: np.ndarray,
                                                           spacing_zyx: tuple[float, float, float],
                                                           *,
                                                           support_threshold: float = 0.5,
                                                           seed_threshold: float = 0.5,
                                                           affinity_threshold: float = 0.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V266 pairwise-softmax edge logits after probability conversion.

    [METRIC][Scope:task1_merge_split_topology]
    V266 keeps the V255 sparse graph decoder but changes edge probability
    semantics: an edge joins only when join_logit-cut_logit crosses the fixed
    0.50 softmax threshold. This directly targets Instance F1, Merge/Split, and
    Topology Consistency without a post-hoc threshold sweep.
    """
    decoded, trace = decode_task1_v255_mutex13_seed_healed(
        target,
        spacing_zyx,
        support_threshold=support_threshold,
        seed_threshold=seed_threshold,
        affinity_threshold=affinity_threshold,
        mutex_threshold=0.5,
    )
    trace.update({
        "decoder": "task1_v266_pairwise_softmax_mutex13_seed_healed",
        "edge_probability_contract": "join_prob=sigmoid(join_logit-cut_logit)",
        "join_rule": "support && sigmoid(join-cut)>=threshold && sigmoid(cut-join)<0.5",
    })
    return decoded, trace


def decode_task1_v273_no_contact_pairwise_seed_healed(
    target: np.ndarray,
    spacing_zyx: tuple[float, float, float],
    *,
    support_threshold: float = 0.5,
    seed_threshold: float = 0.5,
    join_threshold: float = 0.5,
    cut_threshold: float = 0.5,
) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V273 no-contact pairwise join/cut fields.

    [METRIC][Scope:task1_primary_gate]
    The join rule is fixed: support && join>=0.50 && cut<0.50. This is directly
    tied to Task1 Instance F1/Recall/Precision, Merge/Split, Topology, and
    fracture-boundary proxy. There is no contact probability or watershed energy
    in this contract.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V273_OUTPUT_CHANNELS):
        raise ValueError(f"V273 decoder expects [{TASK1_V273_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V273 decoder received NaN/Inf target/probabilities")
    support = np.clip(arr[TASK1_V273_BASE_CHANNELS["support"]], 0.0, 1.0)
    seed_body = np.clip(arr[TASK1_V273_BASE_CHANNELS["seed_body"]], 0.0, 1.0)
    join = np.clip(arr[TASK1_V273_JOIN_START:TASK1_V273_CUT_START], 0.0, 1.0)
    cut = np.clip(arr[TASK1_V273_CUT_START:], 0.0, 1.0)
    support_mask = support >= float(support_threshold)
    seed_outside_support_voxels = int(((seed_body >= float(seed_threshold)) & ~support_mask).sum())
    # [AUDIT][Risk:High][Scope:v273_decoder_seed_contract]
    # V273에서 seed_body는 instance anchor일 뿐이며 독립 segmentation head가 아니다.
    # learned early checkpoint가 ROI 전역에 seed를 뿌리면 nearest-seed healing이
    # support 밖 seed component로 오염되어 Instance Precision/Split/Topology를 왜곡한다.
    # 그래서 V273 경로에서만 seed를 support 내부로 제한한다. 기존 V253/V255 재현 경로는 유지한다.
    seed_body = np.where(support_mask, seed_body, 0.0).astype(np.float32, copy=False)
    v253_like = np.zeros((5 + len(TASK1_V252_AFFINITY13_OFFSETS), *arr.shape[1:]), dtype=np.float32)
    v253_like[TASK1_V252_BASE_CHANNELS["support"]] = support
    v253_like[TASK1_V252_BASE_CHANNELS["seed_body"]] = seed_body
    gated_join = np.where(cut < float(cut_threshold), join, 0.0).astype(np.float32, copy=False)
    v253_like[5:] = gated_join
    decoded, trace = decode_task1_v253_affinity13_seed_healed(
        v253_like,
        spacing_zyx,
        support_threshold=support_threshold,
        seed_threshold=seed_threshold,
        affinity_threshold=join_threshold,
    )
    trace.update({
        "decoder": "task1_v273_no_contact_pairwise_seed_healed",
        "join_threshold": float(join_threshold),
        "cut_threshold": float(cut_threshold),
        "join_rule": "support && join>=threshold && cut<cut_threshold",
        "contract_has_contact_channel": False,
        "cut_edges_ge_threshold": int((cut >= float(cut_threshold)).sum()),
        "seed_outside_support_voxels_suppressed": int(seed_outside_support_voxels),
    })
    return decoded, trace


def decode_task1_v257_mutex13_seed_union_healed(target: np.ndarray,
                                                spacing_zyx: tuple[float, float, float],
                                                *,
                                                support_threshold: float = 0.5,
                                                seed_threshold: float = 0.5,
                                                affinity_threshold: float = 0.5,
                                                mutex_threshold: float = 0.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V257 mutex graph with channel3/channel4 union seed anchors.

    [AUDIT][Risk:High][Scope:v257_decoder_seed_contract]
    V257 trains both sparse seed_center(channel3) and seed_body(channel4), but
    V255 decoder consumed only channel4. V257 10e20i validation showed channel4
    core_f1=0 while barrier/support improved, so the decoder must expose the
    learned seed_center anchor instead of discarding it.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V257 decoder expects [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V257 decoder received NaN/Inf target/probabilities")
    seed_center = arr[TASK1_V252_BASE_CHANNELS["seed_center"]] >= float(seed_threshold)
    seed_body = arr[TASK1_V252_BASE_CHANNELS["seed_body"]] >= float(seed_threshold)
    seed_union = seed_center | seed_body
    v257_target = arr.copy()
    v257_target[TASK1_V252_BASE_CHANNELS["seed_body"]] = seed_union.astype(np.float32)
    decoded, trace = decode_task1_v255_mutex13_seed_healed(
        v257_target,
        spacing_zyx,
        support_threshold=support_threshold,
        seed_threshold=seed_threshold,
        affinity_threshold=affinity_threshold,
        mutex_threshold=mutex_threshold,
    )
    trace.update({
        "decoder": "task1_v257_mutex13_seed_union_healed",
        "seed_union_policy": "channel3_seed_center_or_channel4_seed_body",
        "seed_center_voxels": int(seed_center.sum()),
        "seed_body_voxels": int(seed_body.sum()),
        "seed_union_voxels": int(seed_union.sum()),
    })
    # [METRIC][Scope:task1_instance_topology]
    # seed_union_voxels가 0이면 Instance Recall/Topology는 회복될 수 없다. 반대로
    # seed_union이 지나치게 크면 Split/Precision이 실패하므로 trace에 세 seed mass를
    # 모두 남겨 fulltrain gate 실패 원인을 분리한다.
    return decoded, trace


def _task1_v258_seed_peak_markers(seed_score: np.ndarray,
                                  support: np.ndarray,
                                  spacing_zyx: tuple[float, float, float],
                                  *,
                                  peak_threshold: float = 0.5,
                                  nms_radius_mm: float = 10.0,
                                  max_markers: int = 50,
                                  preselect_markers: int = 4096,
                                  allow_top1_fallback: bool = True) -> tuple[np.ndarray, dict[str, Any]]:
    """Select deterministic seed-center peaks for V258 marker decoding.

    [AUDIT][Risk:High][Scope:v258_seed_peak_decoder]
    V257의 threshold mask seed는 0개 또는 수십만 voxel로 흔들렸다. V258은
    channel3을 dense mask가 아니라 peak field로 해석한다. marker 수는 anatomy
    ID capacity(50) 안에서 NMS로 제한해 Task1 Instance/Topology metric이
    overfragmentation 때문에 평가 불능 상태로 빠지는 것을 막는다.
    """
    score = np.asarray(seed_score, dtype=np.float32)
    support_mask = np.asarray(support).astype(bool, copy=False)
    if score.shape != support_mask.shape:
        raise ValueError(f"V258 seed peak shape mismatch: score={score.shape} support={support_mask.shape}")
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V258 seed peak markers: {spacing_zyx}")
    if int(max_markers) < 1:
        raise ValueError(f"max_markers must be >= 1, got {max_markers}")
    if float(nms_radius_mm) <= 0.0:
        raise ValueError(f"nms_radius_mm must be > 0, got {nms_radius_mm}")

    markers = np.zeros(score.shape, dtype=np.float32)
    if not support_mask.any():
        return markers, {
            "seed_peak_policy": "channel3_local_peak_nms",
            "seed_peak_candidates": 0,
            "seed_peak_selected": 0,
            "seed_peak_threshold": float(peak_threshold),
            "seed_peak_top1_fallback": False,
        }

    candidate_mask = support_mask & (score >= float(peak_threshold))
    fallback_used = False
    if not candidate_mask.any() and bool(allow_top1_fallback):
        masked_score = np.where(support_mask, score, -np.inf)
        top_flat = int(np.argmax(masked_score.reshape(-1)))
        candidate_flat = np.asarray([top_flat], dtype=np.int64)
        fallback_used = True
    else:
        candidate_flat = np.flatnonzero(candidate_mask.reshape(-1))
    if candidate_flat.size == 0:
        return markers, {
            "seed_peak_policy": "channel3_local_peak_nms",
            "seed_peak_candidates": 0,
            "seed_peak_selected": 0,
            "seed_peak_threshold": float(peak_threshold),
            "seed_peak_top1_fallback": bool(fallback_used),
        }

    flat_score = score.reshape(-1)
    candidate_scores = flat_score[candidate_flat]
    preselect = max(int(max_markers) * 8, int(preselect_markers))
    if int(candidate_flat.size) > int(preselect):
        # [QC][Invariant:deterministic_runtime]
        # threshold 후보가 수십만 voxel이면 전체 정렬이 eval runtime을 지배한다.
        # argpartition으로 상위 후보만 남긴 뒤 점수 내림차순 정렬을 적용해 marker
        # 선택은 deterministic하게 유지한다.
        keep_idx = np.argpartition(-candidate_scores, int(preselect) - 1)[:int(preselect)]
        candidate_flat = candidate_flat[keep_idx]
        candidate_scores = candidate_scores[keep_idx]
    order = np.argsort(-candidate_scores, kind="mergesort")
    candidate_flat = candidate_flat[order]
    candidate_scores = candidate_scores[order]
    coords = np.column_stack(np.unravel_index(candidate_flat, score.shape)).astype(np.int32, copy=False)
    spacing = np.asarray(spacing_zyx, dtype=np.float64).reshape(1, 3)
    min_dist2 = float(nms_radius_mm) ** 2
    selected: list[np.ndarray] = []
    selected_scores: list[float] = []
    for coord, value in zip(coords, candidate_scores):
        if selected:
            selected_arr = np.asarray(selected, dtype=np.float64)
            delta_mm = (selected_arr - coord.reshape(1, 3).astype(np.float64)) * spacing
            if bool(np.any(np.sum(delta_mm * delta_mm, axis=1) < min_dist2)):
                continue
        selected.append(coord.copy())
        selected_scores.append(float(value))
        if len(selected) >= int(max_markers):
            break
    for marker_id, coord in enumerate(selected, start=1):
        markers[tuple(int(v) for v in coord)] = 1.0
    # [METRIC][Scope:task1_instance_seed]
    # selected marker 수는 Task1 Instance Precision/Recall 및 Split/Merge의 직접
    # 상한/하한으로 작동한다. trace에 후보 수, fallback, NMS radius를 남겨 fulltrain
    # gate 실패 시 seed 문제와 affinity 문제를 분리한다.
    return markers, {
        "seed_peak_policy": "channel3_local_peak_nms",
        "seed_peak_candidates": int(candidate_flat.size),
        "seed_peak_selected": int(len(selected)),
        "seed_peak_threshold": float(peak_threshold),
        "seed_peak_nms_radius_mm": float(nms_radius_mm),
        "seed_peak_max_markers": int(max_markers),
        "seed_peak_top1_fallback": bool(fallback_used),
        "seed_peak_selected_scores": selected_scores[:50],
    }


def decode_task1_v258_mutex13_seed_peak_healed(target: np.ndarray,
                                               spacing_zyx: tuple[float, float, float],
                                               *,
                                               support_threshold: float = 0.5,
                                               seed_threshold: float = 0.5,
                                               affinity_threshold: float = 0.5,
                                               mutex_threshold: float = 0.5,
                                               seed_peak_nms_radius_mm: float = 10.0,
                                               seed_peak_max_markers: int = 50) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V258 mutex graph with channel3 peak-NMS seed markers."""
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V258 decoder expects [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V258 decoder received NaN/Inf target/probabilities")
    support = arr[TASK1_V252_BASE_CHANNELS["support"]] >= float(support_threshold)
    seed_score = arr[TASK1_V252_BASE_CHANNELS["seed_center"]]
    peak_seed, peak_trace = _task1_v258_seed_peak_markers(
        seed_score,
        support,
        spacing_zyx,
        peak_threshold=seed_threshold,
        nms_radius_mm=seed_peak_nms_radius_mm,
        max_markers=seed_peak_max_markers,
    )
    shape = tuple(int(v) for v in support.shape)
    size = int(np.prod(shape))
    seed_cc, seed_n = ndi.label(peak_seed >= float(seed_threshold))
    if not support.any() or int(seed_n) <= 0:
        trace = {
            "decoder": "task1_v258_mutex13_seed_peak_healed",
            "support_threshold": float(support_threshold),
            "seed_threshold": float(seed_threshold),
            "affinity_threshold": float(affinity_threshold),
            "mutex_threshold": float(mutex_threshold),
            "support_voxels": int(support.sum()),
            "seed_components": int(seed_n),
            "pred_fragment_count": 0,
            "seed_healing_applied": False,
            "seed_healing_reason": "no_seed_or_no_decoded_support",
            **peak_trace,
        }
        return np.zeros(shape, dtype=np.uint16), trace

    attractive = np.clip(arr[TASK1_V255_ATTRACTIVE_START:TASK1_V255_REPULSIVE_START], 0.0, 1.0)
    repulsive = np.clip(arr[TASK1_V255_REPULSIVE_START:], 0.0, 1.0)
    support_idx = np.flatnonzero(support.reshape(-1))
    compact_index = np.full(size, -1, dtype=np.int64)
    compact_index[support_idx] = np.arange(int(support_idx.size), dtype=np.int64)
    flat_index = np.arange(size, dtype=np.int64).reshape(shape)
    edge_rows = []
    edge_cols = []
    joined_edges = 0
    valid_edges = 0
    for i, offset in enumerate(TASK1_V252_AFFINITY13_OFFSETS):
        src_sl, dst_sl = _task1_affinity_offset_slices(shape, offset)
        edge_valid = support[src_sl] & support[dst_sl]
        edge_join = (
            edge_valid
            & (attractive[i][src_sl] >= float(affinity_threshold))
            & (repulsive[i][src_sl] < float(mutex_threshold))
        )
        valid_edges += int(edge_valid.sum())
        joined_edges += int(edge_join.sum())
        if edge_join.any():
            edge_rows.append(compact_index[flat_index[src_sl][edge_join].reshape(-1)])
            edge_cols.append(compact_index[flat_index[dst_sl][edge_join].reshape(-1)])

    from scipy import sparse as sp
    from scipy.sparse.csgraph import connected_components

    n_support = int(support_idx.size)
    if edge_rows:
        rows = np.concatenate(edge_rows)
        cols = np.concatenate(edge_cols)
        graph = sp.coo_matrix(
            (
                np.ones(int(rows.size) * 2, dtype=np.bool_),
                (np.concatenate([rows, cols]), np.concatenate([cols, rows])),
            ),
            shape=(n_support, n_support),
        ).tocsr()
        component_count, labels = connected_components(graph, directed=False, return_labels=True)
    else:
        component_count = n_support
        labels = np.arange(n_support, dtype=np.int64)

    # [QC][Invariant:v258_component_healing_before_uint16]
    # V253/V255는 connected component ID를 바로 uint16 map에 쓰기 때문에 65k 초과
    # component에서 중단된다. V258은 Task1 marker seed로 component를 collapse한 뒤
    # uint16 instance ID를 만들기 때문에, component_count가 커도 여기서 실패시키지 않는다.
    _, nearest_idx = ndi.distance_transform_edt(
        seed_cc == 0,
        sampling=spacing_zyx,
        return_indices=True,
    )
    nearest_seed = seed_cc[tuple(nearest_idx)].reshape(-1)[support_idx].astype(np.int32, copy=False)
    labels = labels.astype(np.int64, copy=False)
    order = np.argsort(labels, kind="mergesort")
    sorted_labels = labels[order]
    sorted_seed = nearest_seed[order]
    component_assignment = np.zeros(int(component_count), dtype=np.uint16)
    start = 0
    while start < int(sorted_labels.size):
        comp = int(sorted_labels[start])
        end = start + 1
        while end < int(sorted_labels.size) and int(sorted_labels[end]) == comp:
            end += 1
        seeds = sorted_seed[start:end]
        seeds = seeds[seeds > 0]
        if seeds.size:
            counts = np.bincount(seeds.astype(np.int64), minlength=int(seed_n) + 1)
            component_assignment[comp] = np.uint16(int(np.argmax(counts)))
        start = end
    decoded_flat = np.zeros(size, dtype=np.uint16)
    decoded_flat[support_idx] = component_assignment[labels]
    decoded = decoded_flat.reshape(shape)
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    trace = {
        "decoder": "task1_v258_mutex13_seed_peak_healed",
        "support_threshold": float(support_threshold),
        "seed_threshold": float(seed_threshold),
        "affinity_threshold": float(affinity_threshold),
        "mutex_threshold": float(mutex_threshold),
        "support_voxels": int(support.sum()),
        "valid_affinity_edges": int(valid_edges),
        "joined_affinity_edges": int(joined_edges),
        "graph_component_count": int(component_count),
        "seed_components": int(seed_n),
        "pred_fragment_count": int(len(pred_ids)),
        "seed_healing_applied": True,
        "seed_healed_fragment_count": int(len(pred_ids)),
        "seedless_component_assignment": "nearest_peak_seed_majority",
        "join_rule": "support && attractive>=threshold && repulsive<mutex_threshold",
        "seed_peak_source_channel": "seed_center_channel3",
        "seed_body_original_voxels": int((arr[TASK1_V252_BASE_CHANNELS["seed_body"]] >= float(seed_threshold)).sum()),
        **peak_trace,
    }
    return decoded, trace


def decode_task1_v260_seed_fracture_watershed(target: np.ndarray,
                                              spacing_zyx: tuple[float, float, float],
                                              *,
                                              support_threshold: float = 0.5,
                                              seed_threshold: float = 0.5,
                                              fracture_threshold: float = 0.5,
                                              seed_peak_nms_radius_mm: float = 5.0,
                                              seed_peak_max_markers: int = 50) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V260 with channel3 seed peaks and channel2 fracture barrier energy.

    [AUDIT][Risk:High][Scope:v260_decoder_contract]
    V259 support-distance watershed over-split non-fractured Sacrum/RightHip,
    while graph-component healing merged fractured hips into one component. V260
    requires learned seed peaks and learned fracture energy; no top1 fallback is
    allowed because fallback hides the exact Task1 Instance/Topology failure.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V255_OUTPUT_CHANNELS):
        raise ValueError(f"V260 decoder expects [{TASK1_V255_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V260 decoder received NaN/Inf target/probabilities")
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V260 decoder: {spacing_zyx}")
    support_prob = np.clip(arr[TASK1_V252_BASE_CHANNELS["support"]], 0.0, 1.0)
    fracture_prob = np.clip(arr[TASK1_V252_BASE_CHANNELS["fracture_surface"]], 0.0, 1.0)
    seed_score = np.clip(arr[TASK1_V252_BASE_CHANNELS["seed_center"]], 0.0, 1.0)
    support = support_prob >= float(support_threshold)
    peak_seed, peak_trace = _task1_v258_seed_peak_markers(
        seed_score,
        support,
        spacing_zyx,
        peak_threshold=seed_threshold,
        nms_radius_mm=seed_peak_nms_radius_mm,
        max_markers=seed_peak_max_markers,
        allow_top1_fallback=False,
    )
    seed_cc, seed_n = ndi.label(peak_seed > 0.0)
    if not support.any() or int(seed_n) <= 0:
        trace = {
            "decoder": "task1_v260_seed_fracture_watershed",
            "support_threshold": float(support_threshold),
            "seed_threshold": float(seed_threshold),
            "fracture_threshold": float(fracture_threshold),
            "support_voxels": int(support.sum()),
            "seed_components": int(seed_n),
            "pred_fragment_count": 0,
            "watershed_applied": False,
            "watershed_reason": "no_support_or_no_decoder_visible_seed",
            "fracture_barrier_voxels": int((fracture_prob >= float(fracture_threshold)).sum()),
            **peak_trace,
        }
        return np.zeros(support.shape, dtype=np.uint16), trace

    # [METRIC][Scope:task1_fracture_instance_topology]
    # channel2 is not reported as a standalone threshold mask only; it is also
    # the watershed crossing cost that should keep seed regions from merging
    # across learned fracture surfaces at the fixed 0.50 contract.
    energy = (
        1.0
        + 12.0 * fracture_prob.astype(np.float32, copy=False)
        + 2.0 * (1.0 - support_prob.astype(np.float32, copy=False))
    )
    decoded = _watershed_assign_energy(seed_cc.astype(np.uint16, copy=False), support, energy)
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    trace = {
        "decoder": "task1_v260_seed_fracture_watershed",
        "support_threshold": float(support_threshold),
        "seed_threshold": float(seed_threshold),
        "fracture_threshold": float(fracture_threshold),
        "support_voxels": int(support.sum()),
        "seed_components": int(seed_n),
        "pred_fragment_count": int(len(pred_ids)),
        "watershed_applied": True,
        "watershed_energy": "1 + 12*fracture_prob + 2*(1-support_prob)",
        "fracture_barrier_voxels": int((fracture_prob >= float(fracture_threshold)).sum()),
        "fracture_prob_mean_support": float(fracture_prob[support].mean()) if support.any() else 0.0,
        "fracture_prob_max_support": float(fracture_prob[support].max()) if support.any() else 0.0,
        "seed_peak_source_channel": "seed_center_channel3",
        **peak_trace,
    }
    # [QA][Status:Not run][Scope:regression]
    # Expected: V258/V259 auto path remains unchanged; only V260 trainer metadata
    # selects this no-fallback watershed decoder.
    return decoded.astype(np.uint16, copy=False), trace


TASK1_V261_CHANNELS = {
    "support": 0,
    "exterior_context": 1,
    "fracture_surface": 2,
    "center_heatmap": 3,
    "distance_field": 4,
    "offset_to_center_z": 5,
    "offset_to_center_y": 6,
    "offset_to_center_x": 7,
}
TASK1_V261_OUTPUT_CHANNELS = 8

TASK1_V269_CHANNELS = {
    "support": 0,
    "flow_z": 1,
    "flow_y": 2,
    "flow_x": 3,
}
TASK1_V269_OUTPUT_CHANNELS = 4

TASK1_V270_CHANNELS = {
    "support": 0,
    "sink_z": 1,
    "sink_y": 2,
    "sink_x": 3,
}
TASK1_V270_OUTPUT_CHANNELS = 4

TASK1_V272_CHANNELS = {
    "support": 0,
    "seed_body": 1,
    "distance_field": 2,
}
TASK1_V272_OUTPUT_CHANNELS = 3


def compute_task1_v261_center_flow_oracle_target(inst_roi: np.ndarray,
                                                 spacing_zyx: tuple[float, float, float],
                                                 *,
                                                 exterior_mm: float = 3.0,
                                                 offset_scale_mm: float = 64.0,
                                                 distance_scale_mm: float = 20.0) -> tuple[np.ndarray, dict[str, Any]]:
    """Build the V261 dense center-flow oracle target for one anatomy ROI.

    [AUDIT][Risk:High][Scope:v261_decoder_contract]
    V260 failed because sparse seed visibility and thresholded fracture barriers
    did not provide a stable instance assignment signal. V261 follows the
    bottom-up center/flow pattern: every foreground voxel predicts a vector to
    its fragment center, so disconnected islands and thin fracture regions do
    not depend on a local contact threshold to recover Task1 topology metrics.

    [QC][Invariant:shape_range]
    The output is `[8, Z, Y, X]`. Channels 0..4 are probability-like oracle
    fields in `[0, 1]`; channels 5..7 are raw normalized physical offsets and
    may be negative or greater than 1.0.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V261 target: {spacing_zyx}")
    if float(offset_scale_mm) <= 0.0:
        raise ValueError(f"offset_scale_mm must be > 0, got {offset_scale_mm}")
    if float(distance_scale_mm) <= 0.0:
        raise ValueError(f"distance_scale_mm must be > 0, got {distance_scale_mm}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = inst > 0
    target = np.zeros((TASK1_V261_OUTPUT_CHANNELS, *inst.shape), dtype=np.float32)
    target[TASK1_V261_CHANNELS["support"]] = support.astype(np.float32)
    fragment_centers: list[dict[str, Any]] = []
    offset_abs_mm_max = 0.0
    if support.any():
        exterior = ndi.distance_transform_edt(~support, sampling=spacing_zyx) <= float(exterior_mm)
        target[TASK1_V261_CHANNELS["exterior_context"]] = (exterior & ~support).astype(np.float32)
        ids = [int(v) for v in np.unique(inst) if int(v) > 0]
        target[TASK1_V261_CHANNELS["fracture_surface"]] = get_contact_surface_regions(
            inst,
            contact_radius=1,
            surface_erosion_radius=1,
            groups={1: ids},
        ).astype(np.float32)
        spacing = np.asarray(spacing_zyx, dtype=np.float32).reshape(1, 3)
        for fragment_id in ids:
            fragment = inst == int(fragment_id)
            center, _body = _task1_v251_fragment_seed_body(
                fragment,
                spacing_zyx,
                radius_mm=1.0,
            )
            center_coords = np.argwhere(center >= 0.5)
            if int(center_coords.shape[0]) != 1:
                raise ValueError(
                    f"V261 center target expected one center for fragment {fragment_id}, "
                    f"got {int(center_coords.shape[0])}"
                )
            center_zyx = center_coords[0].astype(np.float32)
            target[TASK1_V261_CHANNELS["center_heatmap"]][tuple(center_coords[0])] = 1.0

            dist_mm = ndi.distance_transform_edt(fragment, sampling=spacing_zyx).astype(np.float32, copy=False)
            target[TASK1_V261_CHANNELS["distance_field"]][fragment] = np.clip(
                dist_mm[fragment] / float(distance_scale_mm),
                0.0,
                1.0,
            )

            coords = np.argwhere(fragment).astype(np.float32, copy=False)
            delta_mm = (center_zyx.reshape(1, 3) - coords) * spacing
            if coords.size:
                offset_abs_mm_max = max(offset_abs_mm_max, float(np.max(np.abs(delta_mm))))
                idx = tuple(coords.astype(np.int64, copy=False).T)
                for axis in range(3):
                    target[TASK1_V261_CHANNELS["offset_to_center_z"] + axis][idx] = (
                        delta_mm[:, axis] / float(offset_scale_mm)
                    ).astype(np.float32, copy=False)
            fragment_centers.append({
                "fragment_id": int(fragment_id),
                "center_zyx": [int(v) for v in center_coords[0]],
                "voxels": int(fragment.sum()),
            })

    center_cc, center_n = ndi.label(target[TASK1_V261_CHANNELS["center_heatmap"]] >= 0.5)
    fragment_count = int(len([v for v in np.unique(inst) if int(v) > 0]))
    audit = {
        "contract": "task1_v261_center_flow_oracle_target_v1",
        "channels": dict(TASK1_V261_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "fragment_count": int(fragment_count),
        "support_voxels": int(support.sum()),
        "fracture_surface_voxels": int(target[TASK1_V261_CHANNELS["fracture_surface"]].sum()),
        "center_components": int(center_n),
        "one_center_component_per_fragment": bool(int(center_n) == int(fragment_count)),
        "distance_field_max": float(target[TASK1_V261_CHANNELS["distance_field"]].max()) if support.any() else 0.0,
        "offset_scale_mm": float(offset_scale_mm),
        "offset_abs_mm_max": float(offset_abs_mm_max),
        "fragment_centers": fragment_centers[:50],
        "fragment_center_report_cap": 50,
    }
    if support.any() and not audit["one_center_component_per_fragment"]:
        # [QC][FailFast:v261_center_topology]
        # center-flow decoder의 instance 수 상한은 center component 수가 결정한다.
        # oracle에서 이 값이 GT fragment 수와 다르면 learned loss를 만들기 전에
        # target 생성 자체를 수정해야 한다.
        raise ValueError(
            "V261 oracle target center topology failed: "
            f"center_components={center_n}, fragment_count={fragment_count}"
        )
    return target, audit


def decode_task1_v261_center_flow(target: np.ndarray,
                                  spacing_zyx: tuple[float, float, float],
                                  *,
                                  support_threshold: float = 0.5,
                                  center_threshold: float = 0.5,
                                  offset_scale_mm: float = 64.0,
                                  max_vote_distance_mm: float | None = None) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode dense support + center + offset fields into Task1 instances.

    [METRIC][Risk:High][Scope:task1_instance_topology]
    V261 assignment is decoder-facing: support voxels vote to an instance center
    through channels 5..7, then inherit the nearest center ID. This directly
    targets Instance F1/Recall/Precision, Merge/Split, and Topology Consistency,
    while fracture surface remains an auxiliary metric head instead of the
    primary grouping mechanism.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V261_OUTPUT_CHANNELS):
        raise ValueError(f"V261 decoder expects [{TASK1_V261_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V261 decoder received NaN/Inf target/probabilities")
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V261 decoder: {spacing_zyx}")
    if float(offset_scale_mm) <= 0.0:
        raise ValueError(f"offset_scale_mm must be > 0, got {offset_scale_mm}")
    if max_vote_distance_mm is not None and float(max_vote_distance_mm) <= 0.0:
        raise ValueError(f"max_vote_distance_mm must be > 0 or None, got {max_vote_distance_mm}")

    support = arr[TASK1_V261_CHANNELS["support"]] >= float(support_threshold)
    center_mask = (arr[TASK1_V261_CHANNELS["center_heatmap"]] >= float(center_threshold)) & support
    center_cc, center_n = ndi.label(center_mask)
    shape = tuple(int(v) for v in support.shape)
    if not support.any() or int(center_n) <= 0:
        return np.zeros(shape, dtype=np.uint16), {
            "decoder": "task1_v261_center_flow",
            "support_threshold": float(support_threshold),
            "center_threshold": float(center_threshold),
            "offset_scale_mm": float(offset_scale_mm),
            "support_voxels": int(support.sum()),
            "center_components": int(center_n),
            "pred_fragment_count": 0,
            "assignment_applied": False,
            "assignment_reason": "no_support_or_no_center",
        }

    centers = np.zeros((int(center_n), 3), dtype=np.float64)
    center_scores = arr[TASK1_V261_CHANNELS["center_heatmap"]]
    for marker_id in range(1, int(center_n) + 1):
        coords = np.argwhere(center_cc == int(marker_id)).astype(np.float64, copy=False)
        weights = center_scores[center_cc == int(marker_id)].astype(np.float64, copy=False)
        if weights.size and float(weights.sum()) > 0.0:
            centers[int(marker_id) - 1] = np.average(coords, axis=0, weights=weights)
        else:
            centers[int(marker_id) - 1] = coords.mean(axis=0)

    support_coords = np.argwhere(support).astype(np.float64, copy=False)
    support_idx = tuple(support_coords.astype(np.int64, copy=False).T)
    offsets = np.stack([
        arr[TASK1_V261_CHANNELS["offset_to_center_z"]][support],
        arr[TASK1_V261_CHANNELS["offset_to_center_y"]][support],
        arr[TASK1_V261_CHANNELS["offset_to_center_x"]][support],
    ], axis=1).astype(np.float64, copy=False)
    spacing = np.asarray(spacing_zyx, dtype=np.float64).reshape(1, 3)
    votes_zyx = support_coords + (offsets * float(offset_scale_mm) / spacing)
    centers_mm = centers * spacing
    votes_mm = votes_zyx * spacing

    from scipy.spatial import cKDTree

    tree = cKDTree(centers_mm)
    distances, nearest = tree.query(votes_mm, k=1)
    if max_vote_distance_mm is None:
        valid = np.ones(distances.shape, dtype=bool)
    else:
        valid = distances <= float(max_vote_distance_mm)
    decoded = np.zeros(shape, dtype=np.uint16)
    valid_coords = tuple(support_coords[valid].astype(np.int64, copy=False).T)
    decoded[valid_coords] = (nearest[valid].astype(np.uint32) + 1).astype(np.uint16)
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    return decoded, {
        "decoder": "task1_v261_center_flow",
        "support_threshold": float(support_threshold),
        "center_threshold": float(center_threshold),
        "offset_scale_mm": float(offset_scale_mm),
        "max_vote_distance_mm": None if max_vote_distance_mm is None else float(max_vote_distance_mm),
        "support_voxels": int(support.sum()),
        "assigned_support_voxels": int(valid.sum()),
        "unassigned_support_voxels": int(valid.size - int(valid.sum())),
        "center_components": int(center_n),
        "pred_fragment_count": int(len(pred_ids)),
        "assignment_applied": True,
        "assignment_policy": "nearest_center_after_dense_offset_vote",
        "vote_distance_mm_mean": float(np.mean(distances)) if distances.size else 0.0,
        "vote_distance_mm_p95": float(np.percentile(distances, 95)) if distances.size else 0.0,
        "vote_distance_mm_max": float(np.max(distances)) if distances.size else 0.0,
    }


def _task1_v262_peak_seed_mask(center_prob: np.ndarray,
                               support: np.ndarray,
                               *,
                               center_threshold: float,
                               peak_nms_size_vox: int) -> tuple[np.ndarray, dict[str, Any]]:
    """Return one decoder seed per local peak plateau for V262 center-flow."""
    if int(peak_nms_size_vox) < 1 or int(peak_nms_size_vox) % 2 == 0:
        raise ValueError(f"peak_nms_size_vox must be odd and >=1, got {peak_nms_size_vox}")
    score = np.asarray(center_prob, dtype=np.float32)
    support = np.asarray(support, dtype=bool)
    if score.shape != support.shape:
        raise ValueError(f"V262 peak seed shape mismatch: center={score.shape} support={support.shape}")
    if not np.isfinite(score).all():
        raise ValueError("V262 center probability contains NaN/Inf")
    if not support.any():
        return np.zeros(score.shape, dtype=bool), {
            "peak_nms_size_vox": int(peak_nms_size_vox),
            "raw_local_peak_voxels": 0,
            "raw_peak_plateaus": 0,
            "peak_count_after_nms": 0,
        }
    pooled = ndi.maximum_filter(
        score,
        size=int(peak_nms_size_vox),
        mode="constant",
        cval=-np.inf,
    )
    raw_peak = (score >= float(center_threshold)) & support & (score >= pooled - 1e-7)
    plateau_cc, plateau_n = ndi.label(raw_peak)
    seeds = np.zeros(score.shape, dtype=bool)
    for plateau_id in range(1, int(plateau_n) + 1):
        coords = np.argwhere(plateau_cc == int(plateau_id))
        if coords.size == 0:
            continue
        vals = score[tuple(coords.T)]
        # [QC][Invariant:deterministic_peak_tie_break]
        # maximum_filter는 plateau 전체를 local maximum으로 표시할 수 있다. plateau당
        # 하나의 voxel만 남겨야 decoder center 수가 Task1 Split/Instance Precision과
        # 직접 대응한다. argmax tie는 np.argmax의 첫 좌표로 deterministic하게 처리한다.
        chosen = coords[int(np.argmax(vals))]
        seeds[tuple(int(v) for v in chosen)] = True
    return seeds, {
        "peak_nms_size_vox": int(peak_nms_size_vox),
        "raw_local_peak_voxels": int(raw_peak.sum()),
        "raw_peak_plateaus": int(plateau_n),
        "peak_count_after_nms": int(seeds.sum()),
    }


def decode_task1_v262_center_peak_flow(target: np.ndarray,
                                       spacing_zyx: tuple[float, float, float],
                                       *,
                                       support_threshold: float = 0.5,
                                       center_threshold: float = 0.5,
                                       peak_nms_size_vox: int = 31,
                                       offset_scale_mm: float = 64.0,
                                       max_vote_distance_mm: float | None = None) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V262 support + center peak + offset fields into Task1 instances.

    [METRIC][Risk:High][Scope:task1_primary_gate]
    V262 decoder는 center>=0.50 connected components를 쓰지 않는다. channel3
    local peak-NMS seed만 marker로 사용해 사용자가 준 Instance F1/Precision,
    Merge/Split, Topology Consistency 축을 직접 겨냥한다. IoU-F는 diagnostic only다.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V261_OUTPUT_CHANNELS):
        raise ValueError(f"V262 decoder expects [{TASK1_V261_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V262 decoder received NaN/Inf target/probabilities")
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V262 decoder: {spacing_zyx}")
    if float(offset_scale_mm) <= 0.0:
        raise ValueError(f"offset_scale_mm must be > 0, got {offset_scale_mm}")
    if max_vote_distance_mm is not None and float(max_vote_distance_mm) <= 0.0:
        raise ValueError(f"max_vote_distance_mm must be > 0 or None, got {max_vote_distance_mm}")

    support = arr[TASK1_V261_CHANNELS["support"]] >= float(support_threshold)
    peak_mask, peak_trace = _task1_v262_peak_seed_mask(
        arr[TASK1_V261_CHANNELS["center_heatmap"]],
        support,
        center_threshold=center_threshold,
        peak_nms_size_vox=peak_nms_size_vox,
    )
    center_cc, center_n = ndi.label(peak_mask)
    shape = tuple(int(v) for v in support.shape)
    if not support.any() or int(center_n) <= 0:
        trace = {
            "decoder": "task1_v262_center_peak_flow",
            "support_threshold": float(support_threshold),
            "center_threshold": float(center_threshold),
            "offset_scale_mm": float(offset_scale_mm),
            "support_voxels": int(support.sum()),
            "center_components": int(center_n),
            "pred_fragment_count": 0,
            "assignment_applied": False,
            "assignment_reason": "no_support_or_no_peak_center",
        }
        trace.update(peak_trace)
        return np.zeros(shape, dtype=np.uint16), trace

    centers = np.zeros((int(center_n), 3), dtype=np.float64)
    center_scores = arr[TASK1_V261_CHANNELS["center_heatmap"]]
    for marker_id in range(1, int(center_n) + 1):
        coords = np.argwhere(center_cc == int(marker_id)).astype(np.float64, copy=False)
        weights = center_scores[center_cc == int(marker_id)].astype(np.float64, copy=False)
        if weights.size and float(weights.sum()) > 0.0:
            centers[int(marker_id) - 1] = np.average(coords, axis=0, weights=weights)
        else:
            centers[int(marker_id) - 1] = coords.mean(axis=0)

    support_coords = np.argwhere(support).astype(np.float64, copy=False)
    offsets = np.stack([
        arr[TASK1_V261_CHANNELS["offset_to_center_z"]][support],
        arr[TASK1_V261_CHANNELS["offset_to_center_y"]][support],
        arr[TASK1_V261_CHANNELS["offset_to_center_x"]][support],
    ], axis=1).astype(np.float64, copy=False)
    spacing = np.asarray(spacing_zyx, dtype=np.float64).reshape(1, 3)
    votes_zyx = support_coords + (offsets * float(offset_scale_mm) / spacing)
    centers_mm = centers * spacing
    votes_mm = votes_zyx * spacing

    from scipy.spatial import cKDTree

    tree = cKDTree(centers_mm)
    distances, nearest = tree.query(votes_mm, k=1)
    if max_vote_distance_mm is None:
        valid = np.ones(distances.shape, dtype=bool)
    else:
        valid = distances <= float(max_vote_distance_mm)
    decoded = np.zeros(shape, dtype=np.uint16)
    valid_coords = tuple(support_coords[valid].astype(np.int64, copy=False).T)
    decoded[valid_coords] = (nearest[valid].astype(np.uint32) + 1).astype(np.uint16)
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    trace = {
        "decoder": "task1_v262_center_peak_flow",
        "support_threshold": float(support_threshold),
        "center_threshold": float(center_threshold),
        "offset_scale_mm": float(offset_scale_mm),
        "max_vote_distance_mm": None if max_vote_distance_mm is None else float(max_vote_distance_mm),
        "support_voxels": int(support.sum()),
        "assigned_support_voxels": int(valid.sum()),
        "unassigned_support_voxels": int(valid.size - int(valid.sum())),
        "center_components": int(center_n),
        "pred_fragment_count": int(len(pred_ids)),
        "assignment_applied": True,
        "assignment_policy": "nearest_peak_center_after_dense_offset_vote",
        "vote_distance_mm_mean": float(np.mean(distances)) if distances.size else 0.0,
        "vote_distance_mm_p95": float(np.percentile(distances, 95)) if distances.size else 0.0,
        "vote_distance_mm_max": float(np.max(distances)) if distances.size else 0.0,
    }
    trace.update(peak_trace)
    return decoded, trace


def compute_task1_v269_dense_flow_oracle_target(inst_roi: np.ndarray,
                                                spacing_zyx: tuple[float, float, float]) -> tuple[np.ndarray, dict[str, Any]]:
    """Build a contact-free dense instance-flow oracle target for one anatomy ROI.

    [AUDIT][Risk:Blocker][Scope:v269_contact_removal]
    V247-V266 contact/fracture heads failed the Task1 proxy gate, V267 sparse
    center/absolute offset collapsed, and V268 local pairwise edges joined
    different fragments. V269 removes contact supervision entirely and makes
    instance identity a dense decoder-facing vector field: every support voxel
    predicts a bounded one-voxel step toward its own fragment sink.

    [QC][Invariant:channel_order]
    Output is `[4, Z, Y, X]`: support probability plus z/y/x flow components.
    Flow values are bounded to `[-1, 1]`; they are not contact probabilities and
    must not be thresholded as fracture/contact evidence.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V269 target: {spacing_zyx}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = inst > 0
    target = np.zeros((TASK1_V269_OUTPUT_CHANNELS, *inst.shape), dtype=np.float32)
    target[TASK1_V269_CHANNELS["support"]] = support.astype(np.float32)
    fragment_rows: list[dict[str, Any]] = []
    max_sink_distance_vox = 0.0
    zero_flow_support_voxels = 0
    for fragment_id in [int(v) for v in np.unique(inst) if int(v) > 0]:
        fragment = inst == int(fragment_id)
        center, _body = _task1_v251_fragment_seed_body(fragment, spacing_zyx, radius_mm=1.0)
        center_coords = np.argwhere(center >= 0.5)
        if int(center_coords.shape[0]) != 1:
            raise ValueError(
                f"V269 expected one sink center for fragment {fragment_id}, got {int(center_coords.shape[0])}"
            )
        center_zyx = center_coords[0].astype(np.float32, copy=False)
        coords = np.argwhere(fragment).astype(np.float32, copy=False)
        delta = center_zyx.reshape(1, 3) - coords
        distance = np.linalg.norm(delta, axis=1)
        max_sink_distance_vox = max(max_sink_distance_vox, float(distance.max()) if distance.size else 0.0)
        denom = np.maximum(distance, 1.0).reshape(-1, 1)
        flow = delta / denom
        idx = tuple(coords.astype(np.int64, copy=False).T)
        for axis, name in enumerate(("flow_z", "flow_y", "flow_x")):
            target[TASK1_V269_CHANNELS[name]][idx] = flow[:, axis].astype(np.float32, copy=False)
        zero_flow_support_voxels += int(np.count_nonzero(distance < 1e-6))
        fragment_rows.append({
            "fragment_id": int(fragment_id),
            "sink_zyx": [int(v) for v in center_coords[0]],
            "voxels": int(fragment.sum()),
            "max_sink_distance_vox": float(distance.max()) if distance.size else 0.0,
        })

    flow_mag = np.sqrt(
        np.sum(
            np.stack([
                target[TASK1_V269_CHANNELS["flow_z"]],
                target[TASK1_V269_CHANNELS["flow_y"]],
                target[TASK1_V269_CHANNELS["flow_x"]],
            ], axis=0) ** 2,
            axis=0,
        )
    )
    audit = {
        "contract": "task1_v269_dense_instance_flow_oracle_target_v1",
        "channels": dict(TASK1_V269_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "fragment_count": int(len(fragment_rows)),
        "support_voxels": int(support.sum()),
        "flow_mag_support_mean": float(flow_mag[support].mean()) if support.any() else 0.0,
        "flow_mag_support_min": float(flow_mag[support].min()) if support.any() else 0.0,
        "flow_mag_support_max": float(flow_mag[support].max()) if support.any() else 0.0,
        "max_sink_distance_vox": float(max_sink_distance_vox),
        "zero_flow_support_voxels": int(zero_flow_support_voxels),
        "fragment_centers": fragment_rows[:50],
        "fragment_center_report_cap": 50,
    }
    return target, audit


def _task1_v269_cluster_endpoint_votes(endpoints: np.ndarray,
                                       *,
                                       cluster_radius_vox: float,
                                       min_endpoint_votes: int) -> tuple[np.ndarray, dict[str, Any]]:
    """Cluster flow-dynamics endpoints and return one label per endpoint row."""
    if float(cluster_radius_vox) <= 0.0:
        raise ValueError(f"cluster_radius_vox must be > 0, got {cluster_radius_vox}")
    if int(min_endpoint_votes) < 1:
        raise ValueError(f"min_endpoint_votes must be >= 1, got {min_endpoint_votes}")
    points = np.asarray(endpoints, dtype=np.int64)
    if points.ndim != 2 or int(points.shape[1]) != 3:
        raise ValueError(f"V269 endpoint array must have shape [N,3], got {points.shape}")
    if int(points.shape[0]) == 0:
        return np.zeros((0,), dtype=np.uint16), {
            "unique_endpoint_count": 0,
            "endpoint_cluster_count_raw": 0,
            "endpoint_cluster_count_kept": 0,
            "dropped_endpoint_votes": 0,
        }

    unique_points, inverse, counts = np.unique(points, axis=0, return_inverse=True, return_counts=True)
    n_points = int(unique_points.shape[0])
    parent = np.arange(n_points, dtype=np.int64)

    def find(i: int) -> int:
        while int(parent[i]) != int(i):
            parent[i] = parent[int(parent[i])]
            i = int(parent[i])
        return int(i)

    def union(a: int, b: int) -> None:
        ra = find(int(a))
        rb = find(int(b))
        if ra != rb:
            parent[rb] = ra

    from scipy.spatial import cKDTree

    tree = cKDTree(unique_points.astype(np.float32, copy=False))
    for a, b in tree.query_pairs(r=float(cluster_radius_vox)):
        union(int(a), int(b))
    roots = np.asarray([find(i) for i in range(n_points)], dtype=np.int64)
    root_to_indices: dict[int, list[int]] = {}
    for idx, root in enumerate(roots):
        root_to_indices.setdefault(int(root), []).append(int(idx))

    cluster_rows = []
    for root, indices in root_to_indices.items():
        vote_count = int(np.sum(counts[indices]))
        centroid = np.average(unique_points[indices].astype(np.float64, copy=False), axis=0, weights=counts[indices])
        cluster_rows.append((int(root), vote_count, centroid))
    cluster_rows.sort(key=lambda row: (float(row[2][0]), float(row[2][1]), float(row[2][2]), -int(row[1])))
    kept_roots = [root for root, votes, _centroid in cluster_rows if int(votes) >= int(min_endpoint_votes)]
    root_label = {int(root): int(i + 1) for i, root in enumerate(kept_roots)}
    unique_labels = np.zeros((n_points,), dtype=np.uint16)
    for idx, root in enumerate(roots):
        label = root_label.get(int(root), 0)
        unique_labels[idx] = np.uint16(label)
    labels = unique_labels[inverse]
    dropped_votes = int(np.count_nonzero(labels == 0))
    return labels.astype(np.uint16, copy=False), {
        "unique_endpoint_count": int(n_points),
        "endpoint_cluster_count_raw": int(len(cluster_rows)),
        "endpoint_cluster_count_kept": int(len(kept_roots)),
        "min_endpoint_votes": int(min_endpoint_votes),
        "cluster_radius_vox": float(cluster_radius_vox),
        "dropped_endpoint_votes": int(dropped_votes),
    }


def decode_task1_v269_dense_flow(target: np.ndarray,
                                 *,
                                 support_threshold: float = 0.5,
                                 dynamics_steps: int = 256,
                                 step_size_vox: float = 1.0,
                                 endpoint_cluster_radius_vox: float = 2.0,
                                 min_endpoint_votes: int = 8) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode contact-free dense flow dynamics into Task1 instances.

    [METRIC][Risk:Blocker][Scope:task1_fulltrain_gate]
    V269 derives instances from support + flow endpoint clusters only. Fracture
    Dice proxy is therefore a downstream consequence of decoded instance
    adjacency, not a supervised contact channel.
    """
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V269_OUTPUT_CHANNELS):
        raise ValueError(f"V269 decoder expects [{TASK1_V269_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V269 decoder received NaN/Inf target/probabilities")
    if int(dynamics_steps) < 1:
        raise ValueError(f"dynamics_steps must be >= 1, got {dynamics_steps}")
    if float(step_size_vox) <= 0.0:
        raise ValueError(f"step_size_vox must be > 0, got {step_size_vox}")
    support = arr[TASK1_V269_CHANNELS["support"]] >= float(support_threshold)
    shape = tuple(int(v) for v in support.shape)
    if not support.any():
        return np.zeros(shape, dtype=np.uint16), {
            "decoder": "task1_v269_dense_instance_flow",
            "support_threshold": float(support_threshold),
            "support_voxels": 0,
            "pred_fragment_count": 0,
            "assignment_applied": False,
            "assignment_reason": "no_support",
        }

    support_coords_i64 = np.argwhere(support).astype(np.int64, copy=False)
    pos = support_coords_i64.astype(np.float32, copy=True)
    max_zyx = np.asarray(shape, dtype=np.float32).reshape(1, 3) - 1.0
    flow_fields = np.stack([
        arr[TASK1_V269_CHANNELS["flow_z"]],
        arr[TASK1_V269_CHANNELS["flow_y"]],
        arr[TASK1_V269_CHANNELS["flow_x"]],
    ], axis=0).astype(np.float32, copy=False)

    # [QC][Invariant:flow_range]
    # Oracle target은 [-1, 1] bounded local step field다. Learned logits path에서도
    # tanh 후 이 decoder를 써야 하므로, flow magnitude 폭주가 있으면 dynamics가 ROI
    # 밖으로 클리핑되어 split/merge 원인 추적이 어려워진다.
    flow_abs_max = float(np.max(np.abs(flow_fields[:, support]))) if support.any() else 0.0
    if flow_abs_max > 1.0001:
        raise ValueError(f"V269 flow components must be bounded to [-1, 1], got abs max {flow_abs_max}")

    last_mean_step = 0.0
    for _step in range(int(dynamics_steps)):
        idx = np.rint(pos).astype(np.int64, copy=False)
        for axis, dim in enumerate(shape):
            idx[:, axis] = np.clip(idx[:, axis], 0, int(dim) - 1)
        vectors = np.stack([
            flow_fields[0, idx[:, 0], idx[:, 1], idx[:, 2]],
            flow_fields[1, idx[:, 0], idx[:, 1], idx[:, 2]],
            flow_fields[2, idx[:, 0], idx[:, 1], idx[:, 2]],
        ], axis=1)
        step = vectors * float(step_size_vox)
        last_mean_step = float(np.linalg.norm(step, axis=1).mean()) if step.size else 0.0
        pos += step
        pos = np.minimum(np.maximum(pos, 0.0), max_zyx)

    endpoints = np.rint(pos).astype(np.int64, copy=False)
    for axis, dim in enumerate(shape):
        endpoints[:, axis] = np.clip(endpoints[:, axis], 0, int(dim) - 1)
    labels, cluster_trace = _task1_v269_cluster_endpoint_votes(
        endpoints,
        cluster_radius_vox=endpoint_cluster_radius_vox,
        min_endpoint_votes=min_endpoint_votes,
    )
    decoded = np.zeros(shape, dtype=np.uint16)
    decoded[tuple(support_coords_i64.T)] = labels
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    trace = {
        "decoder": "task1_v269_dense_instance_flow",
        "support_threshold": float(support_threshold),
        "dynamics_steps": int(dynamics_steps),
        "step_size_vox": float(step_size_vox),
        "support_voxels": int(support.sum()),
        "assigned_support_voxels": int(np.count_nonzero(labels > 0)),
        "unassigned_support_voxels": int(np.count_nonzero(labels == 0)),
        "pred_fragment_count": int(len(pred_ids)),
        "assignment_applied": True,
        "assignment_policy": "endpoint_clustering_after_dense_flow_dynamics",
        "flow_abs_max": float(flow_abs_max),
        "last_mean_step_vox": float(last_mean_step),
    }
    trace.update(cluster_trace)
    return decoded, trace


def compute_task1_v270_spatial_embedding_oracle_target(inst_roi: np.ndarray,
                                                       spacing_zyx: tuple[float, float, float]) -> tuple[np.ndarray, dict[str, Any]]:
    """Build a contact-free dense spatial-embedding oracle target.

    [AUDIT][Risk:Blocker][Scope:v270_instance_identity]
    V269 flow dynamics produced an oracle split/merge tradeoff: endpoint radius
    changes reduced splits but merged true fragments. V270 switches to the
    spatial-embedding family: each support voxel predicts the normalized sink
    coordinate of its own fragment, and the decoder clusters those dense
    embeddings directly. Contact/fracture is still derived only after instance
    reconstruction.

    [QC][Invariant:range]
    Channels 1..3 are normalized ROI coordinates in `[0, 1]`; they are bounded
    decoder-facing embedding coordinates, not offsets and not logits.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V270 target: {spacing_zyx}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = inst > 0
    target = np.zeros((TASK1_V270_OUTPUT_CHANNELS, *inst.shape), dtype=np.float32)
    target[TASK1_V270_CHANNELS["support"]] = support.astype(np.float32)
    shape = np.asarray(inst.shape, dtype=np.float32)
    denom = np.maximum(shape - 1.0, 1.0)
    fragment_rows: list[dict[str, Any]] = []
    for fragment_id in [int(v) for v in np.unique(inst) if int(v) > 0]:
        fragment = inst == int(fragment_id)
        center, _body = _task1_v251_fragment_seed_body(fragment, spacing_zyx, radius_mm=1.0)
        center_coords = np.argwhere(center >= 0.5)
        if int(center_coords.shape[0]) != 1:
            raise ValueError(
                f"V270 expected one sink center for fragment {fragment_id}, got {int(center_coords.shape[0])}"
            )
        sink = center_coords[0].astype(np.float32, copy=False)
        sink_norm = sink / denom
        idx = np.where(fragment)
        for axis, name in enumerate(("sink_z", "sink_y", "sink_x")):
            target[TASK1_V270_CHANNELS[name]][idx] = float(sink_norm[axis])
        fragment_rows.append({
            "fragment_id": int(fragment_id),
            "sink_zyx": [int(v) for v in center_coords[0]],
            "sink_normalized_zyx": [float(v) for v in sink_norm],
            "voxels": int(fragment.sum()),
        })
    audit = {
        "contract": "task1_v270_dense_spatial_embedding_oracle_target_v1",
        "channels": dict(TASK1_V270_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "fragment_count": int(len(fragment_rows)),
        "support_voxels": int(support.sum()),
        "embedding_coordinate_space": "normalized_roi_zyx",
        "fragment_centers": fragment_rows[:50],
        "fragment_center_report_cap": 50,
    }
    return target, audit


def decode_task1_v270_spatial_embedding(target: np.ndarray,
                                        *,
                                        support_threshold: float = 0.5,
                                        embedding_cluster_radius_vox: float = 1.5,
                                        min_cluster_votes: int = 8) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode dense spatial embeddings into Task1 instances."""
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V270_OUTPUT_CHANNELS):
        raise ValueError(f"V270 decoder expects [{TASK1_V270_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V270 decoder received NaN/Inf target/probabilities")
    if float(embedding_cluster_radius_vox) <= 0.0:
        raise ValueError(f"embedding_cluster_radius_vox must be > 0, got {embedding_cluster_radius_vox}")
    if int(min_cluster_votes) < 1:
        raise ValueError(f"min_cluster_votes must be >= 1, got {min_cluster_votes}")
    support = arr[TASK1_V270_CHANNELS["support"]] >= float(support_threshold)
    shape = tuple(int(v) for v in support.shape)
    if not support.any():
        return np.zeros(shape, dtype=np.uint16), {
            "decoder": "task1_v270_dense_spatial_embedding",
            "support_threshold": float(support_threshold),
            "support_voxels": 0,
            "pred_fragment_count": 0,
            "assignment_applied": False,
            "assignment_reason": "no_support",
        }

    sink_norm = np.stack([
        arr[TASK1_V270_CHANNELS["sink_z"]][support],
        arr[TASK1_V270_CHANNELS["sink_y"]][support],
        arr[TASK1_V270_CHANNELS["sink_x"]][support],
    ], axis=1).astype(np.float32, copy=False)
    if float(sink_norm.min()) < -1e-5 or float(sink_norm.max()) > 1.00001:
        raise ValueError(
            f"V270 normalized sink coordinates must be in [0,1], "
            f"got min={float(sink_norm.min())} max={float(sink_norm.max())}"
        )
    denom = np.maximum(np.asarray(shape, dtype=np.float32) - 1.0, 1.0).reshape(1, 3)
    sink_vox = sink_norm * denom
    sink_points = np.rint(sink_vox).astype(np.int64, copy=False)
    for axis, dim in enumerate(shape):
        sink_points[:, axis] = np.clip(sink_points[:, axis], 0, int(dim) - 1)
    labels, cluster_trace = _task1_v269_cluster_endpoint_votes(
        sink_points,
        cluster_radius_vox=embedding_cluster_radius_vox,
        min_endpoint_votes=min_cluster_votes,
    )
    support_coords = np.argwhere(support).astype(np.int64, copy=False)
    decoded = np.zeros(shape, dtype=np.uint16)
    decoded[tuple(support_coords.T)] = labels
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    trace = {
        "decoder": "task1_v270_dense_spatial_embedding",
        "support_threshold": float(support_threshold),
        "embedding_cluster_radius_vox": float(embedding_cluster_radius_vox),
        "min_cluster_votes": int(min_cluster_votes),
        "support_voxels": int(support.sum()),
        "assigned_support_voxels": int(np.count_nonzero(labels > 0)),
        "unassigned_support_voxels": int(np.count_nonzero(labels == 0)),
        "pred_fragment_count": int(len(pred_ids)),
        "assignment_applied": True,
        "assignment_policy": "cluster_dense_normalized_sink_coordinates",
    }
    trace.update({
        "unique_embedding_point_count": cluster_trace["unique_endpoint_count"],
        "embedding_cluster_count_raw": cluster_trace["endpoint_cluster_count_raw"],
        "embedding_cluster_count_kept": cluster_trace["endpoint_cluster_count_kept"],
        "dropped_embedding_votes": cluster_trace["dropped_endpoint_votes"],
    })
    return decoded, trace


def compute_task1_v272_distance_marker_oracle_target(inst_roi: np.ndarray,
                                                     spacing_zyx: tuple[float, float, float],
                                                     *,
                                                     seed_radius_mm: float = 1.0) -> tuple[np.ndarray, dict[str, Any]]:
    """Build V272 support + marker + internal-distance oracle target.

    [AUDIT][Risk:Blocker][Scope:v272_instance_identity]
    V270/V271 showed that continuous sink-coordinate regression can pass an
    oracle decoder while learned outputs collapse small fracture fragments into
    anatomy-level sinks. V272 switches to a marker-controlled watershed contract:
    one marker seed per fragment and a dense internal distance field used only
    as watershed energy. Contact/fracture channels remain absent.

    [QC][Invariant:roi_decoder]
    This target is defined per anatomy ROI bbox. Full-volume watershed was
    measured as too slow; V272 must stay ROI-bounded for evaluation and training
    diagnostics.
    """
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V272 target: {spacing_zyx}")
    if float(seed_radius_mm) <= 0.0:
        raise ValueError(f"seed_radius_mm must be > 0, got {seed_radius_mm}")
    inst = np.asarray(inst_roi).astype(np.uint16, copy=False)
    support = inst > 0
    target = np.zeros((TASK1_V272_OUTPUT_CHANNELS, *inst.shape), dtype=np.float32)
    target[TASK1_V272_CHANNELS["support"]] = support.astype(np.float32)
    fragment_rows: list[dict[str, Any]] = []
    for fragment_id in [int(v) for v in np.unique(inst) if int(v) > 0]:
        fragment = inst == int(fragment_id)
        dist_mm = ndi.distance_transform_edt(fragment, sampling=spacing_zyx).astype(np.float32, copy=False)
        max_dist = float(dist_mm[fragment].max()) if bool(fragment.any()) else 0.0
        if max_dist > 0.0:
            target[TASK1_V272_CHANNELS["distance_field"]][fragment] = np.clip(
                dist_mm[fragment] / max_dist,
                0.0,
                1.0,
            )
        center, body = _task1_v251_fragment_seed_body(fragment, spacing_zyx, radius_mm=seed_radius_mm)
        if not bool(body.any()):
            body = center
        target[TASK1_V272_CHANNELS["seed_body"]][body.astype(bool, copy=False)] = 1.0
        fragment_rows.append({
            "fragment_id": int(fragment_id),
            "voxels": int(fragment.sum()),
            "seed_voxels": int(body.sum()),
            "distance_max_mm": float(max_dist),
        })
    audit = {
        "contract": "task1_v272_distance_marker_watershed_oracle_target_v1",
        "channels": dict(TASK1_V272_CHANNELS),
        "shape": [int(v) for v in inst.shape],
        "fragment_count": int(len(fragment_rows)),
        "support_voxels": int(support.sum()),
        "seed_radius_mm": float(seed_radius_mm),
        "distance_field": "per_fragment_internal_distance_normalized_to_unit_peak",
        "fragments": fragment_rows[:50],
        "fragment_report_cap": 50,
    }
    return target, audit


def decode_task1_v272_distance_marker_watershed(target: np.ndarray,
                                                spacing_zyx: tuple[float, float, float],
                                                *,
                                                support_threshold: float = 0.5,
                                                seed_threshold: float = 0.5) -> tuple[np.ndarray, dict[str, Any]]:
    """Decode V272 fields with ROI-bounded marker-controlled watershed."""
    arr = np.asarray(target, dtype=np.float32)
    if arr.ndim != 4 or int(arr.shape[0]) != int(TASK1_V272_OUTPUT_CHANNELS):
        raise ValueError(f"V272 decoder expects [{TASK1_V272_OUTPUT_CHANNELS},Z,Y,X], got {arr.shape}")
    if not np.isfinite(arr).all():
        raise ValueError("V272 decoder received NaN/Inf fields")
    if len(spacing_zyx) != 3 or any(float(v) <= 0.0 for v in spacing_zyx):
        raise ValueError(f"invalid spacing_zyx for V272 decoder: {spacing_zyx}")
    support = arr[TASK1_V272_CHANNELS["support"]] >= float(support_threshold)
    seed = (arr[TASK1_V272_CHANNELS["seed_body"]] >= float(seed_threshold)) & support
    distance = np.clip(arr[TASK1_V272_CHANNELS["distance_field"]], 0.0, 1.0)
    shape = tuple(int(v) for v in support.shape)
    if not bool(support.any()):
        return np.zeros(shape, dtype=np.uint16), {
            "decoder": "task1_v272_distance_marker_watershed",
            "support_threshold": float(support_threshold),
            "seed_threshold": float(seed_threshold),
            "support_voxels": 0,
            "seed_components": 0,
            "pred_fragment_count": 0,
            "watershed_applied": False,
            "watershed_reason": "no_support",
        }
    seed_cc, seed_n = ndi.label(seed, structure=np.ones((3, 3, 3), dtype=np.uint8))
    if int(seed_n) == 0:
        return np.zeros(shape, dtype=np.uint16), {
            "decoder": "task1_v272_distance_marker_watershed",
            "support_threshold": float(support_threshold),
            "seed_threshold": float(seed_threshold),
            "support_voxels": int(support.sum()),
            "seed_voxels": int(seed.sum()),
            "seed_components": 0,
            "pred_fragment_count": 0,
            "watershed_applied": False,
            "watershed_reason": "no_seed_components",
        }
    from skimage.segmentation import watershed

    # [METRIC][Scope:v272_decoder_energy]
    # Higher distance means more likely fragment interior. Watershed minimizes
    # energy, so use negative distance. No contact probability participates.
    decoded = watershed(
        (-distance).astype(np.float32, copy=False),
        seed_cc.astype(np.int32, copy=False),
        mask=support,
        connectivity=1,
        watershed_line=False,
    ).astype(np.uint16, copy=False)
    pred_ids = [int(v) for v in np.unique(decoded) if int(v) > 0]
    trace = {
        "decoder": "task1_v272_distance_marker_watershed",
        "support_threshold": float(support_threshold),
        "seed_threshold": float(seed_threshold),
        "support_voxels": int(support.sum()),
        "seed_voxels": int(seed.sum()),
        "seed_components": int(seed_n),
        "pred_fragment_count": int(len(pred_ids)),
        "watershed_applied": True,
        "watershed_energy": "negative_internal_distance_field",
    }
    return decoded, trace


def _write_task1_prediction_mha(decoded_case: np.ndarray,
                                ref_img: sitk.Image,
                                out_path: Path) -> None:
    """Write a decoded uint16 instance mask with the source label geometry."""
    # [QC][Invariant:geometry]
    # 시각화와 Task1 proxy가 같은 source-space volume을 보도록 oracle prediction은
    # canonicalized label image의 geometry를 그대로 복사한다.
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_img = sitk.GetImageFromArray(decoded_case.astype(np.uint16, copy=False))
    out_img.CopyInformation(ref_img)
    sitk.WriteImage(out_img, str(out_path))


def run_task1_v252_oracle_eval(cases: list[str],
                               out_path: Path,
                               *,
                               roi_pad_vox: int = 24,
                               affinity_threshold: float = 0.5,
                               seed_radius_mm: float = 2.5,
                               max_match_fragments: int = 300) -> dict[str, Any]:
    """Run V252 affinity13 oracle target -> decoder -> Task1 proxy gate."""
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        # [QC][Invariant:task1_anatomy_id_range]
        # Task1 proxy metric과 visualize.py는 instance ID 범위(1..50/51..100/101..150)로
        # Sacrum/LeftHip/RightHip anatomy를 구분한다. ROI별 decoder가 1부터 시작하는
        # local ID를 내더라도 case volume에 붙일 때는 anatomy별 공식 범위를 보존해야
        # fracture proxy, topology audit, 시각화가 같은 의미를 공유한다.
        next_pred_id_by_anatomy = {
            str(name): int(lo)
            for name, (lo, _hi) in V5_ANATOMY_RANGES.items()
        }
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            target, target_audit = compute_task1_v252_oracle_target(
                inst_roi,
                spacing_zyx,
                seed_radius_mm=seed_radius_mm,
            )
            decoded_roi, trace = decode_task1_v252_affinity13(
                target,
                affinity_threshold=affinity_threshold,
            )
            pred_ids = sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0)
            next_pred_id = int(next_pred_id_by_anatomy[str(anatomy)])
            if pred_ids and int(next_pred_id) + int(len(pred_ids)) - 1 > int(hi):
                # [QC][FailFast:anatomy_instance_id_overflow]
                # Task1 anatomy range를 넘겨 붙이면 ID가 uint16 범위 안에 있어도
                # Sacrum/LeftHip/RightHip 의미가 섞인다. 이 경우 ROI를 빈 실패 예측으로
                # 기록하고 trace에 overflow 원인을 남긴다.
                overflow_count = int(len(pred_ids))
                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                trace = dict(trace)
                trace.update({
                    "decoder_skipped": True,
                    "decoder_skipped_reason": "case_pred_fragment_id_exceeds_anatomy_range",
                    "anatomy": str(anatomy),
                    "anatomy_id_range": [int(lo), int(hi)],
                    "case_next_pred_id_before_roi": int(next_pred_id),
                    "roi_pred_fragment_count_before_skip": int(overflow_count),
                    "pred_fragment_count": 0,
                })
                pred_ids = []
            view = decoded_case[bbox]
            assigned_ids = []
            for pred_id in pred_ids:
                view[decoded_roi == int(pred_id)] = np.uint16(next_pred_id)
                assigned_ids.append(int(next_pred_id))
                next_pred_id += 1
            next_pred_id_by_anatomy[str(anatomy)] = int(next_pred_id)
            if pred_ids:
                trace = dict(trace)
                trace.update({
                    "assigned_case_instance_id_range": [int(assigned_ids[0]), int(assigned_ids[-1])],
                    "assigned_anatomy_id_range": [int(lo), int(hi)],
                })
            decoded_case[bbox] = view
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": f"PENGWIN_{case}_{anatomy}",
                "anatomy": anatomy,
                "target_audit": target_audit,
                "decoder_trace": trace,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(sum(
            int(next_pred_id_by_anatomy[str(name)]) - int(lo)
            for name, (lo, _hi) in V5_ANATOMY_RANGES.items()
        ))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": total_pred_fragments,
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    acceptance = {
        "v252_oracle_iouf_mean_ge_0_99": bool(iouf and float(np.mean(iouf)) >= 0.99),
        "v252_oracle_iouf_min_ge_0_99": bool(iouf and float(np.min(iouf)) >= 0.99),
        "dice_ge_0_999": bool((proxy_summary["dice_mean"] or 0.0) >= 0.999),
        "fracture_dice_ge_0_999": bool((proxy_summary["fracture_dice_proxy_mean"] or 0.0) >= 0.999),
        "local_dice_ge_0_999": bool((proxy_summary["local_dice_cfs_20mm_proxy_mean"] or 0.0) >= 0.999),
        "hd95_eq_0": bool((proxy_summary["hd95_mm_mean"] or 0.0) <= 1e-6),
        "assd_eq_0": bool((proxy_summary["assd_mm_mean"] or 0.0) <= 1e-6),
        "instance_f1_ge_0_999": bool((proxy_summary["instance_f1_mean"] or 0.0) >= 0.999),
        "instance_recall_ge_0_999": bool((proxy_summary["instance_recall_mean"] or 0.0) >= 0.999),
        "instance_precision_ge_0_999": bool((proxy_summary["instance_precision_mean"] or 0.0) >= 0.999),
        "merge_error_rate_eq_0": bool((proxy_summary["merge_error_rate_mean"] or 0.0) <= 1e-6),
        "split_error_rate_eq_0": bool((proxy_summary["split_error_rate_mean"] or 0.0) <= 1e-6),
        "topology_consistency_ge_0_999": bool((proxy_summary["topology_consistency_mean"] or 0.0) >= 0.999),
    }
    acceptance["v252_oracle_gate_pass"] = bool(all(acceptance.values()))
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v252_oracle_affinity13_eval",
        "target_contract": "task1_v252_oracle_target_affinity13_v1",
        "decoder": "task1_v252_affinity13_cc",
        "roi_pad_vox": int(roi_pad_vox),
        "affinity_threshold": float(affinity_threshold),
        "seed_radius_mm": float(seed_radius_mm),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def run_task1_v253_oracle_eval(cases: list[str],
                               out_path: Path,
                               *,
                               roi_pad_vox: int = 24,
                               affinity_threshold: float = 0.5,
                               seed_radius_mm: float = 2.5,
                               max_match_fragments: int = 300) -> dict[str, Any]:
    """Run V253 affinity13 + nearest-seed healing oracle gate."""
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        next_pred_id = 1
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            target, target_audit = compute_task1_v252_oracle_target(
                inst_roi,
                spacing_zyx,
                seed_radius_mm=seed_radius_mm,
            )
            decoded_roi, trace = decode_task1_v253_affinity13_seed_healed(
                target,
                spacing_zyx,
                affinity_threshold=affinity_threshold,
            )
            view = decoded_case[bbox]
            for pred_id in sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0):
                view[decoded_roi == int(pred_id)] = np.uint16(next_pred_id)
                next_pred_id += 1
            decoded_case[bbox] = view
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": f"PENGWIN_{case}_{anatomy}",
                "anatomy": anatomy,
                "target_audit": target_audit,
                "decoder_trace": trace,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(next_pred_id - 1)
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": total_pred_fragments,
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    acceptance = {
        "v253_oracle_iouf_mean_ge_0_99": bool(iouf and float(np.mean(iouf)) >= 0.99),
        "v253_oracle_iouf_min_ge_0_99": bool(iouf and float(np.min(iouf)) >= 0.99),
        "dice_ge_0_999": bool((proxy_summary["dice_mean"] or 0.0) >= 0.999),
        "fracture_dice_ge_0_999": bool((proxy_summary["fracture_dice_proxy_mean"] or 0.0) >= 0.999),
        "local_dice_ge_0_999": bool((proxy_summary["local_dice_cfs_20mm_proxy_mean"] or 0.0) >= 0.999),
        "hd95_eq_0": bool((proxy_summary["hd95_mm_mean"] or 0.0) <= 1e-6),
        "assd_eq_0": bool((proxy_summary["assd_mm_mean"] or 0.0) <= 1e-6),
        "instance_f1_ge_0_999": bool((proxy_summary["instance_f1_mean"] or 0.0) >= 0.999),
        "instance_recall_ge_0_999": bool((proxy_summary["instance_recall_mean"] or 0.0) >= 0.999),
        "instance_precision_ge_0_999": bool((proxy_summary["instance_precision_mean"] or 0.0) >= 0.999),
        "merge_error_rate_eq_0": bool((proxy_summary["merge_error_rate_mean"] or 0.0) <= 1e-6),
        "split_error_rate_eq_0": bool((proxy_summary["split_error_rate_mean"] or 0.0) <= 1e-6),
        "topology_consistency_ge_0_999": bool((proxy_summary["topology_consistency_mean"] or 0.0) >= 0.999),
    }
    acceptance["v253_oracle_gate_pass"] = bool(all(acceptance.values()))
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v253_oracle_affinity13_seed_healed_eval",
        "target_contract": "task1_v252_oracle_target_affinity13_v1",
        "decoder": "task1_v253_affinity13_seed_healed",
        "roi_pad_vox": int(roi_pad_vox),
        "affinity_threshold": float(affinity_threshold),
        "seed_radius_mm": float(seed_radius_mm),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def run_task1_v255_oracle_eval(cases: list[str],
                               out_path: Path,
                               *,
                               roi_pad_vox: int = 24,
                               affinity_threshold: float = 0.5,
                               mutex_threshold: float = 0.5,
                               seed_radius_mm: float = 2.5,
                               max_match_fragments: int = 300) -> dict[str, Any]:
    """Run V255 mutex13 + nearest-seed healing oracle gate."""
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        next_pred_id = 1
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            target, target_audit = compute_task1_v255_oracle_target(
                inst_roi,
                spacing_zyx,
                seed_radius_mm=seed_radius_mm,
            )
            decoded_roi, trace = decode_task1_v255_mutex13_seed_healed(
                target,
                spacing_zyx,
                affinity_threshold=affinity_threshold,
                mutex_threshold=mutex_threshold,
            )
            view = decoded_case[bbox]
            for pred_id in sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0):
                view[decoded_roi == int(pred_id)] = np.uint16(next_pred_id)
                next_pred_id += 1
            decoded_case[bbox] = view
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": f"PENGWIN_{case}_{anatomy}",
                "anatomy": anatomy,
                "target_audit": target_audit,
                "decoder_trace": trace,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(next_pred_id - 1)
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": total_pred_fragments,
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    acceptance = {
        "v255_oracle_iouf_mean_ge_0_99": bool(iouf and float(np.mean(iouf)) >= 0.99),
        "v255_oracle_iouf_min_ge_0_99": bool(iouf and float(np.min(iouf)) >= 0.99),
        "dice_ge_0_999": bool((proxy_summary["dice_mean"] or 0.0) >= 0.999),
        "fracture_dice_ge_0_999": bool((proxy_summary["fracture_dice_proxy_mean"] or 0.0) >= 0.999),
        "local_dice_ge_0_999": bool((proxy_summary["local_dice_cfs_20mm_proxy_mean"] or 0.0) >= 0.999),
        "hd95_eq_0": bool((proxy_summary["hd95_mm_mean"] or 0.0) <= 1e-6),
        "assd_eq_0": bool((proxy_summary["assd_mm_mean"] or 0.0) <= 1e-6),
        "instance_f1_ge_0_999": bool((proxy_summary["instance_f1_mean"] or 0.0) >= 0.999),
        "instance_recall_ge_0_999": bool((proxy_summary["instance_recall_mean"] or 0.0) >= 0.999),
        "instance_precision_ge_0_999": bool((proxy_summary["instance_precision_mean"] or 0.0) >= 0.999),
        "merge_error_rate_eq_0": bool((proxy_summary["merge_error_rate_mean"] or 0.0) <= 1e-6),
        "split_error_rate_eq_0": bool((proxy_summary["split_error_rate_mean"] or 0.0) <= 1e-6),
        "topology_consistency_ge_0_999": bool((proxy_summary["topology_consistency_mean"] or 0.0) >= 0.999),
    }
    acceptance["v255_oracle_gate_pass"] = bool(all(acceptance.values()))
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v255_oracle_mutex13_seed_healed_eval",
        "target_contract": "task1_v255_oracle_target_mutex13_seed_healed_v1",
        "decoder": "task1_v255_mutex13_seed_healed",
        "roi_pad_vox": int(roi_pad_vox),
        "affinity_threshold": float(affinity_threshold),
        "mutex_threshold": float(mutex_threshold),
        "seed_radius_mm": float(seed_radius_mm),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def run_task1_v273_oracle_eval(cases: list[str],
                               out_path: Path,
                               *,
                               roi_pad_vox: int = 24,
                               support_threshold: float = 0.5,
                               seed_threshold: float = 0.5,
                               join_threshold: float = 0.5,
                               cut_threshold: float = 0.5,
                               seed_radius_mm: float = 2.5,
                               max_match_fragments: int = 300,
                               pred_out_dir: Path | None = None) -> dict[str, Any]:
    """Run V273 no-contact pairwise join/cut oracle -> Task1 proxy gate.

    [AUDIT][Risk:Blocker][Scope:fulltrain_gate]
    Fulltrain is forbidden unless the GT-derived oracle first passes the user's
    Task1 metrics. V273 keeps only boundary-exact local graph supervision and
    removes contact/fracture scalar heads from the active contract.
    """
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        next_pred_id_by_anatomy = {str(name): int(lo) for name, (lo, _hi) in V5_ANATOMY_RANGES.items()}
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            target, target_audit = compute_task1_v273_no_contact_pairwise_oracle_target(
                inst_roi,
                spacing_zyx,
                seed_radius_mm=seed_radius_mm,
            )
            decoded_roi, trace = decode_task1_v273_no_contact_pairwise_seed_healed(
                target,
                spacing_zyx,
                support_threshold=support_threshold,
                seed_threshold=seed_threshold,
                join_threshold=join_threshold,
                cut_threshold=cut_threshold,
            )
            view = decoded_case[bbox]
            local_to_case: dict[int, int] = {}
            for pred_id in sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0):
                next_id = int(next_pred_id_by_anatomy[str(anatomy)])
                if next_id > int(hi):
                    raise ValueError(
                        f"V273 anatomy ID range overflow for {case} {anatomy}: "
                        f"next_id={next_id}, range=({lo}, {hi})"
                    )
                local_to_case[int(pred_id)] = int(next_id)
                view[decoded_roi == int(pred_id)] = np.uint16(next_id)
                next_pred_id_by_anatomy[str(anatomy)] = int(next_id) + 1
            decoded_case[bbox] = view
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": f"PENGWIN_{case}_{anatomy}",
                "anatomy": anatomy,
                "target_audit": target_audit,
                "decoder_trace": trace,
                "local_to_case_id": local_to_case,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(len([v for v in np.unique(decoded_case) if int(v) > 0]))
        prediction_path = None
        if pred_out_dir is not None:
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_v273_no_contact_pairwise_oracle.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": int(total_pred_fragments),
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    acceptance = {
        "dice_ge_0_90": bool((proxy_summary["dice_mean"] or 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool((proxy_summary["fracture_dice_proxy_mean"] or 0.0) >= 0.90),
        "local_dice_ge_0_90": bool((proxy_summary["local_dice_cfs_20mm_proxy_mean"] or 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool((proxy_summary["instance_f1_mean"] or 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool((proxy_summary["instance_recall_mean"] or 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool((proxy_summary["instance_precision_mean"] or 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(
            proxy_summary["merge_error_rate_mean"] is not None
            and float(proxy_summary["merge_error_rate_mean"]) <= 0.10
        ),
        "split_error_rate_le_0_10": bool(
            proxy_summary["split_error_rate_mean"] is not None
            and float(proxy_summary["split_error_rate_mean"]) <= 0.10
        ),
        "topology_consistency_ge_0_90": bool((proxy_summary["topology_consistency_mean"] or 0.0) >= 0.90),
    }
    acceptance["v273_oracle_gate_pass"] = bool(all(acceptance.values()))
    acceptance["v273_fulltrain_gate_pass"] = False
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v273_oracle_no_contact_pairwise_eval",
        "target_contract": "task1_v273_no_contact_pairwise_join_cut_oracle_target_v1",
        "decoder": "task1_v273_no_contact_pairwise_seed_healed",
        "roi_pad_vox": int(roi_pad_vox),
        "support_threshold": float(support_threshold),
        "seed_threshold": float(seed_threshold),
        "join_threshold": float(join_threshold),
        "cut_threshold": float(cut_threshold),
        "seed_radius_mm": float(seed_radius_mm),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def run_task1_v275_oracle_eval(cases: list[str],
                               out_path: Path,
                               *,
                               roi_pad_vox: int = 24,
                               max_match_fragments: int = 300,
                               pred_out_dir: Path | None = None) -> dict[str, Any]:
    """Run V275 contact-free fragment-position oracle -> Task1 proxy gate.

    [QA][Status:Required][Scope:v275_oracle_gate]
    GT-derived local position class가 Task1 proxy를 재현하지 못하면 learned model을
    훈련할 이유가 없다. 이 oracle은 fulltrain 전 필수 gate다.
    """
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            target, target_audit = task1_v275_local_fragment_position_target(inst_roi)
            decoded_roi, trace = decode_task1_v275_fragment_position(target)
            view = decoded_case[bbox]
            local_to_case: dict[int, int] = {}
            for local_id in sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0):
                case_id = int(lo) + int(local_id) - 1
                if case_id > int(hi):
                    raise ValueError(
                        f"V275 anatomy ID range overflow for {case} {anatomy}: "
                        f"local_id={local_id}, case_id={case_id}, range=({lo}, {hi})"
                    )
                local_to_case[int(local_id)] = int(case_id)
                view[decoded_roi == int(local_id)] = np.uint16(case_id)
            decoded_case[bbox] = view
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": f"PENGWIN_{case}_{anatomy}",
                "anatomy": anatomy,
                "target_audit": target_audit,
                "decoder_trace": trace,
                "local_to_case_id": local_to_case,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(len([v for v in np.unique(decoded_case) if int(v) > 0]))
        prediction_path = None
        if pred_out_dir is not None:
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_v275_fragment_position_oracle.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": int(total_pred_fragments),
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    def _proxy_value(key: str, fallback: float) -> float:
        value = proxy_summary.get(key)
        return float(fallback) if value is None else float(value)
    acceptance = {
        "dice_ge_0_90": bool(_proxy_value("dice_mean", 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool(_proxy_value("fracture_dice_proxy_mean", 0.0) >= 0.90),
        "local_dice_ge_0_90": bool(_proxy_value("local_dice_cfs_20mm_proxy_mean", 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool(_proxy_value("instance_f1_mean", 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool(_proxy_value("instance_recall_mean", 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool(_proxy_value("instance_precision_mean", 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(_proxy_value("merge_error_rate_mean", 1.0) <= 0.10),
        "split_error_rate_le_0_10": bool(_proxy_value("split_error_rate_mean", 1.0) <= 0.10),
        "topology_consistency_ge_0_90": bool(_proxy_value("topology_consistency_mean", 0.0) >= 0.90),
    }
    acceptance["v275_oracle_gate_pass"] = bool(all(acceptance.values()))
    acceptance["v275_fulltrain_gate_pass"] = False
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v275_oracle_no_contact_fragment_position_eval",
        "target_contract": "task1_v275_local_fragment_position_target_v1",
        "decoder": "task1_v275_fragment_position_argmax",
        "roi_pad_vox": int(roi_pad_vox),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def run_task1_v277_oracle_eval(cases: list[str],
                               out_path: Path,
                               *,
                               roi_pad_vox: int = 24,
                               support_threshold: float = 0.50,
                               separator_threshold: float = 0.50,
                               min_component_voxels: int = 100,
                               max_match_fragments: int = 300,
                               pred_out_dir: Path | None = None) -> dict[str, Any]:
    """Run V277 no-contact separator-gap oracle -> Task1 proxy gate.

    [QA][Status:Required][Scope:v277_oracle_gate]
    learned training 전에 2채널 support/separator target과 CC decoder가 hard cases의
    Task1 proxy를 재현할 수 있는지 확인한다. 이 gate가 실패하면 fulltrain은 금지다.
    """
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            target, target_audit = task1_v277_separator_gap_target(inst_roi)
            decoded_roi, trace = decode_task1_v277_separator_gap(
                target,
                support_threshold=support_threshold,
                separator_threshold=separator_threshold,
                min_component_voxels=min_component_voxels,
            )
            view = decoded_case[bbox]
            local_to_case: dict[int, int] = {}
            overflow_count = 0
            for local_id in sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0):
                case_id = int(lo) + int(local_id) - 1
                if case_id > int(hi):
                    overflow_count += 1
                    continue
                local_to_case[int(local_id)] = int(case_id)
                view[decoded_roi == int(local_id)] = np.uint16(case_id)
            decoded_case[bbox] = view
            if overflow_count:
                trace["anatomy_id_range_overflow_count"] = int(overflow_count)
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": f"PENGWIN_{case}_{anatomy}",
                "anatomy": anatomy,
                "target_audit": target_audit,
                "decoder_trace": trace,
                "local_to_case_id": local_to_case,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(len([v for v in np.unique(decoded_case) if int(v) > 0]))
        prediction_path = None
        if pred_out_dir is not None:
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_v277_separator_gap_oracle.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": int(total_pred_fragments),
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    def _proxy_value(key: str, fallback: float) -> float:
        value = proxy_summary.get(key)
        return float(fallback) if value is None else float(value)
    acceptance = {
        "dice_ge_0_90": bool(_proxy_value("dice_mean", 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool(_proxy_value("fracture_dice_proxy_mean", 0.0) >= 0.90),
        "local_dice_ge_0_90": bool(_proxy_value("local_dice_cfs_20mm_proxy_mean", 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool(_proxy_value("instance_f1_mean", 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool(_proxy_value("instance_recall_mean", 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool(_proxy_value("instance_precision_mean", 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(_proxy_value("merge_error_rate_mean", 1.0) <= 0.10),
        "split_error_rate_le_0_10": bool(_proxy_value("split_error_rate_mean", 1.0) <= 0.10),
        "topology_consistency_ge_0_90": bool(_proxy_value("topology_consistency_mean", 0.0) >= 0.90),
    }
    acceptance["v277_oracle_gate_pass"] = bool(all(acceptance.values()))
    acceptance["v277_fulltrain_gate_pass"] = False
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v277_oracle_no_contact_separator_gap_eval",
        "target_contract": "task1_v277_no_contact_separator_gap_target_v1",
        "decoder": "task1_v277_no_contact_separator_gap_cc",
        "roi_pad_vox": int(roi_pad_vox),
        "support_threshold": float(support_threshold),
        "separator_threshold": float(separator_threshold),
        "min_component_voxels": int(min_component_voxels),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


