def _task1_v283_global_coord_channels(shape: tuple[int, int, int]) -> np.ndarray:
    """Return full-ROI normalized z/y/x channels for V283 inference."""
    # [QC][Invariant:global_coord_space]
    # V283 trainer는 dataloader에서 전체 preprocessed ROI 기준 좌표를 붙인다. Prediction도
    # 같은 shape 정규화를 써야 sliding-window tile마다 좌표계가 달라지는 V282 실패를
    # 반복하지 않는다.
    depth, height, width = (int(v) for v in shape)
    denom = np.maximum(np.asarray([depth, height, width], dtype=np.float32) - 1.0, 1.0)
    z = (np.arange(depth, dtype=np.float32) / float(denom[0]))[:, None, None]
    y = (np.arange(height, dtype=np.float32) / float(denom[1]))[None, :, None]
    x = (np.arange(width, dtype=np.float32) / float(denom[2]))[None, None, :]
    return np.stack(
        [
            np.broadcast_to(z, (depth, height, width)),
            np.broadcast_to(y, (depth, height, width)),
            np.broadcast_to(x, (depth, height, width)),
        ],
        axis=0,
    ).astype(np.float32, copy=False)


def run_task1_v283_predict(cases: list[str],
                           out_root: Path,
                           checkpoint: str = "checkpoint_best.pth",
                           fold: int = 1,
                           trainer: str = "PengwinTrainerBoundaryFragmentSidecarCoreRecallDenseCandidateCore025StrongPeakNoContactGlobalCoordFreeEmbeddingV283",
                           plans: str = "nnUNetResEncUNetLPlans",
                           config: str = "3d_fullres",
                           preprocessed_plans_dir: str = "nnUNetPlans_3d_fullres") -> dict[str, Any]:
    """Export V283 support + free embedding logits with full-ROI coordinate input."""
    import torch
    from nnunetv2.inference.predict_from_raw_data import nnUNetPredictor

    model_dir = _nnunet_results_root() / DATASETS[537]["name"] / f"{trainer}__{plans}__{config}"
    if not model_dir.is_dir():
        raise FileNotFoundError(f"trained V283 model folder missing: {model_dir}")
    if "NoContactGlobalCoordFreeEmbeddingV283" not in str(trainer):
        raise ValueError(f"task1-v283-predict requires V283 trainer, got {trainer}")
    predictor = nnUNetPredictor(
        tile_step_size=0.5,
        use_gaussian=True,
        use_mirroring=False,
        perform_everything_on_device=True,
        device=torch.device("cuda" if torch.cuda.is_available() else "cpu"),
        verbose=False,
        verbose_preprocessing=False,
        allow_tqdm=True,
    )
    predictor.initialize_from_trained_model_folder(
        str(model_dir),
        use_folds=(int(fold),),
        checkpoint_name=checkpoint,
    )
    config_dir = NN_PREP / DATASETS[537]["name"] / preprocessed_plans_dir
    rows = []
    out_root.mkdir(parents=True, exist_ok=True)
    for cid_raw in cases:
        cid = str(cid_raw).zfill(3)
        for anatomy in V5_ANATOMY_RANGES:
            sample = f"PENGWIN_{cid}_{anatomy}"
            data = _load_preprocessed_sample(config_dir, sample)
            # [DATA][Risk:High][Scope:v283_prediction_input_contract]
            # V283은 contact/query/seed를 prediction input으로 받지 않는다. 학습과 같은
            # full-ROI global z/y/x 세 채널만 원본 preprocessed ROI 뒤에 붙인다.
            coords = _task1_v283_global_coord_channels(tuple(int(v) for v in data.shape[1:]))
            data_with_coords = np.concatenate([np.asarray(data, dtype=np.float32), coords], axis=0)
            logits = _predict_custom_logits_from_preprocessed_data(
                predictor,
                torch.from_numpy(np.asarray(data_with_coords).copy()).float(),
                output_channels=int(BFV3_GLOBAL_COORD_FREE_EMBEDDING_V283_OUTPUT_CHANNELS),
            )
            logits_np = logits.detach().cpu().numpy() if torch.is_tensor(logits) else np.asarray(logits)
            out_path = out_root / f"{sample}.npz"
            np.savez_compressed(out_path, logits=logits_np.astype(np.float16))
            rows.append({
                "case": cid,
                "sample": sample,
                "anatomy": anatomy,
                "output": str(out_path),
                "shape": [int(v) for v in logits_np.shape],
                "dtype": "float16",
                "input_contract": "preprocessed_roi_plus_full_roi_normalized_zyx",
            })
    report = {
        "task": "task1_v283_predict_global_coord_free_embedding_logits",
        "dataset": DATASETS[537]["name"],
        "trainer": trainer,
        "output_channels": int(BFV3_GLOBAL_COORD_FREE_EMBEDDING_V283_OUTPUT_CHANNELS),
        "target_contract": "task1_v283_learned_logits_no_contact_global_coord_free_embedding_v1",
        "decoder_scope": "oracle_gt_fragment_prototype_diagnostic",
        "model_dir": str(model_dir),
        "checkpoint": checkpoint,
        "fold": int(fold),
        "out_root": str(out_root),
        "samples": rows,
    }
    (out_root / "predict_summary.json").write_text(json.dumps(_json_sanitize(report), indent=2))
    return report


def _task1_v280_seed_component(mask: np.ndarray, seed_zyx: np.ndarray) -> np.ndarray:
    mask = np.asarray(mask, dtype=bool)
    if not bool(mask.any()):
        return mask
    labels, n_labels = ndi.label(mask)
    if int(n_labels) <= 1:
        return mask
    seed = np.asarray(np.round(seed_zyx), dtype=np.int64)
    seed = np.clip(seed, [0, 0, 0], np.asarray(mask.shape, dtype=np.int64) - 1)
    seed_label = int(labels[tuple(int(v) for v in seed)])
    if seed_label > 0:
        return labels == seed_label
    counts = np.bincount(labels.ravel())
    counts[0] = 0
    return labels == int(np.argmax(counts))


def run_task1_v280_prediction_eval(cases: list[str],
                                   out_path: Path,
                                   *,
                                   output_root: Path,
                                   roi_pad_vox: int = 24,
                                   mask_threshold: float = 0.5,
                                   decoder_support_ratio_cap: float = 6.0,
                                   max_match_fragments: int = 300,
                                   pred_out_dir: Path | None = None) -> dict[str, Any]:
    """Decode V280 oracle-query learned masks and compute Task1 proxy metrics."""
    if output_root is None:
        raise ValueError("V280 learned eval requires --output-root")
    predict_summary_path = output_root / "predict_summary.json"
    if not predict_summary_path.exists():
        raise FileNotFoundError(f"V280 predict summary missing: {predict_summary_path}")
    predict_summary = json.loads(predict_summary_path.read_text())
    trainer_name = str(predict_summary.get("trainer", ""))
    is_v280 = "NoContactQueryMaskV280" in trainer_name
    is_v281 = "NoContactQueryMaskPositiveNegativeV281" in trainer_name
    is_v285 = "NoContactGlobalCoordQueryMaskV285" in trainer_name
    is_v286 = "NoContactGlobalCoordQueryMaskPositiveNegativeV286" in trainer_name
    if not (is_v280 or is_v281 or is_v285 or is_v286):
        raise ValueError(f"V280/V281/V285/V286 eval requires query-mask trainer summary, got {predict_summary.get('trainer')!r}")
    variant = "v286" if is_v286 else ("v285" if is_v285 else ("v281" if is_v281 else "v280"))
    decoder_name = (
        "task1_v286_oracle_global_coord_positive_negative_query_mask_argmax"
        if is_v286 else (
            "task1_v285_oracle_global_coord_query_mask_argmax"
            if is_v285 else (
            "task1_v281_oracle_positive_negative_query_mask_argmax"
            if is_v281 else "task1_v280_oracle_query_mask_argmax"
            )
        )
    )
    rows_by_sample: dict[str, list[dict[str, Any]]] = {}
    for row in predict_summary.get("samples", []):
        rows_by_sample.setdefault(str(row["sample"]), []).append(row)

    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        anatomy_traces = []
        next_pred_id_by_anatomy = {str(name): int(lo) for name, (lo, _hi) in V5_ANATOMY_RANGES.items()}
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            sample = f"PENGWIN_{case}_{anatomy}"
            query_rows = rows_by_sample.get(sample, [])
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None or not query_rows:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            gt_support_voxels = int((inst_roi > 0).sum())
            max_prob = np.zeros(inst_roi.shape, dtype=np.float32)
            decoded_roi = np.zeros(inst_roi.shape, dtype=np.uint16)
            query_traces = []
            for idx, qrow in enumerate(sorted(query_rows, key=lambda r: int(r["fragment_id"]))):
                frag_id = int(qrow["fragment_id"])
                logits = _load_bicm_v6_logits(Path(qrow["output"]))
                if logits.ndim != 4 or int(logits.shape[0]) != int(BFV3_QUERY_MASK_V280_OUTPUT_CHANNELS):
                    raise RuntimeError(f"expected V280 logits [1,Z,Y,X], got {logits.shape} in {qrow['output']}")
                prob_pre = expit(logits[0].astype(np.float32, copy=False))
                prob = _resize_channel_first_probabilities(prob_pre[None], tuple(inst_roi.shape))[0]
                pred_mask = prob >= float(mask_threshold)
                gt_mask = inst_roi == int(frag_id)
                if bool(gt_mask.any()):
                    seed_zyx = np.argwhere(gt_mask).astype(np.float32).mean(axis=0)
                    pred_mask = _task1_v280_seed_component(pred_mask, seed_zyx)
                selected = pred_mask & (prob > max_prob)
                local_id = int(idx) + 1
                decoded_roi[selected] = np.uint16(local_id)
                max_prob[selected] = prob[selected]
                inter = int((pred_mask & gt_mask).sum())
                denom = int(pred_mask.sum()) + int(gt_mask.sum())
                query_traces.append({
                    "fragment_id": int(frag_id),
                    "local_pred_id": int(local_id),
                    "pred_voxels": int(pred_mask.sum()),
                    "gt_voxels": int(gt_mask.sum()),
                    "dice": float((2.0 * inter) / max(denom, 1)),
                    "max_probability": float(prob.max()) if prob.size else 0.0,
                })
            support_ratio = float(int((decoded_roi > 0).sum()) / max(1, gt_support_voxels))
            if support_ratio > float(decoder_support_ratio_cap):
                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
            view = decoded_case[bbox]
            local_to_case: dict[int, int] = {}
            for pred_id in sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0):
                next_id = int(next_pred_id_by_anatomy[str(anatomy)])
                if next_id > int(hi):
                    break
                local_to_case[int(pred_id)] = int(next_id)
                view[decoded_roi == int(pred_id)] = np.uint16(next_id)
                next_pred_id_by_anatomy[str(anatomy)] = int(next_id) + 1
            decoded_case[bbox] = view
            sample_metrics = None
            pred_fragment_count = int(len([v for v in np.unique(decoded_roi) if int(v) > 0]))
            if pred_fragment_count <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": sample,
                "anatomy": anatomy,
                "probability_summary": {
                    "n_queries": int(len(query_rows)),
                    "support_voxels": int((decoded_roi > 0).sum()),
                    "gt_support_voxels": int(gt_support_voxels),
                    "support_pred_gt_ratio": float(support_ratio),
                },
                "decoder_trace": {
                    "decoder": decoder_name,
                    "mask_threshold": float(mask_threshold),
                    "pred_fragment_count": int(pred_fragment_count),
                    "query_traces": query_traces,
                },
                "local_to_case_id": local_to_case,
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(len([v for v in np.unique(decoded_case) if int(v) > 0]))
        prediction_path = None
        if pred_out_dir is not None:
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_{variant}_query_mask_prediction.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": int(total_pred_fragments),
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    acceptance = {
        "dice_ge_0_90": bool((proxy_summary["dice_mean"] or 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool((proxy_summary["fracture_dice_proxy_mean"] or 0.0) >= 0.90),
        "local_dice_ge_0_90": bool((proxy_summary["local_dice_cfs_20mm_proxy_mean"] or 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool((proxy_summary["instance_f1_mean"] or 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool((proxy_summary["instance_recall_mean"] or 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool((proxy_summary["instance_precision_mean"] or 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(proxy_summary["merge_error_rate_mean"] is not None and float(proxy_summary["merge_error_rate_mean"]) <= 0.10),
        "split_error_rate_le_0_10": bool(proxy_summary["split_error_rate_mean"] is not None and float(proxy_summary["split_error_rate_mean"]) <= 0.10),
        "topology_consistency_ge_0_90": bool((proxy_summary["topology_consistency_mean"] or 0.0) >= 0.90),
    }
    gate_key = f"{variant}_learned_fulltrain_gate_pass"
    acceptance[gate_key] = bool(all(acceptance.values()))
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": f"task1_{variant}_prediction_oracle_query_mask_eval",
        "target_contract": str(predict_summary.get("target_contract", "task1_v280_learned_logits_no_contact_oracle_query_mask_v1")),
        "decoder": decoder_name,
        "query_source": str(predict_summary.get("query_source", "gt_fragment_center_oracle")),
        "output_root": str(output_root),
        "roi_pad_vox": int(roi_pad_vox),
        "mask_threshold": float(mask_threshold),
        "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def _task1_v282_assign_oracle_prototypes(embedding: np.ndarray,
                                         support_mask: np.ndarray,
                                         inst_roi: np.ndarray) -> tuple[np.ndarray, dict[str, Any]]:
    """Assign support voxels to nearest GT-fragment embedding prototype."""
    # [AUDIT][Risk:High][Scope:v282_oracle_prototype]
    # 이 decoder는 learned seed/prototype 문제가 아니라 embedding separability만 검증한다.
    # GT fragment ID로 prototype을 만들기 때문에 fulltrain 가능한 최종 decoder가 아니다.
    if embedding.ndim != 4:
        raise ValueError(f"V282 embedding must be [C,Z,Y,X], got {embedding.shape}")
    support = np.asarray(support_mask, dtype=bool)
    inst = np.asarray(inst_roi, dtype=np.uint16)
    ids = [int(v) for v in np.unique(inst) if 0 < int(v) <= 150]
    decoded = np.zeros(inst.shape, dtype=np.uint16)
    if not ids or not bool(support.any()):
        return decoded, {"prototype_count": 0, "assigned_voxels": 0}
    emb_zyxc = np.moveaxis(embedding.astype(np.float32, copy=False), 0, -1)
    prototypes = []
    valid_ids = []
    for frag_id in ids:
        mask = inst == int(frag_id)
        if not bool(mask.any()):
            continue
        prototypes.append(emb_zyxc[mask].mean(axis=0))
        valid_ids.append(int(frag_id))
    if not prototypes:
        return decoded, {"prototype_count": 0, "assigned_voxels": 0}
    proto = np.stack(prototypes, axis=0).astype(np.float32, copy=False)
    coords = np.argwhere(support)
    assigned_ids = np.zeros((coords.shape[0],), dtype=np.uint16)
    for start in range(0, int(coords.shape[0]), 200000):
        chunk = coords[start:start + 200000]
        points = emb_zyxc[tuple(chunk.T)].astype(np.float32, copy=False)
        dist2 = ((points[:, None, :] - proto[None, :, :]) ** 2).sum(axis=2)
        nearest = np.argmin(dist2, axis=1)
        assigned_ids[start:start + len(chunk)] = np.asarray(valid_ids, dtype=np.uint16)[nearest]
    decoded[tuple(coords.T)] = assigned_ids
    return decoded, {
        "prototype_count": int(len(valid_ids)),
        "assigned_voxels": int(coords.shape[0]),
        "prototype_ids": [int(v) for v in valid_ids],
    }


def run_task1_v282_prediction_eval(cases: list[str],
                                   out_path: Path,
                                   *,
                                   output_root: Path,
                                   roi_pad_vox: int = 24,
                                   support_threshold: float = 0.5,
                                   support_source: str = "predicted",
                                   decoder_support_ratio_cap: float = 6.0,
                                   max_match_fragments: int = 300,
                                   pred_out_dir: Path | None = None) -> dict[str, Any]:
    """Evaluate V282 free embedding with oracle GT-fragment prototypes."""
    support_source = str(support_source).strip().lower()
    if support_source not in {"predicted", "gt"}:
        raise ValueError(f"support_source must be 'predicted' or 'gt', got {support_source!r}")
    predict_summary_path = output_root / "predict_summary.json"
    if not predict_summary_path.exists():
        raise FileNotFoundError(f"V282 predict summary missing: {predict_summary_path}")
    predict_summary = json.loads(predict_summary_path.read_text())
    trainer_name = str(predict_summary.get("trainer", ""))
    is_v282 = "NoContactFreeEmbeddingV282" in trainer_name
    is_v283 = "NoContactGlobalCoordFreeEmbeddingV283" in trainer_name
    if not (is_v282 or is_v283):
        raise ValueError(f"V282/V283 eval requires free-embedding trainer summary, got {predict_summary.get('trainer')!r}")
    variant = "v283" if is_v283 else "v282"
    rows_by_sample = {str(row["sample"]): row for row in predict_summary.get("samples", [])}
    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            sample = f"PENGWIN_{case}_{anatomy}"
            row = rows_by_sample.get(sample)
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None or row is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            logits = _load_bicm_v6_logits(Path(row["output"]))
            expected_channels = (
                int(BFV3_GLOBAL_COORD_FREE_EMBEDDING_V283_OUTPUT_CHANNELS)
                if is_v283
                else int(BFV3_FREE_EMBEDDING_V282_OUTPUT_CHANNELS)
            )
            if logits.ndim != 4 or int(logits.shape[0]) != int(expected_channels):
                raise RuntimeError(f"expected {variant.upper()} logits [5,Z,Y,X], got {logits.shape} in {row['output']}")
            support_prob = _resize_channel_first_probabilities(expit(logits[0].astype(np.float32))[None], tuple(inst_roi.shape))[0]
            embedding = _resize_channel_first_probabilities(logits[1:5].astype(np.float32, copy=False), tuple(inst_roi.shape))
            gt_support = inst_roi > 0
            support_mask = gt_support if support_source == "gt" else support_prob >= float(support_threshold)
            support_ratio = float(int(support_mask.sum()) / max(1, int(gt_support.sum())))
            if support_source == "predicted" and support_ratio > float(decoder_support_ratio_cap):
                support_mask = np.zeros_like(gt_support, dtype=bool)
            decoded_roi, trace = _task1_v282_assign_oracle_prototypes(embedding, support_mask, inst_roi)
            view = decoded_case[bbox]
            view[decoded_roi > 0] = decoded_roi[decoded_roi > 0]
            decoded_case[bbox] = view
            sample_metrics = None
            pred_fragment_count = int(len([v for v in np.unique(decoded_roi) if int(v) > 0]))
            if pred_fragment_count <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": sample,
                "anatomy": anatomy,
                "support_source": support_source,
                "support_threshold": float(support_threshold),
                "probability_summary": {
                    "support_voxels": int(support_mask.sum()),
                    "gt_support_voxels": int(gt_support.sum()),
                    "support_pred_gt_ratio": float(support_ratio),
                    "support_probability_min": float(support_prob.min()) if support_prob.size else 0.0,
                    "support_probability_mean": float(support_prob.mean()) if support_prob.size else 0.0,
                    "support_probability_max": float(support_prob.max()) if support_prob.size else 0.0,
                },
                "decoder_trace": {
                    "decoder": "task1_v282_oracle_gt_fragment_prototype_embedding",
                    "pred_fragment_count": int(pred_fragment_count),
                    **trace,
                },
                "fragment_metrics": sample_metrics,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(len([v for v in np.unique(decoded_case) if int(v) > 0]))
        prediction_path = None
        if pred_out_dir is not None:
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_{variant}_free_embedding_{support_source}_support_prediction.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": int(total_pred_fragments),
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    acceptance = {
        "dice_ge_0_90": bool((proxy_summary["dice_mean"] or 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool((proxy_summary["fracture_dice_proxy_mean"] or 0.0) >= 0.90),
        "local_dice_ge_0_90": bool((proxy_summary["local_dice_cfs_20mm_proxy_mean"] or 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool((proxy_summary["instance_f1_mean"] or 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool((proxy_summary["instance_recall_mean"] or 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool((proxy_summary["instance_precision_mean"] or 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(proxy_summary["merge_error_rate_mean"] is not None and float(proxy_summary["merge_error_rate_mean"]) <= 0.10),
        "split_error_rate_le_0_10": bool(proxy_summary["split_error_rate_mean"] is not None and float(proxy_summary["split_error_rate_mean"]) <= 0.10),
        "topology_consistency_ge_0_90": bool((proxy_summary["topology_consistency_mean"] or 0.0) >= 0.90),
    }
    acceptance[f"{variant}_oracle_prototype_fulltrain_gate_pass"] = bool(all(acceptance.values()) and support_source == "predicted")
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": f"task1_{variant}_prediction_free_embedding_oracle_prototype_eval",
        "target_contract": str(predict_summary.get("target_contract", "task1_v282_learned_logits_no_contact_free_embedding_v1")),
        "decoder": "task1_v282_oracle_gt_fragment_prototype_embedding",
        "variant": variant,
        "support_source": support_source,
        "output_root": str(output_root),
        "roi_pad_vox": int(roi_pad_vox),
        "support_threshold": float(support_threshold),
        "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def run_task1_v253_prediction_eval(cases: list[str],
                                   out_path: Path,
                                   output_root: Path,
                                   *,
                                   roi_pad_vox: int = 24,
                                   support_threshold: float = 0.5,
                                   seed_threshold: float = 0.5,
                                   affinity_threshold: float = 0.5,
                                   decoder_support_ratio_cap: float = 6.0,
                                   decoder_joined_edge_cap: int = 8_000_000,
                                   max_match_fragments: int = 300,
                                   pred_out_dir: Path | None = None) -> dict[str, Any]:
    """Decode learned V253 logits and compute the Task1 official-aligned proxy.

    [METRIC][Risk:High][Scope:learned_v253_gate]
    This is the post-train gate for V253. It intentionally mirrors the oracle
    V253 decoder thresholds instead of tuning per checkpoint. The score can be
    poor for a smoke checkpoint; the required evidence here is that the learned
    prediction path is contract-correct and reproducible before full train.
    """
    if output_root is None:
        raise ValueError("V253 learned eval requires --output-root")
    if float(decoder_support_ratio_cap) <= 0.0:
        raise ValueError(f"decoder_support_ratio_cap must be > 0, got {decoder_support_ratio_cap}")
    if int(decoder_joined_edge_cap) < 0:
        raise ValueError(f"decoder_joined_edge_cap must be >= 0, got {decoder_joined_edge_cap}")
    predict_summary_path = output_root / "predict_summary.json"
    predict_summary = {}
    if predict_summary_path.exists():
        predict_summary = json.loads(predict_summary_path.read_text())
    summary_trainer = str(predict_summary.get("trainer", ""))
    use_v257_seed_union_decoder = "SeedStableSupportLeakGuardSeedHealedV257" in summary_trainer
    use_v260_seed_fracture_watershed_decoder = "FractureSeedCalibratedSupportLeakGuardSeedHealedV260" in summary_trainer
    use_v268_no_contact_pairwise_decoder = "NoContactPairwiseSoftmaxMutex13SeedHealedV268" in summary_trainer
    use_v266_pairwise_softmax_decoder = (
        "PairwiseSoftmaxMutex13SeedHealedV266" in summary_trainer
        or use_v268_no_contact_pairwise_decoder
    )
    use_v258_seed_peak_decoder = (
        "SeedPeakSupportLeakGuardSeedHealedV258" in summary_trainer
        or "SeedPeakBodySupportLeakGuardSeedHealedV259" in summary_trainer
    )
    case_rows = []
    sample_rows = []
    learned_contracts: set[str] = set()
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        # [QC][Invariant:task1_anatomy_id_range]
        # V253/V255/V266/V268 graph decoder는 ROI-local component ID를 낸다. case-level
        # MHA에 붙일 때는 Task1 anatomy ID range를 보존해야 visual audit와
        # fracture/topology proxy가 같은 label contract를 본다.
        next_pred_id_by_anatomy = {
            str(name): int(lo)
            for name, (lo, _hi) in V5_ANATOMY_RANGES.items()
        }
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            sample = f"PENGWIN_{case}_{anatomy}"
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            logits_path = output_root / f"{sample}.npz"
            raw_logits = _load_bicm_v6_logits(logits_path).astype(np.float32, copy=False)
            channel_count = int(raw_logits.shape[0])
            if channel_count == int(BFV3_AFFINITY13_SEED_OUTPUT_CHANNELS):
                raw_logits = _load_task1_v253_logits(logits_path)
                decoder_label = "task1_v253_affinity13_seed_healed"
                learned_contracts.add("task1_v253_learned_logits_affinity13_seed_healed_v1")
            elif channel_count == int(BFV3_MUTEX13_SEED_OUTPUT_CHANNELS):
                raw_logits = _load_task1_v255_logits(logits_path)
                if use_v268_no_contact_pairwise_decoder:
                    decoder_label = "task1_v268_no_contact_pairwise_softmax_mutex13_seed_healed"
                    learned_contracts.add("task1_v268_learned_logits_no_contact_pairwise_softmax_mutex13_seed_healed_v1")
                elif use_v266_pairwise_softmax_decoder:
                    decoder_label = "task1_v266_pairwise_softmax_mutex13_seed_healed"
                    learned_contracts.add("task1_v266_learned_logits_pairwise_softmax_mutex13_seed_healed_v1")
                elif use_v260_seed_fracture_watershed_decoder:
                    decoder_label = "task1_v260_seed_fracture_watershed"
                    learned_contracts.add("task1_v260_learned_logits_mutex13_seed_fracture_watershed_v1")
                elif use_v258_seed_peak_decoder:
                    decoder_label = "task1_v258_mutex13_seed_peak_healed"
                    learned_contracts.add("task1_v258_learned_logits_mutex13_seed_peak_healed_v1")
                elif use_v257_seed_union_decoder:
                    decoder_label = "task1_v257_mutex13_seed_union_healed"
                    learned_contracts.add("task1_v257_learned_logits_mutex13_seed_union_healed_v1")
                else:
                    decoder_label = "task1_v255_mutex13_seed_healed"
                    learned_contracts.add("task1_v255_learned_logits_mutex13_seed_healed_v1")
            else:
                raise RuntimeError(
                    f"Task1 learned eval expected 18 or 31 channels, got {raw_logits.shape} in {logits_path}"
                )
            gt_support_voxels = int((inst_roi > 0).sum())
            source_support_logit_threshold = _probability_threshold_to_logit(
                support_threshold,
                name="support_threshold",
            )
            source_support_channel = raw_logits[TASK1_V252_BASE_CHANNELS["support"]]
            source_support_prob = expit(source_support_channel).astype(np.float32, copy=False)
            source_support_pred = source_support_channel >= source_support_logit_threshold
            source_support_ratio = float(int(source_support_pred.sum()) / max(1, gt_support_voxels))
            probability_shape_before_restore = tuple(int(v) for v in raw_logits.shape)
            probability_summary = {
                "shape_before_restore": list(probability_shape_before_restore),
                "source_support_mean": float(np.mean(source_support_prob)),
                "source_support_voxels": int(source_support_pred.sum()),
                "gt_support_voxels": int(gt_support_voxels),
                "source_support_pred_gt_ratio": float(source_support_ratio),
            }
            if source_support_ratio > float(decoder_support_ratio_cap):
                # [QC][FailFast:learned_decoder_explosion]
                # Early or broken checkpoints can put support/affinity near 0.5
                # across most of the ROI. Check the source grid before resizing
                # all 18 channels, otherwise a known-bad smoke checkpoint can
                # spend minutes in interpolation/graph decode before failing.
                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                trace = {
                    "decoder": decoder_label,
                    "decoder_skipped": True,
                    "decoder_skipped_reason": "source_predicted_support_ratio_exceeds_cap",
                    "support_threshold": float(support_threshold),
                    "seed_threshold": float(seed_threshold),
                    "affinity_threshold": float(affinity_threshold),
                    "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
                    "support_voxels": int(source_support_pred.sum()),
                    "gt_support_voxels": int(gt_support_voxels),
                    "support_pred_gt_ratio": float(source_support_ratio),
                    "pred_fragment_count": 0,
                }
                probability_summary["shape_after_restore"] = None
                probability_summary["restore_skipped"] = True
            else:
                source_edge_counts = None
                if tuple(raw_logits.shape[1:]) == tuple(inst_roi.shape):
                    if channel_count == int(BFV3_MUTEX13_SEED_OUTPUT_CHANNELS):
                        if use_v266_pairwise_softmax_decoder:
                            source_edge_counts = _task1_v255_mutex13_edge_counts(
                                task1_v266_pairwise_softmax_fields_from_logits(raw_logits),
                                support_threshold=support_threshold,
                                affinity_threshold=affinity_threshold,
                            )
                        else:
                            source_edge_counts = _task1_v255_mutex13_edge_counts_from_logits(
                                raw_logits,
                                support_threshold=support_threshold,
                                affinity_threshold=affinity_threshold,
                            )
                    else:
                        source_edge_counts = _task1_v253_affinity13_edge_counts_from_logits(
                            raw_logits,
                            support_threshold=support_threshold,
                            affinity_threshold=affinity_threshold,
                        )
                    probability_summary["source_affinity_edge_counts"] = source_edge_counts
                if (
                    source_edge_counts is not None
                    and not use_v260_seed_fracture_watershed_decoder
                    and int(decoder_joined_edge_cap) > 0
                    and int(source_edge_counts["joined_affinity_edges"]) > int(decoder_joined_edge_cap)
                ):
                    # [QC][FailFast:learned_decoder_edge_explosion]
                    # 이미 ROI shape의 raw logits라면 sigmoid/float32 확장 전 logit threshold만으로
                    # decoder와 동일한 edge join 여부를 계산할 수 있다. 여기서 실패 처리하면
                    # 평가가 graph construction에 묶이지 않고 병목 원인이 JSON trace에 남는다.
                    decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                    trace = {
                        "decoder": decoder_label,
                        "decoder_skipped": True,
                        "decoder_skipped_reason": "source_predicted_joined_affinity_edges_exceeds_cap",
                        "support_threshold": float(support_threshold),
                        "seed_threshold": float(seed_threshold),
                        "affinity_threshold": float(affinity_threshold),
                        "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
                        "decoder_joined_edge_cap": int(decoder_joined_edge_cap),
                        "support_voxels": int(source_support_pred.sum()),
                        "gt_support_voxels": int(gt_support_voxels),
                        "support_pred_gt_ratio": float(source_support_ratio),
                        "valid_affinity_edges": int(source_edge_counts["valid_affinity_edges"]),
                        "joined_affinity_edges": int(source_edge_counts["joined_affinity_edges"]),
                        "pred_fragment_count": 0,
                    }
                    probability_summary["shape_after_restore"] = None
                    probability_summary["restore_skipped"] = True
                else:
                    probs = (
                        task1_v266_pairwise_softmax_fields_from_logits(raw_logits)
                        if use_v266_pairwise_softmax_decoder
                        else expit(raw_logits).astype(np.float32, copy=False)
                    )
                    if tuple(probs.shape[1:]) != tuple(inst_roi.shape):
                        probs = _resize_channel_first_probabilities(probs, tuple(inst_roi.shape))
                    support_pred = probs[TASK1_V252_BASE_CHANNELS["support"]] >= float(support_threshold)
                    support_ratio = float(int(support_pred.sum()) / max(1, gt_support_voxels))
                    edge_counts = None
                    if support_ratio > float(decoder_support_ratio_cap):
                        # [QC][FailFast:learned_decoder_explosion]
                        # Source-grid ratio can miss resize-induced overprediction.
                        # This second fixed check still reports a failed prediction
                        # instead of running an already-invalid dense graph decode.
                        decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                        trace = {
                            "decoder": decoder_label,
                            "decoder_skipped": True,
                            "decoder_skipped_reason": "restored_predicted_support_ratio_exceeds_cap",
                            "support_threshold": float(support_threshold),
                            "seed_threshold": float(seed_threshold),
                            "affinity_threshold": float(affinity_threshold),
                            "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
                            "support_voxels": int(support_pred.sum()),
                            "gt_support_voxels": int(gt_support_voxels),
                            "support_pred_gt_ratio": float(support_ratio),
                            "pred_fragment_count": 0,
                        }
                    else:
                        if channel_count == int(BFV3_MUTEX13_SEED_OUTPUT_CHANNELS):
                            edge_counts = _task1_v255_mutex13_edge_counts(
                                probs,
                                support_threshold=support_threshold,
                                affinity_threshold=affinity_threshold,
                            )
                        else:
                            edge_counts = _task1_v253_affinity13_edge_counts(
                                probs,
                                support_threshold=support_threshold,
                                affinity_threshold=affinity_threshold,
                            )
                        # [QC][FailFast:learned_decoder_edge_explosion]
                        # support ratio만으로는 graph density를 제한하지 못한다. V253 learned early checkpoint가
                        # support는 GT 대비 허용 범위에 있어도 13개 affinity 대부분을 join으로 예측하면
                        # sparse graph 생성/connected_components가 평가를 장시간 점유한다. 이 guard는 metric을
                        # 좋게 보정하지 않고 해당 ROI를 실패 예측(빈 mask)으로 기록해 병목을 추적 가능하게 만든다.
                        # [AUDIT][Risk:High][Scope:v260_decoder_contract]
                        # V260 watershed는 affinity graph를 만들지 않으므로 joined-edge cap으로
                        # 실패 처리하면 실제 Task1 fracture/seed decoder를 검증하지 못한다.
                        # V253/V255/V258 graph decoders에는 기존 fail-fast를 그대로 유지한다.
                        if (
                            not use_v260_seed_fracture_watershed_decoder
                            and int(decoder_joined_edge_cap) > 0
                            and int(edge_counts["joined_affinity_edges"]) > int(decoder_joined_edge_cap)
                        ):
                            decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                            trace = {
                                "decoder": decoder_label,
                                "decoder_skipped": True,
                                "decoder_skipped_reason": "restored_predicted_joined_affinity_edges_exceeds_cap",
                                "support_threshold": float(support_threshold),
                                "seed_threshold": float(seed_threshold),
                                "affinity_threshold": float(affinity_threshold),
                                "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
                                "decoder_joined_edge_cap": int(decoder_joined_edge_cap),
                                "support_voxels": int(support_pred.sum()),
                                "gt_support_voxels": int(gt_support_voxels),
                                "support_pred_gt_ratio": float(support_ratio),
                                "valid_affinity_edges": int(edge_counts["valid_affinity_edges"]),
                                "joined_affinity_edges": int(edge_counts["joined_affinity_edges"]),
                                "pred_fragment_count": 0,
                            }
                        else:
                            try:
                                if channel_count == int(BFV3_MUTEX13_SEED_OUTPUT_CHANNELS):
                                    if use_v266_pairwise_softmax_decoder:
                                        decoded_roi, trace = decode_task1_v266_pairwise_softmax_mutex13_seed_healed(
                                            probs,
                                            spacing_zyx,
                                            support_threshold=support_threshold,
                                            seed_threshold=seed_threshold,
                                            affinity_threshold=affinity_threshold,
                                        )
                                    elif use_v260_seed_fracture_watershed_decoder:
                                        decoded_roi, trace = decode_task1_v260_seed_fracture_watershed(
                                            probs,
                                            spacing_zyx,
                                            support_threshold=support_threshold,
                                            seed_threshold=seed_threshold,
                                        )
                                    elif use_v258_seed_peak_decoder:
                                        decoded_roi, trace = decode_task1_v258_mutex13_seed_peak_healed(
                                            probs,
                                            spacing_zyx,
                                            support_threshold=support_threshold,
                                            seed_threshold=seed_threshold,
                                            affinity_threshold=affinity_threshold,
                                        )
                                    elif use_v257_seed_union_decoder:
                                        decoded_roi, trace = decode_task1_v257_mutex13_seed_union_healed(
                                            probs,
                                            spacing_zyx,
                                            support_threshold=support_threshold,
                                            seed_threshold=seed_threshold,
                                            affinity_threshold=affinity_threshold,
                                        )
                                    else:
                                        decoded_roi, trace = decode_task1_v255_mutex13_seed_healed(
                                            probs,
                                            spacing_zyx,
                                            support_threshold=support_threshold,
                                            seed_threshold=seed_threshold,
                                            affinity_threshold=affinity_threshold,
                                        )
                                else:
                                    decoded_roi, trace = decode_task1_v253_affinity13_seed_healed(
                                        probs,
                                        spacing_zyx,
                                        support_threshold=support_threshold,
                                        seed_threshold=seed_threshold,
                                        affinity_threshold=affinity_threshold,
                                    )
                            except RuntimeError as exc:
                                if "too many graph components" not in str(exc):
                                    raise
                                # [QC][FailFast:learned_decoder_component_explosion]
                                # 아주 초기 checkpoint는 mutex/affinity가 대부분 끊겨 support voxel마다
                                # 별도 component를 만들 수 있다. 이는 Task1 Instance/Topology 실패이므로
                                # eval 전체를 중단하지 않고 빈 예측과 원인 trace로 남긴다.
                                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                                trace = {
                                    "decoder": decoder_label,
                                    "decoder_skipped": True,
                                    "decoder_skipped_reason": "decoder_component_count_exceeds_uint16",
                                    "decoder_error": str(exc),
                                    "support_threshold": float(support_threshold),
                                    "seed_threshold": float(seed_threshold),
                                    "affinity_threshold": float(affinity_threshold),
                                    "support_voxels": int(support_pred.sum()),
                                    "gt_support_voxels": int(gt_support_voxels),
                                    "support_pred_gt_ratio": float(support_ratio),
                                    "valid_affinity_edges": int(edge_counts["valid_affinity_edges"]),
                                    "joined_affinity_edges": int(edge_counts["joined_affinity_edges"]),
                                    "pred_fragment_count": 0,
                                }
                    probability_summary.update({
                        "shape_after_restore": list(probs.shape),
                        "restore_skipped": False,
                        "support_mean": float(np.mean(probs[TASK1_V252_BASE_CHANNELS["support"]])),
                        "fracture_surface_mean": float(np.mean(probs[TASK1_V252_BASE_CHANNELS["fracture_surface"]])),
                        "seed_center_mean": float(np.mean(probs[TASK1_V252_BASE_CHANNELS["seed_center"]])),
                        "seed_body_mean": float(np.mean(probs[TASK1_V252_BASE_CHANNELS["seed_body"]])),
                        "affinity_mean": float(np.mean(probs[5:18])),
                        "decoder_joined_edge_cap": int(decoder_joined_edge_cap),
                    })
                    if channel_count == int(BFV3_MUTEX13_SEED_OUTPUT_CHANNELS):
                        probability_summary["mutex_mean"] = float(np.mean(probs[18:31]))
                    if edge_counts is not None:
                        probability_summary["restored_affinity_edge_counts"] = edge_counts
            pred_ids = sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0)
            next_pred_id = int(next_pred_id_by_anatomy[str(anatomy)])
            if pred_ids and int(next_pred_id) + int(len(pred_ids)) - 1 > int(hi):
                # [QC][FailFast:anatomy_instance_id_overflow]
                # anatomy range를 넘는 fragment 수는 uint16 overflow가 아니어도 Task1 label
                # 의미를 오염시킨다. 해당 ROI는 실패 예측으로 기록한다.
                overflow_count = int(len(pred_ids))
                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                trace = dict(trace)
                trace.update({
                    "decoder_skipped": True,
                    "decoder_skipped_reason": "case_pred_fragment_id_exceeds_anatomy_range",
                    "anatomy": str(anatomy),
                    "anatomy_id_range": [int(lo), int(hi)],
                    "case_next_pred_id_before_roi": int(next_pred_id),
                    "roi_pred_fragment_count_before_skip": int(overflow_count),
                    "pred_fragment_count": 0,
                })
                pred_ids = []
            view = decoded_case[bbox]
            assigned_ids = []
            for pred_id in pred_ids:
                view[decoded_roi == int(pred_id)] = np.uint16(next_pred_id)
                assigned_ids.append(int(next_pred_id))
                next_pred_id += 1
            next_pred_id_by_anatomy[str(anatomy)] = int(next_pred_id)
            if pred_ids:
                trace = dict(trace)
                trace.update({
                    "assigned_case_instance_id_range": [int(assigned_ids[0]), int(assigned_ids[-1])],
                    "assigned_anatomy_id_range": [int(lo), int(hi)],
                })
            decoded_case[bbox] = view
            sample_metrics = None
            if int(trace["pred_fragment_count"]) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": sample,
                "anatomy": anatomy,
                "output_path": str(logits_path),
                "decoder_trace": trace,
                "fragment_metrics": sample_metrics,
                "probability_summary": probability_summary,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(sum(
            int(next_pred_id_by_anatomy[str(name)]) - int(lo)
            for name, (lo, _hi) in V5_ANATOMY_RANGES.items()
        ))
        prediction_path = None
        if pred_out_dir is not None:
            suffix = (
                "v268_no_contact_pairwise_softmax_mutex13_seed_healed_learned"
                if use_v268_no_contact_pairwise_decoder
                else "v266_pairwise_softmax_mutex13_seed_healed_learned"
                if use_v266_pairwise_softmax_decoder
                else "v260_seed_fracture_watershed_learned"
                if use_v260_seed_fracture_watershed_decoder
                else "v258_mutex13_seed_peak_healed_learned"
                if use_v258_seed_peak_decoder
                else "v257_mutex13_seed_union_healed_learned"
                if use_v257_seed_union_decoder
                else "v255_mutex13_seed_healed_learned"
                if int(predict_summary.get("output_channels", 0) or 0) == int(BFV3_MUTEX13_SEED_OUTPUT_CHANNELS)
                else "v253_affinity13_seed_healed_learned"
            )
            # [QA][Status:Required][Scope:visual_audit]
            # fulltrain gate는 JSON metric만으로 닫지 않는다. decoded MHA를 남겨
            # visualize.py case audit에서 over-split, missing anatomy, wire-like surface를
            # 확인할 수 있어야 한다.
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_{suffix}.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": total_pred_fragments,
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    def _proxy_value(key: str, fallback: float) -> float:
        value = proxy_summary.get(key)
        return float(fallback) if value is None else float(value)

    acceptance = {
        "dice_ge_0_90": bool(_proxy_value("dice_mean", 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool(_proxy_value("fracture_dice_proxy_mean", 0.0) >= 0.90),
        "local_dice_ge_0_90": bool(_proxy_value("local_dice_cfs_20mm_proxy_mean", 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool(_proxy_value("instance_f1_mean", 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool(_proxy_value("instance_recall_mean", 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool(_proxy_value("instance_precision_mean", 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(_proxy_value("merge_error_rate_mean", 1.0) <= 0.10),
        "split_error_rate_le_0_10": bool(_proxy_value("split_error_rate_mean", 1.0) <= 0.10),
        "topology_consistency_ge_0_90": bool(_proxy_value("topology_consistency_mean", 0.0) >= 0.90),
    }
    acceptance["v253_or_v255_or_v266_learned_fulltrain_gate_pass"] = bool(all(acceptance.values()))
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": "task1_v253_prediction_affinity13_seed_healed_eval",
        "target_contract": sorted(learned_contracts) if len(learned_contracts) != 1 else next(iter(learned_contracts)),
        "decoder": "task1_v253_or_v255_auto",
        "output_root": str(output_root),
        "roi_pad_vox": int(roi_pad_vox),
        "support_threshold": float(support_threshold),
        "seed_threshold": float(seed_threshold),
        "affinity_threshold": float(affinity_threshold),
        "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
        "decoder_joined_edge_cap": int(decoder_joined_edge_cap),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


def _task1_v261_fields_from_logits(raw_logits: np.ndarray) -> np.ndarray:
    """Convert V261 learned logits to decoder fields without corrupting offsets."""
    raw = np.asarray(raw_logits, dtype=np.float32)
    if raw.ndim != 4 or int(raw.shape[0]) != int(BFV3_CENTER_FLOW_OUTPUT_CHANNELS):
        raise ValueError(f"expected V261 logits [8,Z,Y,X], got {raw.shape}")
    fields = raw.astype(np.float32, copy=True)
    # [QC][Invariant:channel_activation]
    # V261 rows 0..4 are binary/logistic fields, but rows 5..7 are raw signed
    # voxel offsets. Applying sigmoid to offsets would destroy direction and make
    # Instance/Merge/Split/Topology metrics meaningless.
    fields[:5] = expit(fields[:5]).astype(np.float32, copy=False)
    return fields


def _task1_v267_no_contact_fields_from_logits(raw_logits: np.ndarray) -> np.ndarray:
    """Convert V267 5-channel no-contact logits to V262-compatible fields.

    [QC][Invariant:channel_order]
    V267 rows are 0 support, 1 center heatmap, 2..4 raw offsets. The decoder
    helper still expects the older 8-channel center-flow layout, so rows 1/2/4
    of that layout are filled with inert zeros and never used for promotion.
    """
    raw = np.asarray(raw_logits, dtype=np.float32)
    if raw.ndim != 4 or int(raw.shape[0]) != int(BFV3_NO_CONTACT_CENTER_FLOW_OUTPUT_CHANNELS):
        raise ValueError(f"expected V267 logits [5,Z,Y,X], got {raw.shape}")
    if not np.isfinite(raw).all():
        raise ValueError("V267 logits contain NaN/Inf")
    fields = np.zeros((int(BFV3_CENTER_FLOW_OUTPUT_CHANNELS), *raw.shape[1:]), dtype=np.float32)
    fields[TASK1_V261_CHANNELS["support"]] = expit(raw[0]).astype(np.float32, copy=False)
    fields[TASK1_V261_CHANNELS["center_heatmap"]] = expit(raw[1]).astype(np.float32, copy=False)
    fields[TASK1_V261_CHANNELS["offset_to_center_z"]] = raw[2].astype(np.float32, copy=False)
    fields[TASK1_V261_CHANNELS["offset_to_center_y"]] = raw[3].astype(np.float32, copy=False)
    fields[TASK1_V261_CHANNELS["offset_to_center_x"]] = raw[4].astype(np.float32, copy=False)
    # [METRIC][Scope:task1_primary_gate]
    # fracture/contact probability is intentionally unavailable. Fracture Dice proxy
    # is computed from final instance boundaries, not from a contact head.
    return fields


def run_task1_v261_prediction_eval(cases: list[str],
                                   out_path: Path,
                                   output_root: Path,
                                   *,
                                   roi_pad_vox: int = 24,
                                   support_threshold: float = 0.5,
                                   center_threshold: float = 0.5,
                                   peak_nms_size_vox: int = 31,
                                   offset_scale_vox: float = 64.0,
                                   max_vote_distance_vox: float | None = None,
                                   decoder_support_ratio_cap: float = 6.0,
                                   decoder_center_component_cap: int = 512,
                                   max_match_fragments: int = 300,
                                   pred_out_dir: Path | None = None,
                                   center_flow_variant: str = "v261") -> dict[str, Any]:
    """Decode learned V261 center-flow logits and compute Task1 proxy metrics.

    [METRIC][Risk:High][Scope:task1_official_proxy]
    Promotion/fulltrain 판단은 IoU-F가 아니라 Task1 official-aligned proxy
    Dice/Fracture Dice/Local Dice/HD95/ASSD/Instance F1/Recall/Precision,
    Merge/Split, Topology Consistency로 한다. IoU-F는 legacy diagnostic only다.
    """
    if output_root is None:
        raise ValueError("center-flow learned eval requires --output-root")
    if float(offset_scale_vox) <= 0.0:
        raise ValueError(f"offset_scale_vox must be > 0, got {offset_scale_vox}")
    if center_flow_variant not in {"v261", "v262", "v263", "v264", "v265", "v267"}:
        raise ValueError(
            "center_flow_variant must be 'v261', 'v262', 'v263', 'v264', 'v265', or 'v267', "
            f"got {center_flow_variant!r}"
        )
    if center_flow_variant in {"v262", "v263", "v264", "v265", "v267"} and (int(peak_nms_size_vox) < 1 or int(peak_nms_size_vox) % 2 == 0):
        raise ValueError(f"peak_nms_size_vox must be odd and >=1 for {center_flow_variant.upper()}, got {peak_nms_size_vox}")
    if max_vote_distance_vox is not None and float(max_vote_distance_vox) <= 0.0:
        raise ValueError(f"max_vote_distance_vox must be > 0 or None, got {max_vote_distance_vox}")
    if float(decoder_support_ratio_cap) <= 0.0:
        raise ValueError(f"decoder_support_ratio_cap must be > 0, got {decoder_support_ratio_cap}")
    if int(decoder_center_component_cap) < 1:
        raise ValueError(f"decoder_center_component_cap must be >= 1, got {decoder_center_component_cap}")

    predict_summary_path = output_root / "predict_summary.json"
    predict_summary = json.loads(predict_summary_path.read_text()) if predict_summary_path.exists() else {}
    summary_trainer = str(predict_summary.get("trainer", ""))
    expected_trainer_token = (
        "NoContactCenterHeatmapFlowV267"
        if center_flow_variant == "v267"
        else "TopologyConstrainedCenterHeatmapFlowCalibratedV265"
        if center_flow_variant == "v265"
        else "DenseCenterHeatmapFlowCalibratedV264"
        if center_flow_variant == "v264"
        else "CenterPeakFlowCalibratedV263"
        if center_flow_variant == "v263"
        else "CenterPeakFlowV262"
        if center_flow_variant == "v262"
        else "CenterFlowV261"
    )
    if summary_trainer and expected_trainer_token not in summary_trainer:
        raise ValueError(
            f"{center_flow_variant.upper()} eval requires {expected_trainer_token} logits, "
            f"predict_summary trainer={summary_trainer!r}"
    )
    decoder_name = (
        "task1_v267_no_contact_center_heatmap_flow"
        if center_flow_variant == "v267"
        else "task1_v265_topology_constrained_center_heatmap_flow_calibrated"
        if center_flow_variant == "v265"
        else "task1_v264_dense_center_heatmap_flow_calibrated"
        if center_flow_variant == "v264"
        else "task1_v263_center_peak_flow_calibrated"
        if center_flow_variant == "v263"
        else "task1_v262_center_peak_flow"
        if center_flow_variant == "v262"
        else "task1_v261_center_flow"
    )
    target_contract = (
        "task1_v267_learned_logits_no_contact_center_heatmap_flow_v1"
        if center_flow_variant == "v267"
        else "task1_v265_learned_logits_topology_constrained_center_heatmap_flow_calibrated_v1"
        if center_flow_variant == "v265"
        else "task1_v264_learned_logits_dense_center_heatmap_flow_calibrated_v1"
        if center_flow_variant == "v264"
        else "task1_v263_learned_logits_center_peak_flow_calibrated_v1"
        if center_flow_variant == "v263"
        else "task1_v262_learned_logits_center_peak_flow_v1"
        if center_flow_variant == "v262"
        else "task1_v261_learned_logits_center_flow_v1"
    )

    case_rows = []
    sample_rows = []
    for case in [str(c).zfill(3) for c in cases]:
        cd = find_case_dir(case)
        if cd is None:
            raise FileNotFoundError(f"source case not found: {case}")
        lbl_img = canonicalize_sitk(sitk.ReadImage(str(cd / "label.mha")))
        inst_full = sitk.GetArrayFromImage(lbl_img).astype(np.uint16, copy=False)
        spacing_zyx = tuple(float(v) for v in lbl_img.GetSpacing()[::-1])
        gt_case = np.where((inst_full >= 1) & (inst_full <= 150), inst_full, 0).astype(np.uint16, copy=False)
        decoded_case = np.zeros(inst_full.shape, dtype=np.uint16)
        # [QC][Invariant:task1_anatomy_id_range]
        # Task1 proxy metric과 visualize.py는 instance ID 범위(1..50/51..100/101..150)로
        # Sacrum/LeftHip/RightHip anatomy를 구분한다. ROI별 decoder가 1부터 시작하는
        # local ID를 내더라도 case volume에 붙일 때는 anatomy별 공식 범위를 보존해야
        # fracture proxy, topology audit, 시각화가 같은 의미를 공유한다.
        next_pred_id_by_anatomy = {
            str(name): int(lo)
            for name, (lo, _hi) in V5_ANATOMY_RANGES.items()
        }
        anatomy_traces = []
        for anatomy, (lo, hi) in V5_ANATOMY_RANGES.items():
            sample = f"PENGWIN_{case}_{anatomy}"
            anat_mask = anatomy_mask_from_instances(inst_full, anatomy)
            bbox = bbox_from_mask(anat_mask, pad_vox=roi_pad_vox)
            if bbox is None:
                continue
            inst_roi = np.where(
                (inst_full[bbox] >= int(lo)) & (inst_full[bbox] <= int(hi)),
                inst_full[bbox],
                0,
            ).astype(np.uint16, copy=False)
            gt_support_voxels = int((inst_roi > 0).sum())
            logits_path = output_root / f"{sample}.npz"
            raw_logits = _load_task1_v261_logits(logits_path)
            fields_pre = (
                _task1_v267_no_contact_fields_from_logits(raw_logits)
                if center_flow_variant == "v267"
                else _task1_v261_fields_from_logits(raw_logits)
            )

            restored_binary = _resize_channel_first_probabilities(fields_pre[:5], tuple(inst_roi.shape))
            support_pred_restored = restored_binary[TASK1_V261_CHANNELS["support"]] >= float(support_threshold)
            support_ratio = float(int(support_pred_restored.sum()) / max(1, gt_support_voxels))
            probability_summary = {
                "shape_before_restore": list(raw_logits.shape),
                "shape_binary_after_restore": list(restored_binary.shape),
                "support_mean": float(np.mean(restored_binary[TASK1_V261_CHANNELS["support"]])),
                "center_mean": float(np.mean(restored_binary[TASK1_V261_CHANNELS["center_heatmap"]])),
                "fracture_surface_mean": float(np.mean(restored_binary[TASK1_V261_CHANNELS["fracture_surface"]])),
                "support_voxels_restored": int(support_pred_restored.sum()),
                "gt_support_voxels": int(gt_support_voxels),
                "support_pred_gt_ratio": float(support_ratio),
            }
            if support_ratio > float(decoder_support_ratio_cap):
                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                trace = {
                    "decoder": decoder_name,
                    "decoder_skipped": True,
                    "decoder_skipped_reason": "restored_predicted_support_ratio_exceeds_cap",
                    "support_threshold": float(support_threshold),
                    "center_threshold": float(center_threshold),
                    "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
                    "support_voxels": int(support_pred_restored.sum()),
                    "gt_support_voxels": int(gt_support_voxels),
                    "support_pred_gt_ratio": float(support_ratio),
                    "pred_fragment_count": 0,
                }
            else:
                support_pre = fields_pre[TASK1_V261_CHANNELS["support"]] >= float(support_threshold)
                if center_flow_variant in {"v262", "v263", "v264", "v265", "v267"}:
                    peak_pre, peak_trace_pre = _task1_v262_peak_seed_mask(
                        fields_pre[TASK1_V261_CHANNELS["center_heatmap"]],
                        support_pre,
                        center_threshold=center_threshold,
                        peak_nms_size_vox=peak_nms_size_vox,
                    )
                    _center_cc_pre, center_n_pre = ndi.label(peak_pre)
                    probability_summary["source_peak_nms"] = peak_trace_pre
                else:
                    center_pre = (
                        fields_pre[TASK1_V261_CHANNELS["center_heatmap"]] >= float(center_threshold)
                    ) & support_pre
                    _center_cc_pre, center_n_pre = ndi.label(center_pre)
                if int(center_n_pre) > int(decoder_center_component_cap):
                    decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                    trace = {
                        "decoder": decoder_name,
                        "decoder_skipped": True,
                        "decoder_skipped_reason": "source_center_or_peak_components_exceed_cap",
                        "support_threshold": float(support_threshold),
                        "center_threshold": float(center_threshold),
                        "peak_nms_size_vox": int(peak_nms_size_vox) if center_flow_variant in {"v262", "v263", "v264", "v265", "v267"} else None,
                        "decoder_center_component_cap": int(decoder_center_component_cap),
                        "source_center_components": int(center_n_pre),
                        "support_pred_gt_ratio": float(support_ratio),
                        "pred_fragment_count": 0,
                    }
                    # [QC][FailFast:v261_center_component_explosion]
                    # 초기 checkpoint에서 center logit이 넓게 열리면 cKDTree assignment와
                    # fragment matching이 평가 시간을 장시간 점유한다. center 수 폭증은
                    # Task1 Instance Precision/Split/Topology 실패 그 자체이므로 빈 예측으로
                    # 기록하고 fulltrain gate를 통과시키지 않는다.
                else:
                    # [AUDIT][Risk:High][Scope:center_flow_coordinate_space]
                    # V261+ offset은 전처리된 voxel grid 단위로 학습된다. 먼저 predictor
                    # grid에서 decode하고, discrete label map만 nearest-neighbor로 원본 ROI
                    # shape에 복원한다. raw offset vector를 resize하면 좌표계가 섞여 Task1
                    # instance/topology metric이 깨진다.
                    if center_flow_variant in {"v262", "v263", "v264", "v265", "v267"}:
                        decoded_pre, trace = decode_task1_v262_center_peak_flow(
                            fields_pre,
                            (1.0, 1.0, 1.0),
                            support_threshold=support_threshold,
                            center_threshold=center_threshold,
                            peak_nms_size_vox=peak_nms_size_vox,
                            offset_scale_mm=offset_scale_vox,
                            max_vote_distance_mm=max_vote_distance_vox,
                        )
                    else:
                        decoded_pre, trace = decode_task1_v261_center_flow(
                            fields_pre,
                            (1.0, 1.0, 1.0),
                            support_threshold=support_threshold,
                            center_threshold=center_threshold,
                            offset_scale_mm=offset_scale_vox,
                            max_vote_distance_mm=max_vote_distance_vox,
                        )
                    decoded_roi = _resize_label_volume_nearest(decoded_pre, tuple(inst_roi.shape)).astype(np.uint16, copy=False)
                    trace = dict(trace)
                    trace.update({
                        "offset_unit": "preprocessed_voxel",
                        "offset_scale_vox": float(offset_scale_vox),
                        "max_vote_distance_vox": None if max_vote_distance_vox is None else float(max_vote_distance_vox),
                        "peak_nms_size_vox": int(peak_nms_size_vox) if center_flow_variant in {"v262", "v263", "v264", "v265", "v267"} else None,
                        "decoded_shape_before_restore": list(decoded_pre.shape),
                        "decoded_shape_after_restore": list(decoded_roi.shape),
                        "support_pred_gt_ratio": float(support_ratio),
                        "source_center_components": int(center_n_pre),
                        "decoder_center_component_cap": int(decoder_center_component_cap),
                    })
                    pred_count_after_restore = int(len([v for v in np.unique(decoded_roi) if int(v) > 0]))
                    trace["pred_fragment_count_after_restore"] = int(pred_count_after_restore)

            pred_ids = sorted(int(v) for v in np.unique(decoded_roi) if int(v) > 0)
            next_pred_id = int(next_pred_id_by_anatomy[str(anatomy)])
            if pred_ids and int(next_pred_id) + int(len(pred_ids)) - 1 > int(hi):
                decoded_roi = np.zeros_like(inst_roi, dtype=np.uint16)
                trace = dict(trace)
                trace.update({
                    "decoder_skipped": True,
                    "decoder_skipped_reason": "case_pred_fragment_id_exceeds_anatomy_range",
                    "anatomy": str(anatomy),
                    "anatomy_id_range": [int(lo), int(hi)],
                    "case_next_pred_id_before_roi": int(next_pred_id),
                    "roi_pred_fragment_count_before_skip": int(len(pred_ids)),
                    "pred_fragment_count": 0,
                })
                pred_ids = []
            view = decoded_case[bbox]
            assigned_ids = []
            for pred_id in pred_ids:
                view[decoded_roi == int(pred_id)] = np.uint16(next_pred_id)
                assigned_ids.append(int(next_pred_id))
                next_pred_id += 1
            next_pred_id_by_anatomy[str(anatomy)] = int(next_pred_id)
            if pred_ids:
                trace = dict(trace)
                trace.update({
                    "assigned_case_instance_id_range": [int(assigned_ids[0]), int(assigned_ids[-1])],
                    "assigned_anatomy_id_range": [int(lo), int(hi)],
                })
            decoded_case[bbox] = view
            sample_metrics = None
            if int(len(pred_ids)) <= int(max_match_fragments):
                sample_metrics = _fragment_matching_metrics_positive(inst_roi, decoded_roi)
            sample_row = {
                "case": case,
                "sample": sample,
                "anatomy": anatomy,
                "output_path": str(logits_path),
                "decoder_trace": trace,
                "fragment_metrics": sample_metrics,
                "probability_summary": probability_summary,
            }
            sample_rows.append(sample_row)
            anatomy_traces.append(sample_row)
        total_pred_fragments = int(sum(
            int(next_pred_id_by_anatomy[str(name)]) - int(lo)
            for name, (lo, _hi) in V5_ANATOMY_RANGES.items()
        ))
        prediction_path = None
        if pred_out_dir is not None:
            suffix = (
                "v267_no_contact_center_heatmap_flow_learned"
                if center_flow_variant == "v267"
                else "v265_topology_constrained_center_heatmap_flow_calibrated_learned"
                if center_flow_variant == "v265"
                else "v264_dense_center_heatmap_flow_calibrated_learned"
                if center_flow_variant == "v264"
                else "v263_center_peak_flow_calibrated_learned"
                if center_flow_variant == "v263"
                else "v262_center_peak_flow_learned"
                if center_flow_variant == "v262"
                else "v261_center_flow_learned"
            )
            prediction_path = str(pred_out_dir / f"PENGWIN_{case}_{suffix}.mha")
            _write_task1_prediction_mha(decoded_case, lbl_img, Path(prediction_path))
        case_fragment_metrics = None
        if total_pred_fragments <= int(max_match_fragments):
            case_fragment_metrics = _fragment_matching_metrics_positive(gt_case, decoded_case)
        task1_proxy = compute_task1_official_proxy_metrics(gt_case, decoded_case, spacing_zyx)
        case_rows.append({
            "case": case,
            "pred_fragment_count": total_pred_fragments,
            "gt_fragment_count": int(len([v for v in np.unique(gt_case) if int(v) > 0])),
            "fragment_metrics": case_fragment_metrics,
            "iou_f": None if case_fragment_metrics is None else case_fragment_metrics["official_style"]["mean_best_iou"],
            "matching_skipped": bool(case_fragment_metrics is None),
            "prediction_path": prediction_path,
            "task1_official_proxy": task1_proxy,
            "anatomy_traces": anatomy_traces,
        })

    iouf = [row["iou_f"] for row in case_rows if row["iou_f"] is not None]
    proxy_names = [
        "dice", "fracture_dice_proxy", "local_dice_cfs_20mm_proxy", "hd95_mm", "assd_mm",
        "instance_f1", "instance_recall", "instance_precision", "merge_error_rate",
        "split_error_rate", "topology_consistency",
    ]
    proxy_summary = {
        "metric_contract": "task1_official_aligned_proxy_v1",
        "official_score_reproducible": False,
        "mean_position_score": None,
    }
    for name in proxy_names:
        values = [row["task1_official_proxy"][name] for row in case_rows if row["task1_official_proxy"][name] is not None]
        proxy_summary[f"{name}_mean"] = float(np.mean(values)) if values else None
    def _proxy_value(key: str, fallback: float) -> float:
        value = proxy_summary.get(key)
        return float(fallback) if value is None else float(value)

    acceptance = {
        "dice_ge_0_90": bool(_proxy_value("dice_mean", 0.0) >= 0.90),
        "fracture_dice_ge_0_90": bool(_proxy_value("fracture_dice_proxy_mean", 0.0) >= 0.90),
        "local_dice_ge_0_90": bool(_proxy_value("local_dice_cfs_20mm_proxy_mean", 0.0) >= 0.90),
        "instance_f1_ge_0_90": bool(_proxy_value("instance_f1_mean", 0.0) >= 0.90),
        "instance_recall_ge_0_90": bool(_proxy_value("instance_recall_mean", 0.0) >= 0.90),
        "instance_precision_ge_0_90": bool(_proxy_value("instance_precision_mean", 0.0) >= 0.90),
        "merge_error_rate_le_0_10": bool(_proxy_value("merge_error_rate_mean", 1.0) <= 0.10),
        "split_error_rate_le_0_10": bool(_proxy_value("split_error_rate_mean", 1.0) <= 0.10),
        "topology_consistency_ge_0_90": bool(_proxy_value("topology_consistency_mean", 0.0) >= 0.90),
    }
    acceptance_key = (
        "v267_learned_fulltrain_gate_pass"
        if center_flow_variant == "v267"
        else "v265_learned_fulltrain_gate_pass"
        if center_flow_variant == "v265"
        else "v264_learned_fulltrain_gate_pass"
        if center_flow_variant == "v264"
        else "v263_learned_fulltrain_gate_pass"
        if center_flow_variant == "v263"
        else "v262_learned_fulltrain_gate_pass"
        if center_flow_variant == "v262"
        else "v261_learned_fulltrain_gate_pass"
    )
    acceptance[acceptance_key] = bool(all(acceptance.values()))
    result = {
        "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "task": (
            "task1_v267_prediction_no_contact_center_heatmap_flow_eval"
            if center_flow_variant == "v267"
            else "task1_v265_prediction_topology_constrained_center_heatmap_flow_calibrated_eval"
            if center_flow_variant == "v265"
            else "task1_v264_prediction_dense_center_heatmap_flow_calibrated_eval"
            if center_flow_variant == "v264"
            else "task1_v263_prediction_center_peak_flow_calibrated_eval"
            if center_flow_variant == "v263"
            else "task1_v262_prediction_center_peak_flow_eval"
            if center_flow_variant == "v262"
            else "task1_v261_prediction_center_flow_eval"
        ),
        "target_contract": target_contract,
        "decoder": decoder_name,
        "output_root": str(output_root),
        "roi_pad_vox": int(roi_pad_vox),
        "support_threshold": float(support_threshold),
        "center_threshold": float(center_threshold),
        "peak_nms_size_vox": int(peak_nms_size_vox) if center_flow_variant in {"v262", "v263", "v264", "v265", "v267"} else None,
        "offset_scale_vox": float(offset_scale_vox),
        "max_vote_distance_vox": None if max_vote_distance_vox is None else float(max_vote_distance_vox),
        "decoder_support_ratio_cap": float(decoder_support_ratio_cap),
        "decoder_center_component_cap": int(decoder_center_component_cap),
        "pred_out_dir": None if pred_out_dir is None else str(pred_out_dir),
        "summary": {
            "n_cases": int(len(case_rows)),
            "iou_f_mean": float(np.mean(iouf)) if iouf else None,
            "iou_f_min": float(np.min(iouf)) if iouf else None,
            "matching_skipped_cases": [row["case"] for row in case_rows if row["matching_skipped"]],
            "task1_official_proxy": proxy_summary,
            "acceptance": acceptance,
        },
        "cases": case_rows,
        "samples": sample_rows,
    }
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(_json_sanitize(result), indent=2, allow_nan=False))
    return result


